insert into public.parts(id,section_id,name,display_order) values('d92623be-4486-274c-996a-d38ca021bd64','2dd5a6ad-d4e5-5141-982e-22469816765f','Expression of Ideas',12) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('411965da-2d7e-a584-2fa1-ee7649525a5e','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to specify where Merian traveled to conduct her research. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Maria Sibylla Merian (1647–1717) was a German-born naturalist and artist.\n• In 1699, she traveled to Suriname to study insects and plants.\n• She documented the life cycles of butterflies and moths.\n• Her book Metamorphosis insectorum Surinamensium was published in 1705.\n• Its illustrations showed insects alongside the plants they feed on.","options":[{"id":"A","label":"Merian, a German-born naturalist, documented the life cycles of butterflies and moths."},{"id":"B","label":"Merian’s book Metamorphosis insectorum Surinamensium was published in 1705."},{"id":"C","label":"Merian’s illustrations showed insects alongside the plants they feed on."},{"id":"D","label":"In 1699, Merian traveled to Suriname to study insects and plants."}]}'::jsonb,1,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '411965da-2d7e-a584-2fa1-ee7649525a5e','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because it names the place Merian traveled to for her research, Suriname, which is exactly what the goal asks for. Choice A is incorrect because it describes what Merian documented but not where she went. Choice B is incorrect because it gives the title and date of her book, not a location. Choice C is incorrect because it describes her illustrations without mentioning where she did her research."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='411965da-2d7e-a584-2fa1-ee7649525a5e') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('292eb404-f4aa-d49e-92bc-b283429c4245','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to explain what happens to tardigrades when their environment dries out. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Tardigrades are microscopic animals, usually less than 1 millimeter long.\n• They are often called “water bears” because of their appearance and slow, lumbering walk.\n• They live in many habitats, including moss, soil, and ocean sediments.\n• When their surroundings dry out, they can enter a dormant state called a tun.\n• In this state, some tardigrades survive for years without water.","options":[{"id":"A","label":"Tardigrades, microscopic animals often called “water bears,” live in many habitats, including moss, soil, and ocean sediments, and are usually less than 1 millimeter long."},{"id":"B","label":"Tardigrades are often called “water bears” because of their appearance and slow, lumbering walk."},{"id":"C","label":"Tardigrades are microscopic animals that live in many different habitats."},{"id":"D","label":"When their surroundings dry out, tardigrades can enter a dormant state called a tun, in which some survive for years without water."}]}'::jsonb,2,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-002","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '292eb404-f4aa-d49e-92bc-b283429c4245','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because it explains what tardigrades do when their surroundings dry out: they enter a dormant state, a tun, in which some can survive for years. Choice A is incorrect because it gives their nickname, habitats, and size but says nothing about what happens when their surroundings dry out. Choice B is incorrect because it explains their nickname, not their response to dry conditions. Choice C is incorrect because it only introduces tardigrades in general terms."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='292eb404-f4aa-d49e-92bc-b283429c4245') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('aa8b6bfe-671d-558f-a562-d226d44e03ac','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to describe a construction technique used at Great Zimbabwe. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Great Zimbabwe is a ruined city in southeastern Zimbabwe.\n• It was built between roughly the eleventh and fifteenth centuries.\n• Its stone walls were constructed without mortar.\n• Its largest structure is known as the Great Enclosure.\n• The site was designated a UNESCO World Heritage Site in 1986.","options":[{"id":"A","label":"The builders of Great Zimbabwe constructed its stone walls without mortar."},{"id":"B","label":"Great Zimbabwe, a ruined city, was designated a UNESCO World Heritage Site in 1986."},{"id":"C","label":"The largest structure at Great Zimbabwe is known as the Great Enclosure."},{"id":"D","label":"Great Zimbabwe was built between roughly the eleventh and fifteenth centuries."}]}'::jsonb,3,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'aa8b6bfe-671d-558f-a562-d226d44e03ac','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because it describes how the walls were built, without mortar, which is a construction technique. Choice B is incorrect because it reports the site’s UNESCO status, not how it was built. Choice C is incorrect because it names a structure without describing a technique used to build it. Choice D is incorrect because it tells when the city was built, not how."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='aa8b6bfe-671d-558f-a562-d226d44e03ac') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e3b2f800-94dc-7567-55ae-29d9c01b6f8b','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to identify the series that includes The Great Wave off Kanagawa. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Katsushika Hokusai (1760–1849) was a Japanese artist.\n• He worked in ukiyo-e, a style of woodblock printing.\n• His series Thirty-Six Views of Mount Fuji was produced in the early 1830s.\n• The series includes the print The Great Wave off Kanagawa.\n• The Great Wave shows a towering wave above three boats, with Mount Fuji in the distance.","options":[{"id":"A","label":"Hokusai, who lived from 1760 to 1849, was a Japanese artist."},{"id":"B","label":"The Great Wave off Kanagawa shows a towering wave above three boats."},{"id":"C","label":"The Great Wave off Kanagawa is part of Hokusai’s series Thirty-Six Views of Mount Fuji."},{"id":"D","label":"Hokusai worked in ukiyo-e, a style of woodblock printing."}]}'::jsonb,4,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'e3b2f800-94dc-7567-55ae-29d9c01b6f8b','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because it names the series, Thirty-Six Views of Mount Fuji, to which The Great Wave off Kanagawa belongs. Choice A is incorrect because it gives Hokusai’s nationality and dates but no series. Choice B is incorrect because it describes what the print shows rather than the series it belongs to. Choice D is incorrect because it names an artistic style, ukiyo-e, not a series."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='e3b2f800-94dc-7567-55ae-29d9c01b6f8b') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('21d1db2e-d136-91e1-b1e5-43f5d6ead888','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to explain what information the duration of the waggle dance conveys. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Honeybee foragers that find food return to the hive.\n• There, they perform a movement called the waggle dance.\n• The angle of the dance relative to vertical indicates the direction of the food relative to the sun.\n• The duration of the waggle portion of the dance indicates the distance to the food.\n• Karl von Frisch, who studied the dance, shared a Nobel Prize in 1973.","options":[{"id":"A","label":"Karl von Frisch, who studied the waggle dance, shared a Nobel Prize in 1973."},{"id":"B","label":"The duration of the waggle portion of the dance tells other bees how far away the food is."},{"id":"C","label":"Honeybee foragers perform the waggle dance after returning to the hive."},{"id":"D","label":"When honeybee foragers return to the hive, they perform a waggle dance whose angle relative to vertical indicates the direction of the food relative to the sun."}]}'::jsonb,5,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-005","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '21d1db2e-d136-91e1-b1e5-43f5d6ead888','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because it states that the duration of the waggle portion communicates the distance to the food. Choice A is incorrect because it concerns the scientist who studied the dance, not what the dance conveys. Choice C is incorrect because it tells when the dance is performed, not what its duration means. Choice D is incorrect because it explains what the angle of the dance conveys (direction), not what the duration conveys."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='21d1db2e-d136-91e1-b1e5-43f5d6ead888') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('68bf6df7-5c88-2e3d-06ee-423fe5a4a5e6','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to indicate the genre and publication year of Their Eyes Were Watching God. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Zora Neale Hurston (1891–1960) was an American writer and anthropologist.\n• She studied anthropology at Barnard College with Franz Boas.\n• She collected African American folklore in Florida in the late 1920s.\n• Her folklore collection Mules and Men was published in 1935.\n• Her novel Their Eyes Were Watching God was published in 1937.","options":[{"id":"A","label":"Hurston’s folklore collection Mules and Men was published in 1935."},{"id":"B","label":"Hurston studied anthropology at Barnard College with Franz Boas."},{"id":"C","label":"Zora Neale Hurston, an American writer, lived from 1891 to 1960."},{"id":"D","label":"Their Eyes Were Watching God is a novel by Hurston that was published in 1937."}]}'::jsonb,6,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '68bf6df7-5c88-2e3d-06ee-423fe5a4a5e6','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because it gives both required details about Their Eyes Were Watching God: it is a novel (its genre), and it was published in 1937. Choice A is incorrect because it describes a different work, Mules and Men. Choice B is incorrect because it concerns Hurston’s education. Choice C is incorrect because it gives Hurston’s dates but says nothing about the novel."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='68bf6df7-5c88-2e3d-06ee-423fe5a4a5e6') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('03657133-3701-c308-fe75-9009b8ee94ec','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to describe what Lovelace’s 1843 notes contained. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Ada Lovelace (1815–1852) was an English mathematician.\n• She worked with Charles Babbage, who designed a machine called the Analytical Engine.\n• The Analytical Engine was never completed.\n• In 1843, Lovelace published notes on the machine.\n• Her notes included a method for calculating Bernoulli numbers with the machine.","options":[{"id":"A","label":"Lovelace’s 1843 notes on the Analytical Engine included a method for calculating Bernoulli numbers with the machine."},{"id":"B","label":"Charles Babbage designed the Analytical Engine, which was never completed."},{"id":"C","label":"Ada Lovelace, an English mathematician, worked with Charles Babbage."},{"id":"D","label":"Ada Lovelace lived from 1815 to 1852."}]}'::jsonb,7,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '03657133-3701-c308-fe75-9009b8ee94ec','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because it describes the content of the 1843 notes: a method for calculating Bernoulli numbers with the Analytical Engine. Choice B is incorrect because it is about Babbage’s machine, not Lovelace’s notes. Choice C is incorrect because it names Lovelace’s collaborator without describing the notes. Choice D is incorrect because it gives only her birth and death years."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='03657133-3701-c308-fe75-9009b8ee94ec') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2c55b877-a63f-6738-3f1b-2d5d00c24543','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to explain how mangroves help protect coastlines. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Mangroves are trees and shrubs that grow in coastal saltwater.\n• They are found mainly in tropical and subtropical regions.\n• Their tangled roots slow the movement of water.\n• This slowing allows sediment to settle and helps protect coastlines from erosion.\n• Mangrove forests also provide habitat for young fish.","options":[{"id":"A","label":"Mangroves, trees and shrubs that grow in coastal saltwater mainly in tropical and subtropical regions, form forests that provide habitat for young fish."},{"id":"B","label":"Mangrove forests provide habitat for young fish."},{"id":"C","label":"By slowing the movement of water, mangroves’ tangled roots allow sediment to settle, which helps protect coastlines from erosion."},{"id":"D","label":"Mangroves are trees and shrubs that grow in tropical regions."}]}'::jsonb,8,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '2c55b877-a63f-6738-3f1b-2d5d00c24543','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because it explains the mechanism: the roots slow the water, sediment settles, and coastlines are protected from erosion. Choice A is incorrect because it tells where mangroves grow and mentions a different benefit, habitat for fish, without explaining how they protect coastlines. Choice B is incorrect because it describes a different benefit, habitat for fish. Choice D is incorrect because it only defines mangroves."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='2c55b877-a63f-6738-3f1b-2d5d00c24543') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8660db55-ad5d-4ae0-347b-29c60bca6f7d','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to emphasize a similarity between the Atacama Desert and the McMurdo Dry Valleys. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• The Atacama Desert in Chile is one of the driest places on Earth.\n• It is a coastal desert located between the Pacific Ocean and the Andes Mountains.\n• Some weather stations there have recorded almost no rain for years at a time.\n• Antarctica’s McMurdo Dry Valleys also receive extremely little precipitation.\n• The Dry Valleys are cold deserts, with average temperatures well below freezing.","options":[{"id":"A","label":"The Atacama Desert is in Chile, whereas the McMurdo Dry Valleys are in Antarctica."},{"id":"B","label":"Both the Atacama Desert and the McMurdo Dry Valleys receive extremely little precipitation."},{"id":"C","label":"The Atacama Desert lies between the Pacific Ocean and the Andes Mountains."},{"id":"D","label":"The McMurdo Dry Valleys have average temperatures well below freezing."}]}'::jsonb,9,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-009","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '8660db55-ad5d-4ae0-347b-29c60bca6f7d','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because it states something the two places share: both receive extremely little precipitation. Choice A is incorrect because it emphasizes a difference in location rather than a similarity. Choice C is incorrect because it describes only the Atacama Desert. Choice D is incorrect because it describes only the Dry Valleys, and their cold temperatures are a way they differ from the Atacama rather than resemble it."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='8660db55-ad5d-4ae0-347b-29c60bca6f7d') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c6fca260-6f5b-7f05-7900-c124dd445ac2','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to emphasize the historical significance of Wheatley’s book. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Phillis Wheatley (c. 1753–1784) was born in West Africa and enslaved as a child.\n• She was brought to Boston in 1761.\n• She learned to read English, Latin, and Greek.\n• Her book Poems on Various Subjects, Religious and Moral was published in London in 1773.\n• It was the first book of poetry published by an African American woman.","options":[{"id":"A","label":"Wheatley’s book Poems on Various Subjects, Religious and Moral was published in London."},{"id":"B","label":"Phillis Wheatley was brought to Boston in 1761."},{"id":"C","label":"Phillis Wheatley learned to read English, Latin, and Greek."},{"id":"D","label":"Published in 1773, Wheatley’s Poems on Various Subjects, Religious and Moral was the first book of poetry published by an African American woman."}]}'::jsonb,10,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'c6fca260-6f5b-7f05-7900-c124dd445ac2','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because it explains why the book matters historically: it was the first book of poetry published by an African American woman. Choice A is incorrect because it gives the place of publication without any sign of the book’s significance. Choice B is incorrect because it concerns Wheatley’s arrival in Boston, not her book. Choice C is incorrect because it describes her learning, not the book’s historical importance."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='c6fca260-6f5b-7f05-7900-c124dd445ac2') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('546efaab-8a7b-8aa0-941a-be824cc94b1e','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to explain why the Rosetta Stone was useful for deciphering hieroglyphs. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• The Rosetta Stone was found in 1799 near the town of Rashid (Rosetta) in Egypt.\n• It is inscribed with the same decree in three scripts: hieroglyphic, Demotic, and ancient Greek.\n• Scholars could already read ancient Greek.\n• Jean-François Champollion used the stone to help decipher hieroglyphs, announcing his breakthrough in 1822.\n• The stone is now held by the British Museum in London.","options":[{"id":"A","label":"The Rosetta Stone, which was found in 1799 near the town of Rashid in Egypt and is inscribed in three scripts, is now held by the British Museum in London."},{"id":"B","label":"Jean-François Champollion announced his breakthrough in deciphering hieroglyphs in 1822."},{"id":"C","label":"Because the Rosetta Stone presents the same decree in hieroglyphic, Demotic, and ancient Greek, and scholars could already read Greek, the stone helped them decipher hieroglyphs."},{"id":"D","label":"The Rosetta Stone is inscribed with text in three different scripts."}]}'::jsonb,11,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '546efaab-8a7b-8aa0-941a-be824cc94b1e','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because it explains why the stone was useful: the same decree appears in three scripts, one of which, Greek, scholars could already read, so the Greek could serve as a key to the hieroglyphs. Choice A is incorrect because it gives the stone’s discovery and current location and mentions its three scripts, but it does not explain why the stone was useful. Choice B is incorrect because it reports when a breakthrough was announced without explaining why the stone made it possible. Choice D is incorrect because it mentions the three scripts but leaves out the crucial facts that the texts say the same thing and that Greek was readable."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='546efaab-8a7b-8aa0-941a-be824cc94b1e') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('88461e37-1e88-3aab-6777-fc559e7a2e75','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to identify two purposes of octopuses’ color changes. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Octopuses can change the color of their skin within a fraction of a second.\n• The changes are produced by cells called chromatophores.\n• Each chromatophore contains pigment and is surrounded by muscles.\n• When the muscles contract, the chromatophore expands and displays more color.\n• Octopuses use color changes for camouflage and communication.","options":[{"id":"A","label":"Octopuses use color changes for camouflage and communication."},{"id":"B","label":"Octopuses change color by using cells called chromatophores."},{"id":"C","label":"Each chromatophore contains pigment and is surrounded by muscles."},{"id":"D","label":"Octopuses can change their skin color within a fraction of a second."}]}'::jsonb,12,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '88461e37-1e88-3aab-6777-fc559e7a2e75','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because it names two purposes of color change: camouflage and communication. Choice B is incorrect because it explains how octopuses change color, not why. Choice C is incorrect because it describes the structure of a chromatophore. Choice D is incorrect because it describes how fast the change happens, not its purpose."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='88461e37-1e88-3aab-6777-fc559e7a2e75') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8fab5eba-451e-7f04-39d1-09db78eb3427','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to explain how Kahlo began painting. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Frida Kahlo (1907–1954) was a Mexican painter.\n• She was born in Coyoacán, a neighborhood of Mexico City.\n• She began painting while recovering from a bus accident in 1925.\n• About 55 of her roughly 140 paintings are self-portraits.\n• Her work often draws on Mexican folk art.","options":[{"id":"A","label":"Kahlo’s work often draws on Mexican folk art."},{"id":"B","label":"Kahlo began painting while she was recovering from a bus accident in 1925."},{"id":"C","label":"About 55 of Kahlo’s roughly 140 paintings are self-portraits."},{"id":"D","label":"Frida Kahlo was born in Coyoacán, a neighborhood of Mexico City."}]}'::jsonb,13,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-013","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '8fab5eba-451e-7f04-39d1-09db78eb3427','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because it describes the circumstances in which Kahlo started painting: while recovering from a 1925 bus accident. Choice A is incorrect because it describes an influence on her work, not how she began. Choice C is incorrect because it counts her self-portraits. Choice D is incorrect because it gives her birthplace, not the start of her painting."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='8fab5eba-451e-7f04-39d1-09db78eb3427') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('17f18a31-72fe-780b-58d3-8f344d7fdef6','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to explain why Pando is considered a single organism. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Pando is a grove of quaking aspen trees in Utah.\n• Although it looks like a forest, all of its roughly 47,000 stems grow from a single root system.\n• Genetic tests have shown that the stems are genetically identical.\n• Pando covers about 106 acres.\n• Scientists consider it one of the most massive known organisms.","options":[{"id":"A","label":"Pando, a grove of quaking aspen trees in Utah that covers about 106 acres, is considered by scientists to be one of the most massive known organisms."},{"id":"B","label":"Pando is a grove of quaking aspen trees that looks like a forest."},{"id":"C","label":"Pando’s roughly 47,000 stems all grow from a single root system and are genetically identical."},{"id":"D","label":"Scientists consider Pando one of the most massive known organisms."}]}'::jsonb,14,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-014","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '17f18a31-72fe-780b-58d3-8f344d7fdef6','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because it gives the reasons Pando counts as one organism: all of its stems share a single root system and are genetically identical. Choice A is incorrect because it gives Pando’s location and area and reports that scientists consider it a massive organism, but it gives no reason why it counts as a single organism. Choice B is incorrect because it notes that Pando looks like a forest, which if anything suggests many organisms. Choice D is incorrect because it states the conclusion that Pando is an organism without explaining why."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='17f18a31-72fe-780b-58d3-8f344d7fdef6') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1fd13f22-ed83-3628-7621-0fbf7327ede3','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to describe how messages were carried along the Inca roads. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• The Inca road system, called Qhapaq Ñan, stretched about 30,000 kilometers.\n• It connected parts of present-day Peru, Ecuador, Bolivia, Chile, Argentina, and Colombia.\n• Runners called chasquis carried messages along the roads in relays.\n• Rope bridges crossed deep river gorges.\n• The network was designated a UNESCO World Heritage Site in 2014.","options":[{"id":"A","label":"Runners called chasquis carried messages along the Inca roads in relays."},{"id":"B","label":"Rope bridges allowed the Inca roads to cross deep river gorges."},{"id":"C","label":"The Inca road system was designated a UNESCO World Heritage Site in 2014."},{"id":"D","label":"Stretching about 30,000 kilometers, the Inca road system connected parts of six present-day countries."}]}'::jsonb,15,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-015","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '1fd13f22-ed83-3628-7621-0fbf7327ede3','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because it explains how messages traveled: relay runners called chasquis carried them. Choice B is incorrect because it describes how roads crossed gorges, not how messages moved. Choice C is incorrect because it gives the network’s UNESCO status. Choice D is incorrect because it describes the size and reach of the network without mentioning messages."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='1fd13f22-ed83-3628-7621-0fbf7327ede3') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('cec2db56-486e-57e7-5aaf-4b722894c02f','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to describe the main activity of the Green Belt Movement. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Wangari Maathai (1940–2011) was a Kenyan environmental activist.\n• In 1977, she founded the Green Belt Movement.\n• The movement encouraged women to plant trees in their communities.\n• It has planted tens of millions of trees in Kenya.\n• In 2004, Maathai became the first African woman to receive the Nobel Peace Prize.","options":[{"id":"A","label":"In 2004, Maathai became the first African woman to receive the Nobel Peace Prize."},{"id":"B","label":"Wangari Maathai was a Kenyan environmental activist who lived from 1940 to 2011."},{"id":"C","label":"Maathai founded the Green Belt Movement in Kenya in 1977."},{"id":"D","label":"The Green Belt Movement, which Maathai founded in 1977, has encouraged women to plant trees in their communities."}]}'::jsonb,16,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-016","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'cec2db56-486e-57e7-5aaf-4b722894c02f','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because it describes what the Green Belt Movement does: it encourages women to plant trees in their communities. Choice A is incorrect because it concerns Maathai’s Nobel Prize. Choice B is incorrect because it introduces Maathai without describing the movement. Choice C is incorrect because it names the movement and its founding year but not its activity."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='cec2db56-486e-57e7-5aaf-4b722894c02f') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9448ff4b-b8b9-7b11-b56d-db02b376f1d3','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to emphasize a difference in appearance between cumulus and stratus clouds. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Cumulus clouds are puffy clouds with flat bases.\n• They often form on warm days when rising air cools.\n• Stratus clouds form flat, gray layers that can cover the whole sky.\n• Stratus clouds can produce light drizzle.\n• Both types are low clouds, usually with bases below 2,000 meters.","options":[{"id":"A","label":"Both cumulus and stratus clouds are low clouds, usually with bases below 2,000 meters."},{"id":"B","label":"Stratus clouds can produce light drizzle."},{"id":"C","label":"Cumulus clouds often form on warm days when rising air cools."},{"id":"D","label":"Whereas cumulus clouds are puffy with flat bases, stratus clouds form flat, gray layers that can cover the whole sky."}]}'::jsonb,17,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-017","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '9448ff4b-b8b9-7b11-b56d-db02b376f1d3','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because it contrasts how the two cloud types look: cumulus clouds are puffy, while stratus clouds form flat, gray layers. Choice A is incorrect because it emphasizes a similarity in height, not a difference in appearance. Choice B is incorrect because it describes what stratus clouds can produce and mentions only one type. Choice C is incorrect because it explains when cumulus clouds form, not how they differ in appearance from stratus clouds."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='9448ff4b-b8b9-7b11-b56d-db02b376f1d3') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f145b5c1-2a8c-5c03-ac5e-acca48dbea66','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to emphasize a similarity between Cassatt and Morisot. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Mary Cassatt (1844–1926) was an American painter who spent much of her career in France.\n• Berthe Morisot (1841–1895) was a French painter.\n• Both artists exhibited with the Impressionists in Paris.\n• Cassatt often painted scenes of mothers and children.\n• Morisot often painted domestic interiors and gardens.","options":[{"id":"A","label":"Cassatt was an American painter, while Morisot was French."},{"id":"B","label":"Cassatt often painted mothers and children, whereas Morisot often painted gardens."},{"id":"C","label":"Cassatt and Morisot both exhibited with the Impressionists in Paris."},{"id":"D","label":"Mary Cassatt, who lived from 1844 to 1926, spent much of her career in France."}]}'::jsonb,18,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-018","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'f145b5c1-2a8c-5c03-ac5e-acca48dbea66','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because it identifies something the two painters have in common: both exhibited with the Impressionists in Paris. Choice A is incorrect because it contrasts their nationalities. Choice B is incorrect because its “whereas” sets up a contrast between their subjects rather than a similarity. Choice D is incorrect because it describes only Cassatt."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='f145b5c1-2a8c-5c03-ac5e-acca48dbea66') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('12ddf988-191d-d317-d103-d592f08d7dce','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to introduce the Voynich manuscript to an audience unfamiliar with it. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• The Voynich manuscript is a handwritten book of about 240 pages.\n• Its text is written in an unknown script that no one has convincingly deciphered.\n• Radiocarbon dating places its parchment in the early fifteenth century.\n• It is named after Wilfrid Voynich, a book dealer who acquired it in 1912.\n• It is held at Yale University’s Beinecke Rare Book and Manuscript Library.","options":[{"id":"A","label":"Wilfrid Voynich, a book dealer, acquired the manuscript that bears his name in 1912."},{"id":"B","label":"The Voynich manuscript, a handwritten book of about 240 pages whose parchment has been dated to the early fifteenth century, is written in an unknown script that no one has convincingly deciphered."},{"id":"C","label":"Radiocarbon dating has placed the parchment of the Voynich manuscript in the early fifteenth century."},{"id":"D","label":"The Voynich manuscript is held at Yale University’s Beinecke Rare Book and Manuscript Library."}]}'::jsonb,19,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-019","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '12ddf988-191d-d317-d103-d592f08d7dce','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because it tells an unfamiliar reader what the manuscript is (a roughly 240-page handwritten book), how old its parchment is, and why it is notable (its undeciphered script). Choice A is incorrect because it concerns how the manuscript got its name and assumes the reader already knows what “the manuscript” is. Choice C is incorrect because it gives only a dating result without explaining what the manuscript is. Choice D is incorrect because it gives only the manuscript’s location."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='12ddf988-191d-d317-d103-d592f08d7dce') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a90a105a-494c-5482-e4a7-d6fc82cd3027','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to present the research question the researchers sought to answer. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Traffic noise in cities is concentrated at low sound frequencies.\n• Researchers wanted to know whether birds in cities sing at higher pitches than birds of the same species in nearby forests.\n• They recorded great tits in several cities and in forests near those cities.\n• City great tits sang songs with higher minimum frequencies than forest great tits did.\n• Higher-pitched songs may be easier to hear over low-frequency noise.","options":[{"id":"A","label":"City great tits sang songs with higher minimum frequencies than forest great tits did, possibly because higher-pitched songs are easier to hear over low-frequency traffic noise."},{"id":"B","label":"Because traffic noise is concentrated at low frequencies, higher-pitched songs may be easier to hear in cities."},{"id":"C","label":"The researchers recorded great tits both in several cities and in nearby forests."},{"id":"D","label":"The researchers sought to determine whether birds in cities sing at higher pitches than birds of the same species in nearby forests."}]}'::jsonb,20,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-020","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'a90a105a-494c-5482-e4a7-d6fc82cd3027','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because it states the question the study was designed to answer: whether city birds sing at higher pitches than forest birds of the same species. Choice A is incorrect because it reports the study’s finding and a possible explanation for it, not the question the study set out to answer. Choice B is incorrect because it offers a possible explanation for the finding. Choice C is incorrect because it describes the study’s method."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='a90a105a-494c-5482-e4a7-d6fc82cd3027') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('acc1547d-c33c-95f1-e8ba-16ea534dba9c','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to emphasize that the crow’s behavior in the experiment was not the result of training. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• New Caledonian crows live on islands in the South Pacific.\n• In the wild, they use twigs and leaves as tools to pull insect larvae out of holes in wood.\n• Some of the crows shape twigs into hooks.\n• In one experiment, a crow given a straight piece of wire bent it into a hook to lift a small bucket of food out of a tube.\n• The crow had not been trained to bend wire.","options":[{"id":"A","label":"In one experiment, a crow bent a straight wire into a hook to retrieve food from a tube, even though it had never been trained to bend wire."},{"id":"B","label":"New Caledonian crows use twigs and leaves to pull insect larvae out of holes in wood."},{"id":"C","label":"Some New Caledonian crows, which live on South Pacific islands, shape twigs into hooks."},{"id":"D","label":"In one experiment, a crow used a piece of wire to lift a small bucket of food out of a tube."}]}'::jsonb,21,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-021","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'acc1547d-c33c-95f1-e8ba-16ea534dba9c','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because it describes the experiment and explicitly states that the crow had not been trained to bend wire. Choice B is incorrect because it describes the crows’ ordinary tool use in the wild, not the experiment. Choice C is incorrect because it describes hook-making with twigs and says nothing about training. Choice D is incorrect because it describes the experiment but omits the key point that the behavior was untrained."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='acc1547d-c33c-95f1-e8ba-16ea534dba9c') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('33a52560-4a5c-29ea-9190-b568481b7257','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to compare the depths of the two trenches. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• The Mariana Trench, in the Pacific Ocean, reaches a depth of about 10,900 meters.\n• It is the deepest known point in Earth’s oceans.\n• The Puerto Rico Trench is the deepest point in the Atlantic Ocean.\n• It reaches a depth of about 8,400 meters.\n• Both trenches formed where one tectonic plate sinks beneath another.","options":[{"id":"A","label":"Both the Mariana Trench and the Puerto Rico Trench formed where one tectonic plate sinks beneath another."},{"id":"B","label":"The Puerto Rico Trench, which reaches about 8,400 meters, is the deepest point in the Atlantic Ocean."},{"id":"C","label":"At about 10,900 meters deep, the Mariana Trench is roughly 2,500 meters deeper than the Puerto Rico Trench, which reaches about 8,400 meters."},{"id":"D","label":"The Mariana Trench is in the Pacific Ocean, whereas the Puerto Rico Trench is in the Atlantic Ocean."}]}'::jsonb,22,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-022","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '33a52560-4a5c-29ea-9190-b568481b7257','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because it gives both depths and states the difference between them (10,900 − 8,400 = 2,500 meters). Choice A is incorrect because it compares how the trenches formed, not their depths. Choice B is incorrect because it gives the depth of only one trench. Choice D is incorrect because it compares the trenches’ locations rather than their depths."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='33a52560-4a5c-29ea-9190-b568481b7257') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0380fc67-6934-a0d4-1a4b-946ecf0a41ab','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to explain why some Roman harbor structures have lasted so long. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Ancient Roman builders made concrete with lime, water, and volcanic ash.\n• Some Roman harbor structures have survived in seawater for about 2,000 years.\n• Modern concrete exposed to seawater often begins to crumble within decades.\n• Researchers have found that seawater reacts with the volcanic ash in Roman concrete to form new minerals.\n• These minerals strengthen the concrete over time.","options":[{"id":"A","label":"Roman concrete was made with lime, water, and volcanic ash, while modern concrete often crumbles in seawater within decades."},{"id":"B","label":"Roman harbor structures have lasted because seawater reacts with the volcanic ash in their concrete, forming minerals that strengthen it over time."},{"id":"C","label":"Some Roman harbor structures have survived in seawater for about 2,000 years."},{"id":"D","label":"Researchers have studied Roman concrete, which was made with lime, water, and volcanic ash."}]}'::jsonb,23,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-023","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '0380fc67-6934-a0d4-1a4b-946ecf0a41ab','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because it gives the reason for the structures’ durability: seawater reacts with the volcanic ash to form strengthening minerals. Choice A is incorrect because it contrasts ingredients and outcomes without explaining what causes the Roman concrete to last. Choice C is incorrect because it states that the structures have lasted but not why. Choice D is incorrect because it notes that the concrete has been studied and lists its ingredients but does not explain its longevity."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='0380fc67-6934-a0d4-1a4b-946ecf0a41ab') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c6aed97c-d908-6322-1648-ce90129a3551','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to emphasize a similarity in how the two travelers’ accounts were produced. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Marco Polo, a merchant from Venice, traveled across Asia between 1271 and 1295.\n• His account of the journey was written down by Rustichello da Pisa, a writer he met in prison.\n• Ibn Battuta, a scholar from Morocco, traveled across Africa, the Middle East, and Asia between 1325 and 1354.\n• His account, known as the Rihla, was written down by the scholar Ibn Juzayy.\n• Ibn Battuta’s travels covered a much greater distance than Polo’s.","options":[{"id":"A","label":"Ibn Battuta’s travels covered a much greater distance than those of Marco Polo."},{"id":"B","label":"Marco Polo traveled between 1271 and 1295, and Ibn Battuta traveled between 1325 and 1354."},{"id":"C","label":"Ibn Battuta’s account, known as the Rihla, was written down by the scholar Ibn Juzayy."},{"id":"D","label":"Both Marco Polo and Ibn Battuta had the accounts of their journeys written down by someone else: Rustichello da Pisa and Ibn Juzayy, respectively."}]}'::jsonb,24,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-024","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'c6aed97c-d908-6322-1648-ce90129a3551','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because it identifies a shared feature of how the accounts were produced: each traveler’s account was written down by another person. Choice A is incorrect because it emphasizes a difference in distance traveled. Choice B is incorrect because it gives the dates of the journeys, which concern when they traveled, not how the accounts were produced. Choice C is incorrect because it describes only Ibn Battuta’s account, so it cannot show a similarity."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='c6aed97c-d908-6322-1648-ce90129a3551') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('490bd90a-aedf-12fb-a365-fe368b28def3','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to explain why observing in infrared light helps JWST study very distant galaxies. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• The James Webb Space Telescope (JWST) launched in December 2021.\n• It observes mainly in infrared light.\n• Infrared light can pass through clouds of dust that block visible light.\n• As the universe expands, light from very distant galaxies is stretched to longer, infrared wavelengths.\n• JWST’s primary mirror is 6.5 meters across.","options":[{"id":"A","label":"Because light from very distant galaxies has been stretched to infrared wavelengths as the universe expands, JWST’s infrared instruments can detect that light."},{"id":"B","label":"Infrared light can pass through clouds of dust that block visible light."},{"id":"C","label":"JWST, which launched in December 2021, has a primary mirror 6.5 meters across."},{"id":"D","label":"JWST observes mainly in infrared light rather than visible light."}]}'::jsonb,25,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-025","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '490bd90a-aedf-12fb-a365-fe368b28def3','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because it connects infrared observation to distant galaxies specifically: their light arrives stretched to infrared wavelengths, so an infrared telescope can detect it. Choice B is incorrect because, although it names a real advantage of infrared light, that advantage concerns dust clouds, not the distance of galaxies. Choice C is incorrect because it gives the launch date and mirror size, not a reason infrared helps. Choice D is incorrect because it states that JWST observes in infrared without explaining why that helps with distant galaxies."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='490bd90a-aedf-12fb-a365-fe368b28def3') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e083b60e-d112-a3cb-d74c-63e12dcff269','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to challenge a common assumption about sharks. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Many people assume that all sharks must keep swimming in order to breathe.\n• Some shark species, such as great white sharks, rely on swimming to push water over their gills.\n• Other species, such as nurse sharks, can pump water over their gills while resting on the seafloor.\n• Nurse sharks are often found resting in groups during the day.","options":[{"id":"A","label":"Great white sharks rely on swimming to push water over their gills."},{"id":"B","label":"Nurse sharks are often found resting in groups during the day."},{"id":"C","label":"Although many people assume that all sharks must keep swimming to breathe, nurse sharks can pump water over their gills while resting on the seafloor."},{"id":"D","label":"Many people assume that all sharks must keep swimming to breathe, and some species do rely on swimming to move water over their gills."}]}'::jsonb,26,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-026","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'e083b60e-d112-a3cb-d74c-63e12dcff269','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because it states the common assumption and then gives evidence against it: nurse sharks can breathe while resting. Choice A is incorrect because the behavior of great white sharks is consistent with the assumption rather than a challenge to it. Choice B is incorrect because it mentions resting nurse sharks but neither states the assumption nor explains how they breathe while still. Choice D is incorrect because it supports the assumption instead of challenging it."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='e083b60e-d112-a3cb-d74c-63e12dcff269') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f5457d98-fbee-a97e-6b6d-6f3af7f24f47','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to explain how researchers build long tree-ring timelines. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Dendrochronology is the study of tree rings to date past events.\n• Trees in temperate climates usually add one growth ring each year.\n• Rings are wider in years with favorable growing conditions and narrower in dry or cold years.\n• By matching ring patterns across many trees, including ancient timbers, researchers can build timelines thousands of years long.\n• Such timelines are used to date wooden objects and buildings.","options":[{"id":"A","label":"Tree-ring timelines are used to date wooden objects and buildings."},{"id":"B","label":"Researchers build timelines thousands of years long by matching the patterns of wide and narrow rings across many trees, including ancient timbers."},{"id":"C","label":"Because trees in temperate climates usually add one ring each year, with wider rings in favorable years and narrower rings in dry or cold years, tree rings can be used to date past events."},{"id":"D","label":"Dendrochronology is the study of tree rings to date past events."}]}'::jsonb,27,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-027","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'f5457d98-fbee-a97e-6b6d-6f3af7f24f47','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because it describes the process for building long timelines: matching ring patterns across many trees, including ancient timbers. Choice A is incorrect because it describes a use of the timelines, not how they are built. Choice C is incorrect because it explains why tree rings can be used for dating, but not how researchers combine ring patterns from many trees into long timelines. Choice D is incorrect because it only defines the field."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='f5457d98-fbee-a97e-6b6d-6f3af7f24f47') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c7cf0495-7588-ac64-4309-4bdec7086336','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to describe The Block to an audience unfamiliar with Bearden. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Romare Bearden (1911–1988) was an African American artist.\n• He is best known for his collages, which combine cut paper, photographs, and paint.\n• In 1964, he created a series of photomontages called Projections.\n• His 1971 collage The Block depicts a street in Harlem, New York.","options":[{"id":"A","label":"In 1964, Bearden created a series of photomontages called Projections."},{"id":"B","label":"Bearden’s 1971 work The Block depicts a street in Harlem."},{"id":"C","label":"Romare Bearden, who lived from 1911 to 1988, is best known for his collages."},{"id":"D","label":"The Block, a 1971 collage by the African American artist Romare Bearden, depicts a street in Harlem, New York."}]}'::jsonb,28,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-028","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'c7cf0495-7588-ac64-4309-4bdec7086336','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because it describes The Block (a 1971 collage depicting a Harlem street) and identifies Bearden for a reader who does not know him. Choice A is incorrect because it describes a different work, Projections. Choice B is incorrect because it describes The Block but gives no information about who Bearden is, which an unfamiliar audience would need. Choice C is incorrect because it introduces Bearden but does not describe The Block."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='c7cf0495-7588-ac64-4309-4bdec7086336') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5fe711ed-0b21-e798-4f4d-5cba0d5cda33','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to emphasize the size of the Great Barrier Reef. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• The Great Barrier Reef lies off the coast of Queensland, Australia.\n• It is made up of nearly 3,000 individual reefs.\n• It stretches for more than 2,300 kilometers.\n• It is the world’s largest coral reef system.\n• Rising ocean temperatures have caused several mass coral bleaching events there since 1998.","options":[{"id":"A","label":"The Great Barrier Reef lies off the coast of Queensland, Australia."},{"id":"B","label":"Made up of nearly 3,000 individual reefs stretching for more than 2,300 kilometers, the Great Barrier Reef is the world’s largest coral reef system."},{"id":"C","label":"Rising ocean temperatures have caused several mass bleaching events on the Great Barrier Reef since 1998."},{"id":"D","label":"The Great Barrier Reef, which lies off the coast of Queensland, Australia, is made up of individual reefs."}]}'::jsonb,29,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-029","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '5fe711ed-0b21-e798-4f4d-5cba0d5cda33','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because it emphasizes size with three relevant details: the number of reefs, the length of the system, and its status as the world’s largest. Choice A is incorrect because it gives only the reef’s location. Choice C is incorrect because it describes a threat to the reef, not its size. Choice D is incorrect because it mentions that the reef is made up of individual reefs but omits how many and how far they stretch."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='5fe711ed-0b21-e798-4f4d-5cba0d5cda33') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d5dda6fb-b90c-458c-77d1-8b2341dbd906','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to emphasize the economic impact of Mansa Musa’s pilgrimage. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Mansa Musa ruled the Mali Empire in the early fourteenth century.\n• In 1324, he made a pilgrimage to Mecca.\n• He traveled with a large caravan carrying great quantities of gold.\n• His spending and gifts in Cairo are reported to have lowered the value of gold there for years.\n• The Catalan Atlas of 1375 depicts Mansa Musa holding a gold nugget.","options":[{"id":"A","label":"During his 1324 pilgrimage to Mecca, Mansa Musa spent and gave away so much gold in Cairo that the value of gold there is reported to have fallen for years."},{"id":"B","label":"The Catalan Atlas of 1375 depicts Mansa Musa holding a gold nugget."},{"id":"C","label":"Mansa Musa, who ruled the Mali Empire in the early fourteenth century, made a pilgrimage to Mecca in 1324."},{"id":"D","label":"Mansa Musa, who ruled the Mali Empire in the early fourteenth century, traveled to Mecca in 1324 with a large caravan carrying great quantities of gold."}]}'::jsonb,30,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-030","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'd5dda6fb-b90c-458c-77d1-8b2341dbd906','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because it describes an economic effect of the pilgrimage: Mansa Musa’s spending reportedly lowered the value of gold in Cairo for years. Choice B is incorrect because it describes a later map, not an economic impact. Choice C is incorrect because it gives the date of the pilgrimage without any effect. Choice D is incorrect because it mentions the gold he carried but not what his spending did to the economy."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='d5dda6fb-b90c-458c-77d1-8b2341dbd906') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3ae5f5af-469c-138b-fa52-948499790026','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to explain why reflective coatings can help reduce the urban heat island effect. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Cities are often warmer than surrounding rural areas, an effect called the urban heat island.\n• Dark surfaces such as asphalt absorb sunlight and release it as heat.\n• Some cities have painted roofs and pavements with reflective coatings.\n• Reflective surfaces absorb less sunlight than dark surfaces do.\n• Trees cool streets by providing shade and releasing water vapor.","options":[{"id":"A","label":"Trees cool city streets by providing shade and releasing water vapor."},{"id":"B","label":"Cities are often warmer than surrounding rural areas, an effect called the urban heat island."},{"id":"C","label":"Because reflective surfaces absorb less sunlight than dark surfaces like asphalt, which absorb sunlight and release it as heat, reflective coatings on roofs and pavements can help reduce the urban heat island effect."},{"id":"D","label":"Some cities have painted their roofs and pavements with reflective coatings."}]}'::jsonb,31,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-031","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '3ae5f5af-469c-138b-fa52-948499790026','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because it explains the reasoning: dark surfaces absorb sunlight and release heat, while reflective coatings absorb less sunlight, so they can reduce the heat island effect. Choice A is incorrect because it describes a different cooling strategy, trees. Choice B is incorrect because it defines the effect without explaining how coatings help. Choice D is incorrect because it reports that some cities use the coatings but not why they work."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='3ae5f5af-469c-138b-fa52-948499790026') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2256a3d3-b975-b88b-407d-ea9e6abc9328','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to emphasize how little of Dickinson’s work was published while she was alive. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Emily Dickinson (1830–1886) was an American poet.\n• She wrote nearly 1,800 poems.\n• Fewer than a dozen of them were published during her lifetime.\n• Her poems often use dashes and unconventional capitalization.\n• After her death, her sister Lavinia found the poems and sought to have them published.","options":[{"id":"A","label":"Dickinson’s poems often use dashes and unconventional capitalization."},{"id":"B","label":"After Dickinson’s death, her sister Lavinia found her poems and sought to have them published."},{"id":"C","label":"Emily Dickinson, an American poet who lived from 1830 to 1886, wrote nearly 1,800 poems, which often use dashes and unconventional capitalization."},{"id":"D","label":"Although Dickinson wrote nearly 1,800 poems, fewer than a dozen were published during her lifetime."}]}'::jsonb,32,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-032","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '2256a3d3-b975-b88b-407d-ea9e6abc9328','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because it sets the small number of poems published in her lifetime (fewer than a dozen) against the large number she wrote (nearly 1,800), emphasizing how little appeared while she was alive. Choice A is incorrect because it describes features of her style. Choice B is incorrect because it concerns publication efforts after her death and does not say how few poems appeared during her life. Choice C is incorrect because it gives the total number of poems and describes their style but says nothing about publication."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='2256a3d3-b975-b88b-407d-ea9e6abc9328') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('fcb08417-cbc0-4215-63bc-ed8d91b28da4','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to emphasize that Curie’s achievement was unprecedented. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Marie Curie won the Nobel Prize in Physics in 1903, sharing it with Pierre Curie and Henri Becquerel.\n• She won the Nobel Prize in Chemistry in 1911.\n• The 1911 prize recognized her discovery of the elements polonium and radium.\n• She was the first person to win Nobel Prizes in two different sciences.\n• Linus Pauling later won two Nobel Prizes, one in Chemistry and one for Peace.","options":[{"id":"A","label":"Curie shared the 1903 Nobel Prize in Physics with Pierre Curie and Henri Becquerel."},{"id":"B","label":"By winning the 1903 Nobel Prize in Physics and the 1911 Nobel Prize in Chemistry, Marie Curie became the first person to win Nobel Prizes in two different sciences."},{"id":"C","label":"Curie’s 1911 Nobel Prize in Chemistry recognized her discovery of polonium and radium."},{"id":"D","label":"Like Linus Pauling, who won Nobel Prizes in Chemistry and for Peace, Curie won two Nobel Prizes."}]}'::jsonb,33,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-033","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'fcb08417-cbc0-4215-63bc-ed8d91b28da4','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because it states that Curie was the first person to win Nobel Prizes in two different sciences, which shows that her achievement had no precedent. Choice A is incorrect because it describes a shared prize and gives no sign that anything was unprecedented. Choice C is incorrect because it explains what one prize recognized. Choice D is incorrect because it likens Curie to another winner, which undercuts rather than emphasizes the uniqueness of her achievement."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='fcb08417-cbc0-4215-63bc-ed8d91b28da4') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('57c61031-a52b-ba7b-cf0d-ff6da784535c','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to explain a connection between gamelan and Western classical music. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Gamelan is a type of ensemble music from Indonesia, especially the islands of Java and Bali.\n• A gamelan ensemble consists mainly of bronze percussion instruments such as gongs and metallophones.\n• The instruments of a gamelan are tuned to one another and are usually not played with instruments from another set.\n• French composer Claude Debussy heard gamelan music at the Paris Exposition of 1889.\n• Scholars have linked features of Debussy’s later piano music to that experience.","options":[{"id":"A","label":"The instruments of a gamelan are tuned to one another and are usually not played with instruments from another set."},{"id":"B","label":"Gamelan, a type of ensemble music from Indonesia, consists mainly of bronze percussion instruments."},{"id":"C","label":"Scholars have linked features of French composer Claude Debussy’s later piano music to his experience of hearing gamelan at the Paris Exposition of 1889."},{"id":"D","label":"Gamelan music comes especially from the Indonesian islands of Java and Bali."}]}'::jsonb,34,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-034","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '57c61031-a52b-ba7b-cf0d-ff6da784535c','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because it connects gamelan to Western classical music through Debussy, whose later piano music scholars have linked to hearing gamelan in 1889. Choice A is incorrect because it describes how gamelan instruments are tuned, without any link to Western music. Choice B is incorrect because it describes gamelan’s instruments only. Choice D is incorrect because it gives gamelan’s geographic origins only."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='57c61031-a52b-ba7b-cf0d-ff6da784535c') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('eff8e55a-31e4-5968-f54a-d18eadb2e504','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to emphasize a similarity in the design of the two bridges. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• The Golden Gate Bridge in San Francisco opened in 1937.\n• Its main span is about 1,280 meters long.\n• The Akashi Kaikyō Bridge in Japan opened in 1998.\n• Its central span is about 1,991 meters long.\n• Both are suspension bridges, in which the deck hangs from cables strung between towers.","options":[{"id":"A","label":"The Golden Gate Bridge and the Akashi Kaikyō Bridge are both suspension bridges, with decks that hang from cables strung between towers."},{"id":"B","label":"The central span of the Akashi Kaikyō Bridge is about 711 meters longer than the main span of the Golden Gate Bridge."},{"id":"C","label":"The Golden Gate Bridge opened in 1937, and the Akashi Kaikyō Bridge opened in 1998."},{"id":"D","label":"The Akashi Kaikyō Bridge, which opened in Japan in 1998, has a central span about 1,991 meters long."}]}'::jsonb,35,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-035","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'eff8e55a-31e4-5968-f54a-d18eadb2e504','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because it identifies a shared design feature: both are suspension bridges whose decks hang from cables between towers. Choice B is incorrect because it emphasizes a difference in span length. Choice C is incorrect because it gives opening dates, which concern history rather than design and show a difference. Choice D is incorrect because it describes only one bridge."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='eff8e55a-31e4-5968-f54a-d18eadb2e504') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('93b631df-0d87-ef9e-4612-244f50487f56','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to explain why Arctic terns experience so much daylight. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Arctic terns breed in the Arctic during the northern summer.\n• They spend the northern winter near Antarctica, where it is summer.\n• Tracking devices have shown that some terns fly more than 70,000 kilometers in a year.\n• Arctic terns may live for 30 years or more.\n• Because of their migration, Arctic terns are thought to experience more daylight than any other animal.","options":[{"id":"A","label":"Tracking devices have shown that some Arctic terns fly more than 70,000 kilometers in a single year."},{"id":"B","label":"Arctic terns may live for 30 years or more."},{"id":"C","label":"Tracking devices have shown that some Arctic terns, which breed in the Arctic during the northern summer and may live for 30 years or more, fly more than 70,000 kilometers in a year."},{"id":"D","label":"By breeding in the Arctic during the northern summer and spending the northern winter near Antarctica, where it is summer, Arctic terns are thought to experience more daylight than any other animal."}]}'::jsonb,36,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-036","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '93b631df-0d87-ef9e-4612-244f50487f56','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because it explains the cause of the terns’ extra daylight: they spend both halves of the year in the summer of one polar region or the other. Choice A is incorrect because it gives the distance the terns fly without connecting it to daylight. Choice B is incorrect because it gives their life span. Choice C is incorrect because, although it mentions that the terns breed in the Arctic during the northern summer, it leaves out that they spend the northern winter in the Antarctic summer, so it does not explain why they experience so much daylight; its focus is distance and life span."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='93b631df-0d87-ef9e-4612-244f50487f56') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('57416cd0-b8b8-1294-ad4f-0bc3287606ab','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to emphasize both the natural source of CRISPR-Cas9 and one of its practical uses. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• CRISPR-Cas9 is a tool that allows scientists to cut DNA at specific locations.\n• It was adapted from a defense system that bacteria use against viruses.\n• Jennifer Doudna and Emmanuelle Charpentier described the tool in a 2012 paper.\n• They received the 2020 Nobel Prize in Chemistry for this work.\n• Scientists have used CRISPR-Cas9 to develop crops that resist certain diseases.","options":[{"id":"A","label":"Doudna and Charpentier, who described CRISPR-Cas9 in a 2012 paper, received the 2020 Nobel Prize in Chemistry."},{"id":"B","label":"CRISPR-Cas9, which allows scientists to cut DNA at specific locations, has been used to develop crops that resist certain diseases."},{"id":"C","label":"CRISPR-Cas9 was adapted from a defense system that bacteria use against viruses, and its developers received the 2020 Nobel Prize in Chemistry."},{"id":"D","label":"Adapted from a defense system that bacteria use against viruses, CRISPR-Cas9 has been used to develop crops that resist certain diseases."}]}'::jsonb,37,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-037","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '57416cd0-b8b8-1294-ad4f-0bc3287606ab','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because it meets both parts of the goal: it names the natural source of the tool (a bacterial defense system) and a practical use (disease-resistant crops). Choice A is incorrect because it mentions neither the natural source nor a practical use. Choice B is incorrect because it gives a practical use but replaces the natural source with a description of what the tool does. Choice C is incorrect because it gives the natural source but replaces the practical use with the Nobel Prize, which is recognition, not a use."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='57416cd0-b8b8-1294-ad4f-0bc3287606ab') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('163615bd-a5d3-29d7-42c9-e99896a645dd','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to explain why the 2016 survey was able to reveal structures that had not been recorded before. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Lidar is a remote-sensing method that uses laser pulses to measure distances to the ground.\n• It can detect ground features hidden beneath dense forest canopy.\n• In 2016, researchers used aircraft-mounted lidar to survey more than 2,100 square kilometers of forest in northern Guatemala.\n• The survey revealed tens of thousands of previously unrecorded Maya structures, including houses, causeways, and defensive walls.\n• The survey took a fraction of the time that mapping the area on foot would have required.","options":[{"id":"A","label":"In 2016, researchers used aircraft-mounted lidar, a method that uses laser pulses to measure distances to the ground, to survey forest in northern Guatemala."},{"id":"B","label":"The 2016 lidar survey covered more than 2,100 square kilometers in a fraction of the time that mapping on foot would have required."},{"id":"C","label":"The 2016 survey revealed tens of thousands of previously unrecorded Maya structures, including houses, causeways, and defensive walls."},{"id":"D","label":"Because lidar can detect ground features hidden beneath dense forest canopy, the 2016 survey of northern Guatemala was able to reveal tens of thousands of previously unrecorded Maya structures."}]}'::jsonb,38,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-038","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '163615bd-a5d3-29d7-42c9-e99896a645dd','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because it links the result (previously unrecorded structures) to its cause: lidar can detect features hidden beneath dense forest canopy. Choice A is incorrect because it describes how lidar works and where it was used but never mentions the structures it revealed. Choice B is incorrect because it emphasizes the survey’s speed and area, not why hidden structures could be found. Choice C is incorrect because it reports what the survey found without explaining why it was able to find it."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='163615bd-a5d3-29d7-42c9-e99896a645dd') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f6196472-1a03-1be7-32b2-44219d2d24c0','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to emphasize a similarity between the two methods while also noting a difference in what they can reveal. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• The transit method detects a planet when it passes in front of its star, slightly dimming the star’s light.\n• The radial velocity method detects a planet by measuring how the planet’s gravity makes its star wobble.\n• The transit method can reveal a planet’s size.\n• The radial velocity method can reveal a planet’s mass.\n• Both methods work best for large planets that orbit close to their stars.","options":[{"id":"A","label":"Both methods work best for large planets that orbit close to their stars, though one detects a dimming of starlight and the other detects a stellar wobble."},{"id":"B","label":"Both methods work best for large planets that orbit close to their stars, but the transit method can reveal a planet’s size, whereas the radial velocity method can reveal its mass."},{"id":"C","label":"The transit method can reveal a planet’s size, whereas the radial velocity method can reveal a planet’s mass."},{"id":"D","label":"The transit method, which can reveal a planet’s size, works best for large planets that orbit close to their stars."}]}'::jsonb,39,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-039","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'f6196472-1a03-1be7-32b2-44219d2d24c0','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because it does both things the goal requires: it states a similarity (both methods work best for large, close-in planets) and a difference in what the methods reveal (size versus mass). Choice A is incorrect because, although it states the similarity, the difference it notes concerns how the methods detect planets, not what they reveal. Choice C is incorrect because it notes the difference in what the methods reveal but omits any similarity. Choice D is incorrect because it describes only the transit method, so it cannot compare the two."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='f6196472-1a03-1be7-32b2-44219d2d24c0') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6425d03e-f501-fbc9-9a31-078719357716','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to emphasize how quickly printing spread after Gutenberg developed his press. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Johannes Gutenberg developed a movable-type printing press in Mainz around 1450.\n• His press used metal type that could be rearranged and reused.\n• Before printing, books in Europe were copied by hand, often taking months.\n• The Gutenberg Bible was completed around 1455.\n• By 1500, printing presses were operating in more than 200 European towns and cities.","options":[{"id":"A","label":"Before printing, books in Europe were copied by hand, a process that often took months, but Gutenberg’s press used metal type that could be rearranged and reused."},{"id":"B","label":"The Gutenberg Bible was completed around 1455, roughly five years after Gutenberg developed his press."},{"id":"C","label":"Within about fifty years of Gutenberg’s development of a movable-type press around 1450, printing presses were operating in more than 200 European towns and cities."},{"id":"D","label":"By 1500, printing presses were operating in more than 200 European towns and cities."}]}'::jsonb,40,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-040","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '6425d03e-f501-fbc9-9a31-078719357716','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because it conveys both the extent of the spread (more than 200 towns and cities) and the short time it took (about fifty years after Gutenberg’s press around 1450). Choice A is incorrect because it contrasts hand copying with printing but says nothing about the spread of presses. Choice B is incorrect because it measures the time to produce one book, not the spread of printing. Choice D is incorrect because, while it reports how widespread presses were by 1500, it gives no starting point, so it does not show how quickly that spread happened."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='6425d03e-f501-fbc9-9a31-078719357716') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('37c1f1df-e7fd-58c4-eae1-96798461afde','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to explain how Hubble determined that Andromeda is a separate galaxy. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• In the early 1920s, many astronomers believed that the Milky Way made up the entire universe.\n• Many thought that spiral-shaped clouds of light called spiral nebulae lay within the Milky Way.\n• In 1923, Edwin Hubble identified a Cepheid variable star in the Andromeda nebula.\n• The pattern of a Cepheid’s brightness changes can be used to calculate its distance.\n• Hubble’s calculations showed that Andromeda lies far outside the Milky Way and is a separate galaxy.","options":[{"id":"A","label":"By identifying a Cepheid variable star—a type of star whose brightness changes can be used to calculate its distance—in the Andromeda nebula, Hubble was able to show that Andromeda lies far outside the Milky Way."},{"id":"B","label":"In the early 1920s, many astronomers believed that the Milky Way made up the entire universe and that spiral nebulae such as Andromeda lay within it."},{"id":"C","label":"Hubble showed that Andromeda lies far outside the Milky Way and is a separate galaxy, overturning the view that the Milky Way made up the entire universe."},{"id":"D","label":"The pattern of a Cepheid variable star’s brightness changes can be used to calculate the star’s distance."}]}'::jsonb,41,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-041","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '37c1f1df-e7fd-58c4-eae1-96798461afde','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because it explains the method Hubble used: he found a Cepheid in Andromeda, and because a Cepheid’s brightness changes reveal its distance, he could show that Andromeda is far outside the Milky Way. Choice B is incorrect because it describes the view that prevailed before Hubble’s work. Choice C is incorrect because it states Hubble’s conclusion and its significance but not how he reached it. Choice D is incorrect because it describes a general property of Cepheids without connecting it to Hubble or Andromeda."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='37c1f1df-e7fd-58c4-eae1-96798461afde') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2bbf3db7-8d82-6260-dd13-92d3ce429339','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to present Ostrom’s findings as a challenge to Hardin’s argument. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• In 1968, ecologist Garrett Hardin argued that people sharing a resource, such as a pasture, will tend to overuse it.\n• He called this outcome the “tragedy of the commons.”\n• Political economist Elinor Ostrom studied communities that manage shared resources, such as fisheries and forests.\n• She found that many such communities create their own rules that prevent overuse over long periods.\n• In 2009, Ostrom became the first woman to receive the Nobel Prize in Economic Sciences.","options":[{"id":"A","label":"Hardin described the “tragedy of the commons” in 1968, and Ostrom later studied communities that manage shared resources such as fisheries and forests."},{"id":"B","label":"Whereas Hardin argued that people sharing a resource will tend to overuse it, Ostrom found that many communities create their own rules that prevent overuse of shared resources over long periods."},{"id":"C","label":"Ostrom, who studied how communities manage shared resources, became the first woman to receive the Nobel Prize in Economic Sciences."},{"id":"D","label":"In 1968, Hardin argued that people sharing a pasture will tend to overuse it, an outcome he called the “tragedy of the commons.”"}]}'::jsonb,42,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-042","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '2bbf3db7-8d82-6260-dd13-92d3ce429339','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because it sets Ostrom’s finding (communities often make rules that prevent overuse) directly against Hardin’s claim (shared resources tend to be overused), presenting her work as a challenge. Choice A is incorrect because it mentions both scholars but never states Ostrom’s findings, so no challenge is presented. Choice C is incorrect because it concerns Ostrom’s Nobel Prize and does not mention Hardin. Choice D is incorrect because it presents only Hardin’s argument."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='2bbf3db7-8d82-6260-dd13-92d3ce429339') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('88cc903c-89b9-cf7c-512e-1517a903ad01','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to emphasize that, despite its high proportion of carbon dioxide, Mars’s atmosphere is very thin compared with Earth’s. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Earth’s atmosphere is about 78 percent nitrogen and 21 percent oxygen.\n• Carbon dioxide makes up about 0.04 percent of Earth’s atmosphere.\n• Mars’s atmosphere is about 95 percent carbon dioxide.\n• The surface pressure of Mars’s atmosphere is less than 1 percent of Earth’s.\n• Both planets’ atmospheres contain small amounts of argon.","options":[{"id":"A","label":"Although Mars’s atmosphere is about 95 percent carbon dioxide, its surface pressure is less than 1 percent of Earth’s."},{"id":"B","label":"Carbon dioxide makes up about 95 percent of Mars’s atmosphere but only about 0.04 percent of Earth’s."},{"id":"C","label":"Earth’s atmosphere is about 78 percent nitrogen and 21 percent oxygen, while Mars’s is about 95 percent carbon dioxide."},{"id":"D","label":"The surface pressure of Mars’s atmosphere is less than 1 percent of Earth’s, and both atmospheres contain small amounts of argon."}]}'::jsonb,43,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-043","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '88cc903c-89b9-cf7c-512e-1517a903ad01','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because it fulfills both parts of the goal: it acknowledges Mars’s high proportion of carbon dioxide and, with “although,” emphasizes that the atmosphere is nonetheless very thin (less than 1 percent of Earth’s surface pressure). Choice B is incorrect because it compares carbon dioxide proportions but says nothing about thinness. Choice C is incorrect because it compares composition only. Choice D is incorrect because it conveys thinness but omits the high proportion of carbon dioxide that the goal says to acknowledge."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='88cc903c-89b9-cf7c-512e-1517a903ad01') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('913c6cd7-12f2-7a1c-f14c-dcc1e76fae5d','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to explain how the Impressionist movement got its name. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Claude Monet painted Impression, Sunrise in 1872.\n• The painting depicts the harbor of Le Havre, France, in loose, quick brushstrokes.\n• It was shown at an independent exhibition in Paris in 1874.\n• Critic Louis Leroy used the painting’s title to mock the exhibiting artists, calling them “Impressionists.”\n• The artists later adopted the name themselves.","options":[{"id":"A","label":"Monet’s Impression, Sunrise, which depicts the harbor of Le Havre in loose, quick brushstrokes, was painted in 1872 and shown at an independent exhibition in Paris in 1874."},{"id":"B","label":"At an independent exhibition in Paris in 1874, the critic Louis Leroy mocked the exhibiting artists."},{"id":"C","label":"The critic Louis Leroy used the title of Monet’s Impression, Sunrise to mock the artists at an 1874 exhibition, calling them “Impressionists,” a name the artists later adopted."},{"id":"D","label":"Monet’s Impression, Sunrise was shown at an 1874 exhibition of artists who later called themselves Impressionists."}]}'::jsonb,44,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-044","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '913c6cd7-12f2-7a1c-f14c-dcc1e76fae5d','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because it traces the name’s origin: a critic turned the painting’s title into a mocking label, “Impressionists,” which the artists then adopted. Choice A is incorrect because it describes the painting and where it was shown without explaining how the movement got its name. Choice B is incorrect because it mentions the critic’s mockery but not the label or its source in the painting’s title. Choice D is incorrect because it mentions the name but does not explain how it arose."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='913c6cd7-12f2-7a1c-f14c-dcc1e76fae5d') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('013b9c15-69d4-dbba-5d0d-9f7680d946e5','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to explain how researchers’ understanding of Ötzi’s death changed. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Ötzi is a naturally preserved human body found in the Ötztal Alps in 1991.\n• He lived about 5,300 years ago.\n• Researchers initially thought he might have died from exposure to the cold.\n• In 2001, X-rays revealed an arrowhead lodged in his left shoulder.\n• The wound would likely have caused fatal bleeding.","options":[{"id":"A","label":"In 2001, X-rays revealed that Ötzi had an arrowhead lodged in his left shoulder, a wound that would likely have caused fatal bleeding."},{"id":"B","label":"Researchers have suggested both that Ötzi was exposed to the cold and that he had an arrowhead lodged in his left shoulder."},{"id":"C","label":"Found in the Ötztal Alps in 1991, Ötzi was initially thought to have died from exposure to the cold."},{"id":"D","label":"Researchers initially thought that Ötzi might have died from exposure to the cold, but X-rays in 2001 revealed an arrowhead in his shoulder that would likely have caused fatal bleeding."}]}'::jsonb,45,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-045","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '013b9c15-69d4-dbba-5d0d-9f7680d946e5','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because it shows a change: it presents the initial explanation (exposure to cold) and the later evidence that replaced it (an arrowhead wound). Choice A is incorrect because it gives only the newer understanding, so no change is shown. Choice B is incorrect because, although it mentions both the cold and the arrowhead, it presents them side by side and does not show that the arrowhead evidence replaced the earlier explanation. Choice C is incorrect because it gives only the initial explanation."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='013b9c15-69d4-dbba-5d0d-9f7680d946e5') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('18740bcc-d842-2bff-c683-a6d9fe93820f','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to make a generalization about how organisms use bioluminescence. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Bioluminescence is the production of light by living organisms.\n• The anglerfish uses a glowing lure to attract prey.\n• Some squid produce light on their undersides that matches the light from above, hiding their silhouettes from predators below.\n• Fireflies flash light in patterns to attract mates.\n• In each case, the light comes from a chemical reaction involving compounds known as luciferins.","options":[{"id":"A","label":"In anglerfish, squid, and fireflies, light comes from a chemical reaction involving compounds known as luciferins."},{"id":"B","label":"Organisms use bioluminescence for a variety of purposes, including attracting prey, hiding from predators, and attracting mates."},{"id":"C","label":"Some squid hide their silhouettes from predators below by producing light on their undersides."},{"id":"D","label":"Fireflies flash light in patterns to attract mates, and anglerfish use a glowing lure to attract prey."}]}'::jsonb,46,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-046","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '18740bcc-d842-2bff-c683-a6d9fe93820f','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because it makes a general statement about how organisms use bioluminescence, summarizing the purposes shown in the notes. Choice A is incorrect because, although it is a generalization, it concerns how the light is produced rather than how organisms use it. Choice C is incorrect because it describes one specific case. Choice D is incorrect because it lists two specific examples without drawing a general conclusion."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='18740bcc-d842-2bff-c683-a6d9fe93820f') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5332088e-ff49-4999-83f6-a238955d6274','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to emphasize a limitation of radiocarbon dating that is related to the age of a sample. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Radiocarbon dating estimates the age of organic material by measuring how much carbon-14 remains in it.\n• Carbon-14 decays at a known rate, with a half-life of about 5,730 years.\n• After about 50,000 years, too little carbon-14 remains to measure reliably.\n• The method cannot be used directly on most rocks, which do not contain carbon from once-living things.\n• Chemist Willard Libby developed the method in the late 1940s.","options":[{"id":"A","label":"Radiocarbon dating, which Willard Libby developed in the late 1940s, cannot be used directly on most rocks because they do not contain carbon from once-living things."},{"id":"B","label":"Carbon-14 decays at a known rate, with a half-life of about 5,730 years."},{"id":"C","label":"Because too little carbon-14 remains to measure reliably after about 50,000 years, radiocarbon dating cannot reliably date older material."},{"id":"D","label":"Radiocarbon dating, which estimates the age of organic material, was developed by Willard Libby in the late 1940s."}]}'::jsonb,47,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-047","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '5332088e-ff49-4999-83f6-a238955d6274','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because it describes a limitation tied to a sample’s age: material older than about 50,000 years retains too little carbon-14 to measure. Choice A is incorrect because, although it names a limitation, that limitation depends on what a sample is made of, not how old it is. Choice B is incorrect because the known decay rate is what makes the method work, not a limitation. Choice D is incorrect because it concerns the method’s history."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='5332088e-ff49-4999-83f6-a238955d6274') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c51056f2-f086-5cb5-df1c-04e084e40c87','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"The student wants to emphasize that Ventris’s decipherment overturned an earlier assumption. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n• Linear B is a script found on clay tablets at Bronze Age sites such as Knossos and Pylos.\n• It was used in Mycenaean Greece from about 1400 to 1200 BCE.\n• Before 1952, many scholars assumed that the script did not record Greek.\n• In 1952, Michael Ventris, an architect and amateur scholar, deciphered Linear B and showed that it recorded an early form of Greek.","options":[{"id":"A","label":"Many scholars had assumed that Linear B did not record Greek, but in 1952 Michael Ventris deciphered the script and showed that it recorded an early form of Greek."},{"id":"B","label":"Michael Ventris, who deciphered Linear B in 1952, was an architect and amateur scholar."},{"id":"C","label":"Before 1952, many scholars assumed that Linear B, a script found on clay tablets at Knossos and Pylos, did not record Greek."},{"id":"D","label":"In 1952, Ventris showed that Linear B, a script found on clay tablets at Knossos and Pylos, recorded an early form of Greek."}]}'::jsonb,48,'{"section_type":"reading_writing","sat_domain":"rhetoric","sat_official_domain":"expression_of_ideas","sat_skill":"rhetorical_synthesis","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-rs-048","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'c51056f2-f086-5cb5-df1c-04e084e40c87','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because it states the earlier assumption (Linear B did not record Greek) and Ventris’s finding that contradicted it, so the decipherment is clearly shown to overturn the assumption. Choice B is incorrect because it emphasizes Ventris’s profession, not the assumption he overturned. Choice C is incorrect because it states the earlier assumption but never says that Ventris’s work overturned it. Choice D is incorrect because it reports Ventris’s finding but omits the assumption it overturned."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='c51056f2-f086-5cb5-df1c-04e084e40c87') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0bb25145-699a-ae34-3a80-2b5d382f0dc4','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Today, the Sahara is the largest hot desert in the world, receiving very little rain in most years. ______ evidence from ancient lake beds and rock paintings shows that much of the region was covered by grasslands and lakes several thousand years ago.","options":[{"id":"A","label":"Similarly,"},{"id":"B","label":"However,"},{"id":"C","label":"For instance,"},{"id":"D","label":"Therefore,"}]}'::jsonb,49,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '0bb25145-699a-ae34-3a80-2b5d382f0dc4','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because “However” signals a contrast between the Sahara’s present dryness and the evidence that it was once covered by grasslands and lakes. Choice A is incorrect because the second sentence does not describe a situation similar to the first. Choice C is incorrect because evidence of a green past is not an example of the desert’s current dryness. Choice D is incorrect because the past grasslands are not a result of the present dryness."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='0bb25145-699a-ae34-3a80-2b5d382f0dc4') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5c405be3-2991-13ff-59bc-0bc07fa0610a','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Many animals besides humans use tools to obtain food. ______ sea otters use rocks to crack open the shells of clams and sea urchins, often balancing a rock on their chests while floating on their backs.","options":[{"id":"A","label":"For example,"},{"id":"B","label":"Nevertheless,"},{"id":"C","label":"In contrast,"},{"id":"D","label":"Meanwhile,"}]}'::jsonb,50,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-002","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '5c405be3-2991-13ff-59bc-0bc07fa0610a','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because sea otters cracking shells with rocks is a specific example of animals using tools to obtain food, and “For example” introduces such an illustration. Choice B is incorrect because nothing in the second sentence goes against the first. Choice C is incorrect because the sea otters support, rather than contrast with, the general claim. Choice D is incorrect because “Meanwhile” indicates events happening at the same time, which is not the relationship here."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='5c405be3-2991-13ff-59bc-0bc07fa0610a') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a95ebfeb-0ecc-8608-2cc1-d5379699041d','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"After decades of exposure to salty sea air, the steel cables supporting the old harbor bridge had badly corroded. ______ city engineers closed the bridge to heavy trucks until the cables could be replaced.","options":[{"id":"A","label":"In addition,"},{"id":"B","label":"For instance,"},{"id":"C","label":"As a result,"},{"id":"D","label":"Still,"}]}'::jsonb,51,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'a95ebfeb-0ecc-8608-2cc1-d5379699041d','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because closing the bridge to trucks is a consequence of the corroded cables, and “As a result” signals cause and effect. Choice A is incorrect because the closure is not simply an additional fact; it is a response to the corrosion. Choice B is incorrect because the closure is not an example of corrosion. Choice D is incorrect because “Still” would suggest that the closure happened despite the corrosion, which reverses the logic."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='a95ebfeb-0ecc-8608-2cc1-d5379699041d') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3c4b36f3-3930-e4b2-8092-d801c09f0da5','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"The Iraqi British architect Zaha Hadid was known for buildings with sweeping, curved forms, such as the Heydar Aliyev Center in Baku, Azerbaijan. ______ she was the first woman to receive the Pritzker Architecture Prize, which she won in 2004.","options":[{"id":"A","label":"Instead,"},{"id":"B","label":"However,"},{"id":"C","label":"For example,"},{"id":"D","label":"Additionally,"}]}'::jsonb,52,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '3c4b36f3-3930-e4b2-8092-d801c09f0da5','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the second sentence adds another notable fact about Hadid, and “Additionally” signals that addition. Choice A is incorrect because the prize did not replace or substitute for her style. Choice B is incorrect because winning the prize does not contrast with her being known for distinctive buildings. Choice C is incorrect because the prize is not an example of her curved forms."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='3c4b36f3-3930-e4b2-8092-d801c09f0da5') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('12ac35a3-850c-df82-f875-f5d6da9e7d42','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"To make paper by hand, workers first soak plant fibers in water and beat them until they form a soft pulp. ______ they dip a screen into the pulp, lift out a thin, even layer of fibers, and leave it to dry.","options":[{"id":"A","label":"Next,"},{"id":"B","label":"In contrast,"},{"id":"C","label":"For example,"},{"id":"D","label":"Regardless,"}]}'::jsonb,53,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-005","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '12ac35a3-850c-df82-f875-f5d6da9e7d42','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the passage describes a process in order, and “Next” introduces the step that follows soaking and beating the fibers. Choice B is incorrect because the second step does not contrast with the first. Choice C is incorrect because dipping the screen is not an example of making pulp. Choice D is incorrect because “Regardless” suggests that the second step happens despite the first, which does not fit a sequence."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='12ac35a3-850c-df82-f875-f5d6da9e7d42') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5ecd16b7-d4d9-953d-c413-ffc1b1fbdc7f','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Most spiders have eight eyes, which they use to detect movement and, in some species, to spot prey from a distance. ______ many spiders that live deep in caves have reduced eyes or none at all, since there is little or no light in their environment.","options":[{"id":"A","label":"Therefore,"},{"id":"B","label":"Similarly,"},{"id":"C","label":"By contrast,"},{"id":"D","label":"For instance,"}]}'::jsonb,54,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '5ecd16b7-d4d9-953d-c413-ffc1b1fbdc7f','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because cave spiders with few or no eyes differ from most spiders, which have eight, and “By contrast” signals that difference. Choice A is incorrect because cave spiders’ reduced eyes do not follow from most spiders having eight eyes. Choice B is incorrect because the two groups are different, not similar. Choice D is incorrect because cave spiders are an exception to the first statement, not an example of it."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='5ecd16b7-d4d9-953d-c413-ffc1b1fbdc7f') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9fd3fb79-7441-d3c6-13d6-fa4425c91b33','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Some plants rely on animals to spread their seeds far from the parent plant. ______ the seed heads of the burdock plant are covered in tiny hooks that catch on the fur of passing mammals, which may carry them a long distance before they fall off.","options":[{"id":"A","label":"However,"},{"id":"B","label":"For instance,"},{"id":"C","label":"As a result,"},{"id":"D","label":"Likewise,"}]}'::jsonb,55,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '9fd3fb79-7441-d3c6-13d6-fa4425c91b33','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because burdock is a specific case of a plant that relies on animals to spread its seeds, so “For instance” fits. Choice A is incorrect because the burdock example supports the first sentence rather than contradicting it. Choice C is incorrect because the burdock’s hooks are not caused by the general fact in the first sentence. Choice D is incorrect because “Likewise” would introduce a separate but similar case, whereas burdock is an instance of the very group just described."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='9fd3fb79-7441-d3c6-13d6-fa4425c91b33') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3de833f1-2c1d-c637-8be1-88b6233e511c','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Light travels through air about a million times faster than sound does. ______ during a thunderstorm, people see a flash of lightning before they hear the thunder it produces.","options":[{"id":"A","label":"For this reason,"},{"id":"B","label":"Nevertheless,"},{"id":"C","label":"Similarly,"},{"id":"D","label":"In other words,"}]}'::jsonb,56,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '3de833f1-2c1d-c637-8be1-88b6233e511c','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because seeing lightning before hearing thunder is a consequence of light traveling faster than sound, and “For this reason” signals that cause-and-effect relationship. Choice B is incorrect because the second sentence is not surprising given the first. Choice C is incorrect because the second sentence is not a separate similar fact but an effect of the first. Choice D is incorrect because the second sentence does not restate the first; it describes something that follows from it."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='3de833f1-2c1d-c637-8be1-88b6233e511c') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ba590f9e-9981-42a2-6478-0df27eb3960d','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"In ancient Egypt, scribes wrote on a material that was abundant where they lived: sheets made from the papyrus plant, which grew along the Nile. ______ early writers in ancient China often used a material that was plentiful in their region, writing on strips of bamboo.","options":[{"id":"A","label":"Instead,"},{"id":"B","label":"Similarly,"},{"id":"C","label":"As a result,"},{"id":"D","label":"For example,"}]}'::jsonb,57,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-009","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'ba590f9e-9981-42a2-6478-0df27eb3960d','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because both sentences describe writers using a locally plentiful material, and “Similarly” signals that parallel. Choice A is incorrect because Chinese writers’ use of bamboo did not replace the Egyptians’ use of papyrus. Choice C is incorrect because Egyptian practices did not cause Chinese ones. Choice D is incorrect because China is not an example of what happened in Egypt."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='ba590f9e-9981-42a2-6478-0df27eb3960d') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8598de2c-fad0-c6d0-66fe-3b9a5cef7cf3','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"The first draft of the young novelist’s book was rejected by five publishers, and two of them advised her to abandon the project entirely. ______ she kept revising the manuscript, and the sixth publisher she approached accepted it.","options":[{"id":"A","label":"Therefore,"},{"id":"B","label":"For example,"},{"id":"C","label":"Similarly,"},{"id":"D","label":"Still,"}]}'::jsonb,58,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '8598de2c-fad0-c6d0-66fe-3b9a5cef7cf3','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the novelist kept working despite the rejections and discouraging advice, and “Still” signals that she continued in spite of what came before. Choice A is incorrect because continuing to revise is not a logical result of being told to quit. Choice B is incorrect because her persistence is not an example of the rejections. Choice C is incorrect because her persistence is not similar to the rejections."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='8598de2c-fad0-c6d0-66fe-3b9a5cef7cf3') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4d91577f-531a-45f4-90c5-cd206777a174','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"In 1869, Russian chemist Dmitri Mendeleev published a periodic table that left gaps for elements that had not yet been discovered, and he predicted some of their properties. ______ chemists discovered gallium, scandium, and germanium, elements whose properties closely matched his predictions.","options":[{"id":"A","label":"Later,"},{"id":"B","label":"In comparison,"},{"id":"C","label":"For instance,"},{"id":"D","label":"Nonetheless,"}]}'::jsonb,59,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '4d91577f-531a-45f4-90c5-cd206777a174','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the discoveries happened after Mendeleev published his table, and “Later” signals that time sequence. Choice B is incorrect because the passage is not comparing two things. Choice C is incorrect because the discoveries are not an example of Mendeleev publishing his table. Choice D is incorrect because the discoveries confirm his predictions rather than happening despite them."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='4d91577f-531a-45f4-90c5-cd206777a174') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('298fdb79-0d43-beef-8510-c7710cb33cae','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"The Kuiper Belt is a region of icy bodies that lies beyond the orbit of Neptune. ______ it is located farther from the Sun than the most distant of the solar system’s eight major planets.","options":[{"id":"A","label":"However,"},{"id":"B","label":"For example,"},{"id":"C","label":"In other words,"},{"id":"D","label":"As a result,"}]}'::jsonb,60,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '298fdb79-0d43-beef-8510-c7710cb33cae','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the second sentence restates the location given in the first (beyond Neptune, the outermost major planet) in different terms, and “In other words” signals a restatement. Choice A is incorrect because the two sentences agree. Choice B is incorrect because the second sentence is not a specific example. Choice D is incorrect because being farther than Neptune is not a consequence of being beyond Neptune; it is the same fact."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='298fdb79-0d43-beef-8510-c7710cb33cae') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9c684837-a5ac-5b3b-c2e3-e2bb37b1235f','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Unlike most bony fish, sharks do not have a swim bladder, a gas-filled organ that helps many fish stay afloat. ______ sharks rely partly on a large, oil-filled liver, which is less dense than seawater, to keep them from sinking.","options":[{"id":"A","label":"Similarly,"},{"id":"B","label":"Instead,"},{"id":"C","label":"For example,"},{"id":"D","label":"Specifically,"}]}'::jsonb,61,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-013","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '9c684837-a5ac-5b3b-c2e3-e2bb37b1235f','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the oily liver serves sharks in place of the swim bladder they lack, and “Instead” signals that substitution. Choice A is incorrect because sharks’ use of a liver is not similar to their lacking a swim bladder. Choice C is incorrect because the liver is not an example of a swim bladder. Choice D is incorrect because the second sentence does not give a more precise version of the first; it describes an alternative."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='9c684837-a5ac-5b3b-c2e3-e2bb37b1235f') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9e735645-60dc-99bd-afd5-b7122ef0353f','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Honey has very low water content and is acidic, conditions in which few bacteria can survive. ______ honey stored in a sealed container can remain edible for many years.","options":[{"id":"A","label":"In contrast,"},{"id":"B","label":"Similarly,"},{"id":"C","label":"For instance,"},{"id":"D","label":"Thus,"}]}'::jsonb,62,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-014","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '9e735645-60dc-99bd-afd5-b7122ef0353f','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because honey’s long shelf life results from conditions in which bacteria cannot survive, and “Thus” signals that consequence. Choice A is incorrect because the second sentence does not contrast with the first. Choice B is incorrect because the second sentence is an effect of the first, not a similar but separate fact. Choice C is incorrect because a long shelf life is not an example of low water content or acidity."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='9e735645-60dc-99bd-afd5-b7122ef0353f') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a9a00019-8ff1-944f-4c1c-2e31a4df7489','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"The Great Wall of China is often described as a single continuous wall stretching across northern China. ______ it is a series of walls, trenches, and fortifications built and rebuilt by different dynasties over many centuries.","options":[{"id":"A","label":"Likewise,"},{"id":"B","label":"As a result,"},{"id":"C","label":"In reality,"},{"id":"D","label":"For example,"}]}'::jsonb,63,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-015","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'a9a00019-8ff1-944f-4c1c-2e31a4df7489','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the second sentence corrects the common description in the first, and “In reality” introduces the actual situation in contrast to a popular belief. Choice A is incorrect because the second sentence does not describe something similar. Choice B is incorrect because the true structure of the wall is not a result of how it is commonly described. Choice D is incorrect because the second sentence is a correction, not an example."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='a9a00019-8ff1-944f-4c1c-2e31a4df7489') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c547d550-de73-0ded-8cb8-15f28e079a4b','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"The Inca Empire developed a sophisticated accounting system that did not rely on written numerals. ______ officials recorded quantities on khipus, arrangements of knotted cords in which the type and position of each knot represented a particular value.","options":[{"id":"A","label":"Specifically,"},{"id":"B","label":"Nevertheless,"},{"id":"C","label":"Similarly,"},{"id":"D","label":"In conclusion,"}]}'::jsonb,64,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-016","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'c547d550-de73-0ded-8cb8-15f28e079a4b','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the second sentence explains in precise terms how the accounting system worked without written numerals, and “Specifically” introduces such detail. Choice B is incorrect because the khipus are consistent with the first sentence rather than contrary to it. Choice C is incorrect because the second sentence elaborates on the same system rather than describing a different but similar one. Choice D is incorrect because the second sentence adds detail rather than summarizing the passage."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='c547d550-de73-0ded-8cb8-15f28e079a4b') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('530ecb73-9ff0-e13b-df2e-1fc8cf47e925','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Charles Darwin acknowledged that the fossil record of his time contained few clear examples of forms intermediate between species, a fact that critics used against his theory of evolution. ______ he remained confident in the theory, arguing that the fossil record was simply incomplete.","options":[{"id":"A","label":"Accordingly,"},{"id":"B","label":"For instance,"},{"id":"C","label":"Nevertheless,"},{"id":"D","label":"Likewise,"}]}'::jsonb,65,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-017","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '530ecb73-9ff0-e13b-df2e-1fc8cf47e925','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because Darwin stayed confident despite a weakness that critics pointed out, and “Nevertheless” signals that he persisted in spite of the difficulty. Choice A is incorrect because confidence in the theory is not a logical result of evidence that critics used against it. Choice B is incorrect because his confidence is not an example of the gaps in the fossil record. Choice D is incorrect because his confidence is not similar to the critics’ objection."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='530ecb73-9ff0-e13b-df2e-1fc8cf47e925') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0a74f3dd-7edf-bbad-ee15-550ffcbc494d','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"The Spanish cellist Pablo Casals was famous for his dedication to daily practice. ______ he reportedly continued practicing for several hours each day well into his nineties, explaining that he believed he was still improving.","options":[{"id":"A","label":"However,"},{"id":"B","label":"Indeed,"},{"id":"C","label":"Instead,"},{"id":"D","label":"Secondly,"}]}'::jsonb,66,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-018","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '0a74f3dd-7edf-bbad-ee15-550ffcbc494d','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the second sentence strengthens the claim in the first with a striking piece of supporting evidence, and “Indeed” introduces such emphasis. Choice A is incorrect because practicing into his nineties supports, rather than contradicts, his reputation. Choice C is incorrect because nothing is being replaced. Choice D is incorrect because the passage is not presenting a numbered list of points."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='0a74f3dd-7edf-bbad-ee15-550ffcbc494d') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b33229fb-49d7-3a2f-a356-94ab997c40a0','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"The heart of an adult blue whale, the largest animal known to have lived, can weigh roughly 180 kilograms, about as much as two adult men. ______ the heart of an adult human weighs only about 0.3 kilograms.","options":[{"id":"A","label":"Furthermore,"},{"id":"B","label":"Thus,"},{"id":"C","label":"For example,"},{"id":"D","label":"In comparison,"}]}'::jsonb,67,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-019","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'b33229fb-49d7-3a2f-a356-94ab997c40a0','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the second sentence measures the human heart against the blue whale’s, and “In comparison” introduces that comparison. Choice A is incorrect because the human heart’s weight is presented as a contrast, not as an additional point about blue whales. Choice B is incorrect because the human heart’s weight does not follow from the whale’s. Choice C is incorrect because a human heart is not an example of a blue whale heart."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='b33229fb-49d7-3a2f-a356-94ab997c40a0') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b365ed54-d4e6-277d-116a-28361ded0d05','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Since 2006, the International Astronomical Union has classified Pluto as a dwarf planet, a body that orbits the Sun but has not cleared its orbital neighborhood of other objects. ______ Pluto had been considered the ninth planet of the solar system for more than seventy years.","options":[{"id":"A","label":"Previously,"},{"id":"B","label":"Subsequently,"},{"id":"C","label":"Consequently,"},{"id":"D","label":"Similarly,"}]}'::jsonb,68,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-020","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'b365ed54-d4e6-277d-116a-28361ded0d05','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the second sentence describes Pluto’s status before 2006, and “Previously” signals a move back to an earlier time. Choice B is incorrect because “Subsequently” would place the planet classification after 2006, reversing the timeline. Choice C is incorrect because Pluto’s earlier status was not caused by its 2006 reclassification. Choice D is incorrect because the two classifications differ."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='b365ed54-d4e6-277d-116a-28361ded0d05') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('63d945c9-098b-c0cf-810e-b843d6e2e28b','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Urban gardens can provide fresh produce in neighborhoods that have few grocery stores. ______ they can lower nearby air temperatures on hot days, since plants release water vapor that cools the surrounding air.","options":[{"id":"A","label":"Namely,"},{"id":"B","label":"Nonetheless,"},{"id":"C","label":"Moreover,"},{"id":"D","label":"In contrast,"}]}'::jsonb,69,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-021","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '63d945c9-098b-c0cf-810e-b843d6e2e28b','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the second sentence adds another benefit of urban gardens, and “Moreover” signals an additional supporting point. Choice A is incorrect because cooling the air does not specify or name the produce benefit just mentioned. Choice B is incorrect because the cooling benefit does not go against the first benefit. Choice D is incorrect because the two benefits are complementary, not contrasting."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='63d945c9-098b-c0cf-810e-b843d6e2e28b') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('dff9372f-6db4-6711-be49-209ef5d1bc2d','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Some critics have dismissed graphic novels as a lesser form of literature. ______ many graphic novels are written mainly to entertain, but works such as Art Spiegelman’s Maus, which received a special Pulitzer Prize in 1992, show that the form can treat serious subjects with great depth.","options":[{"id":"A","label":"Therefore,"},{"id":"B","label":"Granted,"},{"id":"C","label":"For instance,"},{"id":"D","label":"In short,"}]}'::jsonb,70,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-022","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'dff9372f-6db4-6711-be49-209ef5d1bc2d','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the sentence concedes a point that partly supports the critics (many graphic novels are mainly entertainment) before countering it with “but,” and “Granted” introduces such a concession. Choice A is incorrect because the sentence does not present a conclusion that follows from the critics’ view. Choice C is incorrect because the sentence is not an example of critics dismissing graphic novels; it weighs their view against counterevidence. Choice D is incorrect because the sentence introduces new information rather than summarizing."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='dff9372f-6db4-6711-be49-209ef5d1bc2d') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('cf921ce0-8d37-8c0a-40d7-160042ae41e4','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Glass allows most visible light to pass through it, but many polished metals reflect most of the visible light that strikes their surfaces. ______ thin layers of aluminum or silver have long been applied to the backs of glass panes to make mirrors.","options":[{"id":"A","label":"Conversely,"},{"id":"B","label":"Meanwhile,"},{"id":"C","label":"For instance,"},{"id":"D","label":"Hence,"}]}'::jsonb,71,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-023","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'cf921ce0-8d37-8c0a-40d7-160042ae41e4','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because coating glass with reflective metal to make mirrors follows logically from metals’ ability to reflect light, and “Hence” signals that consequence. Choice A is incorrect because the use of metals in mirrors does not oppose the preceding statement. Choice B is incorrect because “Meanwhile” signals simultaneous events, not a logical result. Choice C is incorrect because mirrors are an application of metals’ reflectivity rather than an example of it."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='cf921ce0-8d37-8c0a-40d7-160042ae41e4') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('db726bb9-dca3-016f-110d-cbfe516f0a6d','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Tea was first cultivated in China, and for centuries China was the world’s only major producer of the crop. ______ by the late 1800s, plantations in British-ruled India were producing large quantities of tea for export to Europe.","options":[{"id":"A","label":"Thus,"},{"id":"B","label":"However,"},{"id":"C","label":"Likewise,"},{"id":"D","label":"In other words,"}]}'::jsonb,72,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-024","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'db726bb9-dca3-016f-110d-cbfe516f0a6d','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the rise of large-scale tea production in India ended China’s position as the only major producer, and “However” signals this contrast. Choice A is incorrect because India’s production was not a logical consequence of China’s long dominance. Choice C is incorrect because the second sentence describes a change, not a parallel situation. Choice D is incorrect because the second sentence does not restate the first."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='db726bb9-dca3-016f-110d-cbfe516f0a6d') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b8aeb197-04a8-fe86-a19b-a8eec2bfb536','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Ornithologists describe the young of some bird species, such as robins and sparrows, as altricial. ______ these chicks hatch with their eyes closed and with little or no down, and they must be fed and kept warm by their parents for some time.","options":[{"id":"A","label":"Additionally,"},{"id":"B","label":"Consequently,"},{"id":"C","label":"That is,"},{"id":"D","label":"Even so,"}]}'::jsonb,73,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-025","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'b8aeb197-04a8-fe86-a19b-a8eec2bfb536','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the second sentence explains what the term “altricial” means, and “That is” introduces a clarification or definition. Choice A is incorrect because the description is not an additional, separate fact; it explains the term. Choice B is incorrect because the chicks’ helplessness is not a result of what scientists call them. Choice D is incorrect because nothing in the description goes against the first sentence."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='b8aeb197-04a8-fe86-a19b-a8eec2bfb536') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('94d966c6-19c1-54ff-d96a-b56a698237b5','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Construction of the Sagrada Família in Barcelona began in 1882, and Antoni Gaudí, who took over the project the following year, devoted much of his later career to it. When Gaudí died in 1926, however, the church was far from finished. ______ work has continued for about a century, guided in part by Gaudí’s surviving models and drawings.","options":[{"id":"A","label":"Since then,"},{"id":"B","label":"Before that,"},{"id":"C","label":"For example,"},{"id":"D","label":"Likewise,"}]}'::jsonb,74,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-026","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '94d966c6-19c1-54ff-d96a-b56a698237b5','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the final sentence describes work carried on after Gaudí’s death in 1926, and “Since then” signals the period from that point to the present. Choice B is incorrect because “Before that” would place the continued work earlier than 1926, contradicting “about a century.” Choice C is incorrect because continued construction is not an example of the church being unfinished. Choice D is incorrect because the final sentence does not describe something similar to Gaudí’s death."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='94d966c6-19c1-54ff-d96a-b56a698237b5') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c4da39ba-0186-fcf1-a1af-1d8c84828c3a','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"In the Northern Hemisphere, the longest day of the year falls in June, when that half of Earth is tilted toward the Sun. ______ in the Southern Hemisphere, which is tilted away from the Sun at that time of year, June brings the shortest days.","options":[{"id":"A","label":"Similarly,"},{"id":"B","label":"For example,"},{"id":"C","label":"As a result,"},{"id":"D","label":"Conversely,"}]}'::jsonb,75,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-027","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'c4da39ba-0186-fcf1-a1af-1d8c84828c3a','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the Southern Hemisphere experiences the opposite of the Northern Hemisphere in June, and “Conversely” signals a reversal. Choice A is incorrect because the two hemispheres have opposite, not similar, experiences. Choice B is incorrect because the Southern Hemisphere is not an example of the Northern Hemisphere’s long days. Choice C is incorrect because the Southern Hemisphere’s short days result from its own tilt away from the Sun, not from the Northern Hemisphere’s long days."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='c4da39ba-0186-fcf1-a1af-1d8c84828c3a') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('16ad8301-442e-c592-c85f-7fc2b02d78f7','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"The Atacama Desert’s high altitude, extremely dry air, and mostly cloudless skies make it one of the best places on Earth for astronomical observation. ______ several major astronomical observatories have been built there, including the Atacama Large Millimeter/submillimeter Array (ALMA).","options":[{"id":"A","label":"Even so,"},{"id":"B","label":"In contrast,"},{"id":"C","label":"For this reason,"},{"id":"D","label":"Specifically,"}]}'::jsonb,76,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-028","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '16ad8301-442e-c592-c85f-7fc2b02d78f7','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the observatories were built in the Atacama because of its excellent viewing conditions, and “For this reason” signals that cause-and-effect relationship. Choice A is incorrect because building observatories there is expected, not surprising, given the conditions. Choice B is incorrect because nothing in the second sentence contrasts with the first. Choice D is incorrect because the observatories are not a more precise description of the desert’s conditions."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='16ad8301-442e-c592-c85f-7fc2b02d78f7') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('584bddcc-119f-804b-1880-0e89826f3cbb','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Researchers who want to know the age of a tree have two main options. They can count the tree’s growth rings after it has been cut down. ______ they can use a tool called an increment borer to extract a thin core from a living tree and count the rings in that core.","options":[{"id":"A","label":"Consequently,"},{"id":"B","label":"Alternatively,"},{"id":"C","label":"For instance,"},{"id":"D","label":"In summary,"}]}'::jsonb,77,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-029","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '584bddcc-119f-804b-1880-0e89826f3cbb','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the passage announces two options, and the final sentence presents the second one, which “Alternatively” introduces. Choice A is incorrect because using an increment borer is not a result of counting rings in a cut tree. Choice C is incorrect because the borer is not an example of cutting a tree down; it is a different method. Choice D is incorrect because the final sentence adds a new option rather than summarizing."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='584bddcc-119f-804b-1880-0e89826f3cbb') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('510bd7b9-7647-84fd-2f37-8e3f5f9f02dc','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Many writers of the Harlem Renaissance drew on African American folk traditions. The poet Langston Hughes, for example, used the rhythms of blues and jazz in poems such as “The Weary Blues.” ______ the novelist Zora Neale Hurston incorporated the speech patterns of Black communities in Florida into the dialogue of her fiction.","options":[{"id":"A","label":"Instead,"},{"id":"B","label":"Similarly,"},{"id":"C","label":"Consequently,"},{"id":"D","label":"Nevertheless,"}]}'::jsonb,78,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-030","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '510bd7b9-7647-84fd-2f37-8e3f5f9f02dc','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because Hurston’s use of local speech patterns is another case of a Harlem Renaissance writer drawing on folk traditions, parallel to Hughes’s use of blues and jazz, so “Similarly” fits. Choice A is incorrect because Hurston’s practice did not replace Hughes’s. Choice C is incorrect because Hughes’s poetry did not cause Hurston’s choices. Choice D is incorrect because Hurston’s work supports, rather than contrasts with, the pattern described."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='510bd7b9-7647-84fd-2f37-8e3f5f9f02dc') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ce55bb8a-b039-065a-6df3-425377c0465b','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Over the past decade, the city added 40 kilometers of protected bike lanes, expanded its bike-share program to every neighborhood, and lowered speed limits on residential streets. ______ the city has made several changes intended to make cycling safer and more convenient.","options":[{"id":"A","label":"In short,"},{"id":"B","label":"For instance,"},{"id":"C","label":"However,"},{"id":"D","label":"Afterward,"}]}'::jsonb,79,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-031","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'ce55bb8a-b039-065a-6df3-425377c0465b','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the second sentence sums up the specific changes listed in the first, and “In short” introduces a brief summary. Choice B is incorrect because the second sentence is a general statement, not an example of the changes. Choice C is incorrect because the summary agrees with the list rather than contrasting with it. Choice D is incorrect because the second sentence does not describe a later event; it describes the same changes."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='ce55bb8a-b039-065a-6df3-425377c0465b') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0f80a6d0-64e4-a4a9-381a-59d078e9cdde','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"The museum’s new exhibit features centuries-old textiles whose natural dyes fade when exposed to strong light. ______ the galleries displaying them are kept dimly lit, and each piece is removed from display after a few months to rest in dark storage.","options":[{"id":"A","label":"Nevertheless,"},{"id":"B","label":"Likewise,"},{"id":"C","label":"For example,"},{"id":"D","label":"Accordingly,"}]}'::jsonb,80,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-032","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '0f80a6d0-64e4-a4a9-381a-59d078e9cdde','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the dim lighting and rotation are measures taken in response to the textiles’ sensitivity to light, and “Accordingly” signals an action that follows from a stated condition. Choice A is incorrect because the protective measures are expected, not contrary, given the fading risk. Choice B is incorrect because the measures are not similar to the textiles’ fragility; they respond to it. Choice C is incorrect because the measures are not an example of fading."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='0f80a6d0-64e4-a4a9-381a-59d078e9cdde') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b9c1e7c2-2cf3-f61d-d1cf-7133014f2ed5','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Gray wolves had been eliminated from Yellowstone National Park by the 1920s, and for decades afterward the park’s elk populations grew largely unchecked. In the early 1990s, federal agencies set out to restore wolves to the park. ______ biologists captured wolves in Canada and released them into Yellowstone in 1995 and 1996.","options":[{"id":"A","label":"Regardless,"},{"id":"B","label":"In other words,"},{"id":"C","label":"By contrast,"},{"id":"D","label":"To that end,"}]}'::jsonb,81,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-033","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'b9c1e7c2-2cf3-f61d-d1cf-7133014f2ed5','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because capturing and releasing wolves was the action taken to achieve the goal just stated (restoring wolves to the park), and “To that end” introduces a step taken toward a goal. Choice A is incorrect because the releases were carried out in pursuit of the plan, not in disregard of anything. Choice B is incorrect because the final sentence does not restate the goal; it describes the specific means used to accomplish it. Choice C is incorrect because the releases are consistent with, not opposed to, the plan to restore wolves."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='b9c1e7c2-2cf3-f61d-d1cf-7133014f2ed5') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('68a5ef13-d479-442b-bb29-0e09f404830d','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"For decades, many scientists assumed that the deep seafloor, cold and lacking sunlight, could support only sparse life. In 1977, however, researchers exploring hydrothermal vents near the Galápagos Islands found dense communities of tube worms, clams, and other animals. These animals depend on bacteria that produce food from chemicals in the vent water rather than from sunlight. ______ the discovery revealed that entire ecosystems can be based on a source of energy other than sunlight.","options":[{"id":"A","label":"Nevertheless,"},{"id":"B","label":"Thus,"},{"id":"C","label":"Meanwhile,"},{"id":"D","label":"Earlier,"}]}'::jsonb,82,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-034","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '68a5ef13-d479-442b-bb29-0e09f404830d','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the final sentence states the conclusion that follows from the preceding evidence (vent animals depend on chemical-based food), and “Thus” introduces a conclusion. Choice A is incorrect because the conclusion is supported by, not contrary to, the sentence before it; the contrast with the old assumption has already been marked by “however.” Choice C is incorrect because the final sentence draws a conclusion rather than describing a simultaneous event. Choice D is incorrect because the conclusion came from the 1977 discovery, so it cannot have come earlier."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='68a5ef13-d479-442b-bb29-0e09f404830d') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0ae64cd6-9486-ee0a-277c-7eab648a8f98','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Historians often credit Johannes Gutenberg’s printing press of the mid-1400s with transforming access to information in Europe. ______ printing with movable type had been developed centuries earlier in East Asia, and metal movable type was in use in Korea by the thirteenth century. Gutenberg’s achievement lay instead in combining metal type with a press and oil-based inks, a system well suited to Europe’s alphabetic scripts.","options":[{"id":"A","label":"Admittedly,"},{"id":"B","label":"Consequently,"},{"id":"C","label":"Similarly,"},{"id":"D","label":"Specifically,"}]}'::jsonb,83,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-035","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '0ae64cd6-9486-ee0a-277c-7eab648a8f98','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the sentence concedes a point that limits Gutenberg’s originality (movable type existed earlier in East Asia) before the passage explains what his real achievement was, and “Admittedly” introduces such a concession. Choice B is incorrect because earlier East Asian printing was not caused by historians’ view of Gutenberg. Choice C is incorrect because the earlier invention is not similar to historians’ crediting Gutenberg; it qualifies that credit. Choice D is incorrect because the sentence does not give precise details of Gutenberg’s press; it shifts to a different time and place."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='0ae64cd6-9486-ee0a-277c-7eab648a8f98') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7a8ae348-76fc-5e96-01d7-cbe997bd2b8e','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"The Voyager 1 spacecraft, launched in 1977, crossed into interstellar space in 2012, becoming the first human-made object to do so. Its aging power source now produces so little electricity that engineers have shut down many of its instruments and heaters to conserve energy. ______ the spacecraft continues to send data back to Earth, giving scientists rare direct measurements of the region beyond the Sun’s protective bubble.","options":[{"id":"A","label":"Therefore,"},{"id":"B","label":"Likewise,"},{"id":"C","label":"Even so,"},{"id":"D","label":"In other words,"}]}'::jsonb,84,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-036","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '7a8ae348-76fc-5e96-01d7-cbe997bd2b8e','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the spacecraft keeps sending data despite its dwindling power and disabled instruments, and “Even so” signals that something happens in spite of what was just described. Choice A is incorrect because continuing to send data does not result from shutting down instruments; it happens despite the power loss. Choice B is incorrect because sending data is not similar to losing power. Choice D is incorrect because the final sentence does not restate the previous one."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='7a8ae348-76fc-5e96-01d7-cbe997bd2b8e') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('cc618d5d-fbcd-2b5a-19d1-3da3255b25d8','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Most of the large moons in the solar system orbit their planets in the same direction that the planet rotates. Neptune’s largest moon, Triton, is a striking exception: it orbits in the opposite direction. ______ astronomers think that Triton did not form alongside Neptune but was instead captured by the planet’s gravity, perhaps after originating in the Kuiper Belt.","options":[{"id":"A","label":"Partly for this reason,"},{"id":"B","label":"Nonetheless,"},{"id":"C","label":"In comparison,"},{"id":"D","label":"By the same token,"}]}'::jsonb,85,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-037","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'cc618d5d-fbcd-2b5a-19d1-3da3255b25d8','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because Triton’s backward orbit is evidence for the idea that it was captured, and “Partly for this reason” presents the astronomers’ view as following, in part, from that unusual orbit. Choice B is incorrect because the capture hypothesis is supported by, not contrary to, the backward orbit. Choice C is incorrect because the final sentence does not compare Triton with other moons; it explains Triton’s origin. Choice D is incorrect because “By the same token” introduces a parallel claim based on the same reasoning, whereas the final sentence is an inference drawn from the orbit itself."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='cc618d5d-fbcd-2b5a-19d1-3da3255b25d8') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('815be191-8c06-1595-61d2-6685b2380339','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"On July 1, 1858, papers by Charles Darwin and Alfred Russel Wallace describing the theory of natural selection were read together at a meeting of the Linnean Society of London. Wallace, however, was not in the audience. ______ he was thousands of kilometers away in the Malay Archipelago, collecting specimens of birds and insects.","options":[{"id":"A","label":"Afterward,"},{"id":"B","label":"At the time,"},{"id":"C","label":"As a result,"},{"id":"D","label":"Similarly,"}]}'::jsonb,86,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-038","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '815be191-8c06-1595-61d2-6685b2380339','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the final sentence explains where Wallace was when the papers were read, and “At the time” signals that the two situations were simultaneous. Choice A is incorrect because Wallace was already abroad during the meeting, not only after it. Choice C is incorrect because his being abroad was the reason he missed the meeting, not a result of missing it. Choice D is incorrect because the final sentence does not describe something similar to his absence; it explains it."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='815be191-8c06-1595-61d2-6685b2380339') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ad8dced9-11ff-f642-673f-ee84f9c443fb','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Economists use the term “opportunity cost” to describe the value of the best alternative that a person gives up when making a choice. A student who works an evening shift at a café instead of studying, ______ gives up whatever benefit the extra hours of study would have brought; that benefit is the opportunity cost of the shift.","options":[{"id":"A","label":"however,"},{"id":"B","label":"in other words,"},{"id":"C","label":"for instance,"},{"id":"D","label":"similarly,"}]}'::jsonb,87,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-039","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'ad8dced9-11ff-f642-673f-ee84f9c443fb','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the student is a concrete illustration of the general definition in the first sentence, and “for instance” introduces an example. Choice A is incorrect because the example applies the definition rather than contradicting it. Choice B is incorrect because a specific case of a student is not a restatement of the abstract definition. Choice D is incorrect because “similarly” would suggest a second, parallel case, but no earlier case has been given; the student is the first and only illustration of the definition."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='ad8dced9-11ff-f642-673f-ee84f9c443fb') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8748a995-a492-2398-723b-a8e18be75b39','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"When the Brooklyn Bridge opened in 1883, its 486-meter main span was the longest of any suspension bridge in the world. Its construction had been plagued by setbacks: the original designer, John A. Roebling, died from an injury suffered while surveying the site, and his son Washington Roebling, who took over, was left partially paralyzed by decompression sickness. ______ the bridge was completed under Washington’s direction, with his wife, Emily Warren Roebling, relaying his instructions to the engineers on site.","options":[{"id":"A","label":"Consequently,"},{"id":"B","label":"For instance,"},{"id":"C","label":"Similarly,"},{"id":"D","label":"Nevertheless,"}]}'::jsonb,88,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-040","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '8748a995-a492-2398-723b-a8e18be75b39','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the bridge was finished despite the death of its designer and the illness of his successor, and “Nevertheless” signals an outcome achieved in spite of obstacles. Choice A is incorrect because the bridge’s completion was not caused by the setbacks. Choice B is incorrect because its completion is not an example of a setback. Choice C is incorrect because completing the bridge is the opposite of a setback, not something similar to one."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='8748a995-a492-2398-723b-a8e18be75b39') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4b429e21-3cdf-ce3c-af1e-5195220f8e33','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"Many plants flower only when nights reach a certain length. Botanists once described such plants as responding to the length of the day. Experiments in the 1930s and 1940s, however, showed that interrupting a long night with a brief flash of light could prevent flowering, whereas interrupting the day with a period of darkness had little effect. ______ these plants are measuring the length of uninterrupted darkness, not the length of daylight.","options":[{"id":"A","label":"Nonetheless,"},{"id":"B","label":"For instance,"},{"id":"C","label":"Similarly,"},{"id":"D","label":"Thus,"}]}'::jsonb,89,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-041","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '4b429e21-3cdf-ce3c-af1e-5195220f8e33','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the final sentence states the conclusion that follows from the experiments: since breaking the night mattered and breaking the day did not, the plants must be measuring darkness, and “Thus” introduces such a conclusion. Choice A is incorrect because the conclusion is supported by the experimental results, not reached in spite of them; the contrast with the older view has already been signaled by “however.” Choice B is incorrect because the final sentence is a general conclusion, not a specific example of the experiments. Choice C is incorrect because the final sentence does not describe a separate, parallel finding; it interprets the results just described."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='4b429e21-3cdf-ce3c-af1e-5195220f8e33') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('38bbdaca-a5f5-ac1a-a2bf-ae9fc3c92b82','d92623be-4486-274c-996a-d38ca021bd64','question_single_choice','{"prompt":"Which choice completes the text with the most logical transition?","passage":"The novelist Charles Dickens published most of his novels in monthly or weekly installments, which allowed readers of modest means to buy them a few chapters at a time. Serial publication helped make Dickens one of the most widely read authors of his era. ______ the format also had drawbacks: because each installment had to hold readers’ interest, some critics have argued that his plots contain digressions and contrived cliffhangers.","options":[{"id":"A","label":"Indeed,"},{"id":"B","label":"Therefore,"},{"id":"C","label":"That said,"},{"id":"D","label":"In other words,"}]}'::jsonb,90,'{"section_type":"reading_writing","sat_domain":"transitions","sat_official_domain":"expression_of_ideas","sat_skill":"transitions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"eoi-tr-042","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '38bbdaca-a5f5-ac1a-a2bf-ae9fc3c92b82','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the final sentence qualifies the positive account of serial publication by introducing its drawbacks, and “That said” signals such a qualification. Choice A is incorrect because “Indeed” would intensify the praise of serial publication, but the sentence introduces criticism. Choice B is incorrect because the drawbacks do not follow logically from the format’s popularity. Choice D is incorrect because the final sentence adds a new point instead of restating the previous one."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='38bbdaca-a5f5-ac1a-a2bf-ae9fc3c92b82') on conflict do nothing;
insert into public.parts(id,section_id,name,display_order) values('24c46e8c-bf57-91c3-4ec9-181a057feb7a','2dd5a6ad-d4e5-5141-982e-22469816765f','Standard English Conventions',13) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4e1108cf-606b-2cc0-afef-9ec3ef9ae56a','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"In 1928, Scottish scientist Alexander Fleming noticed something unusual in his laboratory. Mold growing on one of his culture plates had killed the bacteria around ______ observation eventually led to the development of penicillin, one of the first widely used antibiotics.","options":[{"id":"A","label":"it, this"},{"id":"B","label":"it this"},{"id":"C","label":"it and, this"},{"id":"D","label":"it; this"}]}'::jsonb,1,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '4e1108cf-606b-2cc0-afef-9ec3ef9ae56a','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because “Mold growing on one of his culture plates had killed the bacteria around it” and “this observation eventually led to the development of penicillin” are both independent clauses, and a semicolon can join two independent clauses. Choice A is incorrect because a comma alone between two independent clauses creates a comma splice. Choice B is incorrect because joining the clauses with no punctuation creates a run-on sentence. Choice C is incorrect because a comma placed after a coordinating conjunction, rather than before it, does not correctly join the clauses."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='4e1108cf-606b-2cc0-afef-9ec3ef9ae56a') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7f740eb1-8b83-e6a2-6a87-6daef8b95a21','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The Hawaiian honeycreepers are a group of birds that descended from a single ancestral species of finch. Many honeycreeper species have disappeared since humans arrived in ______ conservation groups are now working to protect the species that remain.","options":[{"id":"A","label":"Hawaii, and"},{"id":"B","label":"Hawaii and,"},{"id":"C","label":"Hawaii,"},{"id":"D","label":"Hawaii, and,"}]}'::jsonb,2,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-002","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '7f740eb1-8b83-e6a2-6a87-6daef8b95a21','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because two independent clauses can be joined by a comma followed by a coordinating conjunction such as “and.” Choice B is incorrect because the comma must come before the conjunction, not after it. Choice C is incorrect because a comma alone between two independent clauses creates a comma splice. Choice D is incorrect because no comma should follow “and” here; the extra comma separates the conjunction from the clause it introduces."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='7f740eb1-8b83-e6a2-6a87-6daef8b95a21') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('16c85d48-8db5-a5c3-cf11-3e9a33fbe31e','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Redwood National Park in northern California protects some of the tallest trees on Earth. The coast redwood nicknamed ______ about 116 meters tall, making it the tallest known living tree in the world.","options":[{"id":"A","label":"Hyperion, stands"},{"id":"B","label":"Hyperion: stands"},{"id":"C","label":"Hyperion stands"},{"id":"D","label":"Hyperion; stands"}]}'::jsonb,3,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '16c85d48-8db5-a5c3-cf11-3e9a33fbe31e','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because no punctuation should separate a subject (“The coast redwood nicknamed Hyperion”) from its verb (“stands”). The name “Hyperion” is essential to identifying which redwood is meant, so it is not set off with punctuation either. Choice A is incorrect because a single comma between the subject and the verb is not standard. Choice B is incorrect because a colon must follow an independent clause, and “The coast redwood nicknamed Hyperion” is not one. Choice D is incorrect because a semicolon separates independent clauses, not a subject from its verb."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='16c85d48-8db5-a5c3-cf11-3e9a33fbe31e') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5ce6199f-2838-3e60-16d1-f928f9baba8e','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Petra, an ancient city in present-day Jordan, is famous for monuments carved directly into rose-colored sandstone cliffs. Visitors to the site usually make a point of seeing three of its best-known ______ the Treasury, the Monastery, and the Royal Tombs.","options":[{"id":"A","label":"monuments;"},{"id":"B","label":"monuments, including:"},{"id":"C","label":"monuments"},{"id":"D","label":"monuments:"}]}'::jsonb,4,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '5ce6199f-2838-3e60-16d1-f928f9baba8e','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because a colon can follow an independent clause (“Visitors to the site usually make a point of seeing three of its best-known monuments”) to introduce a list that specifies what the clause refers to. Choice A is incorrect because a semicolon must join two independent clauses, and the list is not an independent clause. Choice B is incorrect because a colon should not separate “including” from the items it introduces. Choice C is incorrect because without punctuation the list runs directly into “monuments,” making the sentence unclear and ungrammatical."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='5ce6199f-2838-3e60-16d1-f928f9baba8e') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4906a5eb-662b-90fd-5e99-daf2e9cb98b0','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Mexican painter Frida Kahlo often explored questions of identity in her work. The Two Fridas, a double self-portrait completed in ______ two versions of the artist seated side by side and holding hands.","options":[{"id":"A","label":"1939 shows"},{"id":"B","label":"1939, shows"},{"id":"C","label":"1939; shows"},{"id":"D","label":"1939—shows"}]}'::jsonb,5,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-005","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '4906a5eb-662b-90fd-5e99-daf2e9cb98b0','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the phrase “a double self-portrait completed in 1939” is a nonessential appositive that begins with a comma, so it must end with a comma before the verb “shows.” Choice A is incorrect because without a closing comma the appositive is not properly set off from the rest of the sentence. Choice C is incorrect because a semicolon cannot separate a subject from its verb. Choice D is incorrect because a nonessential element that opens with a comma must close with a comma, not a dash."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='4906a5eb-662b-90fd-5e99-daf2e9cb98b0') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2582d406-97d6-50a2-5f87-c69c183a2bfd','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Saturn is the second-largest planet in the solar system, but it is mostly made of hydrogen and helium. Its average density is lower than that of ______ the planet would, in theory, float in a sufficiently large body of water.","options":[{"id":"A","label":"water, therefore,"},{"id":"B","label":"water therefore"},{"id":"C","label":"water; therefore,"},{"id":"D","label":"water, therefore"}]}'::jsonb,6,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '2582d406-97d6-50a2-5f87-c69c183a2bfd','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because “Its average density is lower than that of water” and “the planet would, in theory, float in a sufficiently large body of water” are independent clauses, and when a conjunctive adverb such as “therefore” joins them, it should be preceded by a semicolon and followed by a comma. Choice A is incorrect because placing commas around “therefore” creates a comma splice. Choice B is incorrect because it leaves the clauses joined with no punctuation, creating a run-on. Choice D is incorrect because a comma before “therefore” cannot join two independent clauses."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='2582d406-97d6-50a2-5f87-c69c183a2bfd') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b8581990-5139-d1cf-b63f-34e8224e5955','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Invisible Man, which follows an unnamed narrator who feels unseen by society, won the National Book Award for Fiction in 1953. The American ______ published the novel in 1952 after working on it for about seven years.","options":[{"id":"A","label":"novelist, Ralph Ellison,"},{"id":"B","label":"novelist Ralph Ellison"},{"id":"C","label":"novelist, Ralph Ellison"},{"id":"D","label":"novelist Ralph Ellison,"}]}'::jsonb,7,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'b8581990-5139-d1cf-b63f-34e8224e5955','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the name “Ralph Ellison” is essential: “The American novelist” alone does not identify which novelist is meant, so the name should not be set off with commas. Choice A is incorrect because setting off the name with commas treats it as nonessential information. Choice C is incorrect because it places a comma between the title and the name and also leaves the phrase unclosed. Choice D is incorrect because it places an unnecessary comma between the subject and the verb “published.”"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='b8581990-5139-d1cf-b63f-34e8224e5955') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('546f6595-cf2b-f353-d902-3178f6ea44bc','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The Dead Sea, which borders Jordan, Israel, and the West Bank, attracts visitors from around the world. Most come to experience three of its unusual ______ extremely salty water, a shoreline more than 400 meters below sea level, and mineral-rich mud.","options":[{"id":"A","label":"features:"},{"id":"B","label":"features;"},{"id":"C","label":"features, such as:"},{"id":"D","label":"features"}]}'::jsonb,8,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '546f6595-cf2b-f353-d902-3178f6ea44bc','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the colon follows an independent clause (“Most come to experience three of its unusual features”) and introduces a list that names the features. Choice B is incorrect because a semicolon must be followed by an independent clause, and the list is not one. Choice C is incorrect because a colon should not come between “such as” and the items it introduces. Choice D is incorrect because without punctuation the list runs into the clause, making the sentence ungrammatical."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='546f6595-cf2b-f353-d902-3178f6ea44bc') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('da0e489c-a874-cdad-aa55-ad1bf4231c66','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Each fall, millions of monarch butterflies travel from Canada and the United States to forests in central Mexico. Studies have shown ______ the insects use the position of the sun, along with an internal clock, to stay on course.","options":[{"id":"A","label":", that"},{"id":"B","label":"that,"},{"id":"C","label":": that"},{"id":"D","label":"that"}]}'::jsonb,9,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-009","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'da0e489c-a874-cdad-aa55-ad1bf4231c66','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because no punctuation is needed between a verb (“have shown”) and the clause that serves as its object (“that the insects use ...”). Choice A is incorrect because a comma should not separate a verb from its object. Choice B is incorrect because a comma should not separate “that” from the subject of the clause it introduces. Choice C is incorrect because a colon must follow an independent clause, and “Studies have shown” is incomplete without its object."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='da0e489c-a874-cdad-aa55-ad1bf4231c66') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f50650f4-9eba-e749-a15f-a38f09e30295','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Krakatoa is a volcanic island in Indonesia, between the islands of Java and Sumatra. When the volcano erupted in ______ explosion was heard thousands of kilometers away, and ash in the atmosphere produced vividly colored sunsets around the world for months.","options":[{"id":"A","label":"1883; the"},{"id":"B","label":"1883, the"},{"id":"C","label":"1883: the"},{"id":"D","label":"1883. The"}]}'::jsonb,10,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'f50650f4-9eba-e749-a15f-a38f09e30295','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because a comma correctly separates the introductory dependent clause (“When the volcano erupted in 1883”) from the main clause. Choice A is incorrect because a semicolon must join two independent clauses, and the introductory clause is dependent. Choice C is incorrect because a colon must follow an independent clause. Choice D is incorrect because a period would leave “When the volcano erupted in 1883” as a sentence fragment."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='f50650f4-9eba-e749-a15f-a38f09e30295') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('401fe27a-1296-b4c0-0f0b-b8950c462b17','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Many biologists consider the axolotl—a salamander native to lakes near Mexico ______ an ideal subject for studying regeneration, because it can regrow lost limbs and even parts of its heart.","options":[{"id":"A","label":"City,"},{"id":"B","label":"City"},{"id":"C","label":"City—"},{"id":"D","label":"City;"}]}'::jsonb,11,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '401fe27a-1296-b4c0-0f0b-b8950c462b17','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the nonessential phrase “a salamander native to lakes near Mexico City” begins with a dash, so it must end with a dash. Choice A is incorrect because a nonessential element that opens with a dash cannot close with a comma. Choice B is incorrect because without closing punctuation the phrase is not set off from the rest of the sentence. Choice D is incorrect because a semicolon cannot close a phrase that interrupts a clause."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='401fe27a-1296-b4c0-0f0b-b8950c462b17') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('505512a5-eefc-7631-b6ad-55b176b79db1','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Established in 1800, the Library of Congress in Washington, D.C., holds more than 170 million ______ collections include books, maps, photographs, sound recordings, and manuscripts in hundreds of languages.","options":[{"id":"A","label":"items, its"},{"id":"B","label":"items its"},{"id":"C","label":"items. Its"},{"id":"D","label":"items, and, its"}]}'::jsonb,12,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '505512a5-eefc-7631-b6ad-55b176b79db1','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the passage contains two independent clauses, and a period correctly separates them into two sentences. Choice A is incorrect because a comma alone between two independent clauses creates a comma splice. Choice B is incorrect because joining the clauses without punctuation creates a run-on sentence. Choice D is incorrect because no comma should follow the coordinating conjunction “and.”"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='505512a5-eefc-7631-b6ad-55b176b79db1') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e6194922-6671-561b-2b4e-9fb80396cd70','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"When the first preserved platypus specimens reached Britain in the late 1700s, the animal’s duck-like bill and furry body seemed impossible to many observers. Some of the European ______ first examined the specimens suspected that they were hoaxes stitched together from different animals.","options":[{"id":"A","label":"scientists, who"},{"id":"B","label":"scientists who"},{"id":"C","label":"scientists who,"},{"id":"D","label":"scientists; who"}]}'::jsonb,13,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-013","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'e6194922-6671-561b-2b4e-9fb80396cd70','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the clause “who first examined the specimens” is essential: it identifies which scientists suspected a hoax, so it should not be set off with commas. Choice A is incorrect because a comma would treat the clause as nonessential, leaving the sentence to claim, illogically, that some European scientists in general suspected a hoax and that they all first examined the specimens. Choice C is incorrect because a comma should not separate “who” from the verb it governs. Choice D is incorrect because a semicolon must join independent clauses."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='e6194922-6671-561b-2b4e-9fb80396cd70') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1340768d-7c70-cb0d-80fe-2aec58978317','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The Silk Road was not a single road but a network of trade routes linking China with the Mediterranean ______ merchants carried silk, spices, paper, and ideas along its many branches for more than a thousand years.","options":[{"id":"A","label":"world, merchants"},{"id":"B","label":"world merchants"},{"id":"C","label":"world, and, merchants"},{"id":"D","label":"world; merchants"}]}'::jsonb,14,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-014","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '1340768d-7c70-cb0d-80fe-2aec58978317','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the sentence contains two independent clauses, and a semicolon correctly joins them. Choice A is incorrect because a comma alone between the clauses creates a comma splice. Choice B is incorrect because no punctuation between the clauses creates a run-on sentence. Choice C is incorrect because a comma should not follow the coordinating conjunction “and.”"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='1340768d-7c70-cb0d-80fe-2aec58978317') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6aeaa5cc-9473-0f03-207c-74b03bd8df59','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Washi, a traditional Japanese paper, is prized for its strength and texture. The ingredients used to make it ______ the inner bark of the kozo shrub, water, and a sticky plant extract that helps disperse the fibers evenly.","options":[{"id":"A","label":"include"},{"id":"B","label":"include:"},{"id":"C","label":"include;"},{"id":"D","label":"include,"}]}'::jsonb,15,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-015","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '6aeaa5cc-9473-0f03-207c-74b03bd8df59','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because no punctuation should separate a verb (“include”) from its objects (the list of ingredients). Choice B is incorrect because a colon must follow an independent clause, and “The ingredients used to make it include” is incomplete without its objects. Choice C is incorrect because a semicolon must join independent clauses. Choice D is incorrect because a comma should not separate a verb from its objects."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='6aeaa5cc-9473-0f03-207c-74b03bd8df59') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a0a07f85-631c-ac9c-4036-4ea58f0bfb79','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Born in Texas in 1892, Bessie Coleman dreamed of flying at a time when few women were allowed to train as pilots. Coleman, the first African American woman to earn a pilot’s ______ to travel to France for her training because no flight school in the United States would admit her.","options":[{"id":"A","label":"license had"},{"id":"B","label":"license; had"},{"id":"C","label":"license, had"},{"id":"D","label":"license—had"}]}'::jsonb,16,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-016","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'a0a07f85-631c-ac9c-4036-4ea58f0bfb79','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the appositive “the first African American woman to earn a pilot’s license” begins with a comma and must end with one before the verb “had.” Choice A is incorrect because the appositive is not closed. Choice B is incorrect because a semicolon cannot separate a subject from its verb. Choice D is incorrect because an appositive that opens with a comma cannot close with a dash."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='a0a07f85-631c-ac9c-4036-4ea58f0bfb79') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5e281cb4-4e43-12f1-0467-61a59d4ef329','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Built over roughly two decades in the seventeenth ______ Taj Mahal in Agra, India, was commissioned by the Mughal emperor Shah Jahan as a tomb for the empress Mumtaz Mahal.","options":[{"id":"A","label":"century; the"},{"id":"B","label":"century. The"},{"id":"C","label":"century: the"},{"id":"D","label":"century, the"}]}'::jsonb,17,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-017","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '5e281cb4-4e43-12f1-0467-61a59d4ef329','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because a comma correctly separates the introductory participial phrase (“Built over roughly two decades in the seventeenth century”) from the main clause. Choice A is incorrect because a semicolon must join independent clauses, and the introductory phrase is not one. Choice B is incorrect because a period would leave the introductory phrase as a fragment. Choice C is incorrect because a colon must follow an independent clause."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='5e281cb4-4e43-12f1-0467-61a59d4ef329') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('74c78691-3abc-1f92-f757-a2b0714d4693','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The Svalbard Global ______ secure storage facility built inside a mountain on a remote Norwegian island in the Arctic—holds backup copies of seeds from gene banks around the world.","options":[{"id":"A","label":"Seed Vault, a"},{"id":"B","label":"Seed Vault—a"},{"id":"C","label":"Seed Vault a"},{"id":"D","label":"Seed Vault; a"}]}'::jsonb,18,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-018","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '74c78691-3abc-1f92-f757-a2b0714d4693','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the nonessential phrase describing the vault ends with a dash after “Arctic,” so it must also begin with a dash. Choice A is incorrect because a nonessential element cannot open with a comma and close with a dash. Choice C is incorrect because without opening punctuation the phrase is not set off from the subject it describes. Choice D is incorrect because a semicolon cannot separate a subject from the phrase that describes it."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='74c78691-3abc-1f92-f757-a2b0714d4693') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8a918c9b-57c1-9eee-e986-086c94586641','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Most people picture deserts as hot, sandy places such as the Sahara. Antarctica, ______ is also classified as a desert because it receives very little precipitation each year.","options":[{"id":"A","label":"however,"},{"id":"B","label":"however"},{"id":"C","label":"however;"},{"id":"D","label":"however:"}]}'::jsonb,19,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-019","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '8a918c9b-57c1-9eee-e986-086c94586641','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because “however” interrupts the clause between the subject “Antarctica” and the verb “is,” so it must be set off by a pair of commas; the first comma is already in place. Choice B is incorrect because it leaves “however” without its closing comma. Choice C is incorrect because a semicolon cannot separate a subject from its verb. Choice D is incorrect because a colon cannot separate a subject from its verb."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='8a918c9b-57c1-9eee-e986-086c94586641') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f6d7f7f6-6d7b-04b1-4f6a-8f7538d863ab','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Early telescopes produced images with blurry colored fringes because their glass lenses bent different colors of light by different ______ Isaac Newton designed a telescope that gathered light with a curved mirror instead of a lens.","options":[{"id":"A","label":"amounts; to avoid this problem,"},{"id":"B","label":"amounts, to avoid this problem,"},{"id":"C","label":"amounts to avoid this problem,"},{"id":"D","label":"amounts, to avoid this problem;"}]}'::jsonb,20,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-020","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'f6d7f7f6-6d7b-04b1-4f6a-8f7538d863ab','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the sentence contains two independent clauses, and a semicolon correctly separates them; the comma after the introductory phrase “to avoid this problem” is also appropriate. Choice B is incorrect because a comma alone between the clauses creates a comma splice. Choice C is incorrect because it creates a run-on sentence and wrongly attaches “to avoid this problem” to the first clause, as if the lenses bent light in order to avoid a problem. Choice D is incorrect because the semicolon cuts off the introductory phrase from the clause it modifies and leaves the first clause joined to that phrase illogically."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='f6d7f7f6-6d7b-04b1-4f6a-8f7538d863ab') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3a06aeea-1b66-5805-34b6-430ab8b30224','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Each modern Summer Olympic Games is assigned to a single host city. The Summer Games of 1992, 1996, and 2000 were held in Barcelona, ______ Atlanta, United States; and Sydney, Australia.","options":[{"id":"A","label":"Spain,"},{"id":"B","label":"Spain;"},{"id":"C","label":"Spain:"},{"id":"D","label":"Spain"}]}'::jsonb,21,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-021","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '3a06aeea-1b66-5805-34b6-430ab8b30224','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the items in this list already contain commas (city, country), so semicolons are needed to separate the items, as they are between “United States” and “and Sydney.” Choice A is incorrect because a comma here would make it unclear where one item ends and the next begins. Choice C is incorrect because a colon does not separate items in a list. Choice D is incorrect because omitting punctuation runs the first two items together."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='3a06aeea-1b66-5805-34b6-430ab8b30224') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7b1a898c-7e1d-6bee-c2ac-652d47ea96e2','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Computer and television screens create images by mixing light. The three primary colors of ______ green, and blue—can be combined in different proportions to produce nearly any color a viewer can see on a screen.","options":[{"id":"A","label":"light, red,"},{"id":"B","label":"light: red,"},{"id":"C","label":"light—red,"},{"id":"D","label":"light red,"}]}'::jsonb,22,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-022","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '7b1a898c-7e1d-6bee-c2ac-652d47ea96e2','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the list “red, green, and blue” is a nonessential interruption between the subject and the verb that ends with a dash, so it must also begin with a dash. Choice A is incorrect because a comma here, together with the commas inside the list, makes the sentence’s structure unclear and fails to match the closing dash. Choice B is incorrect because a colon must follow an independent clause, and “The three primary colors of light” is not one. Choice D is incorrect because without punctuation “light red” reads as a single color rather than the start of a list."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='7b1a898c-7e1d-6bee-c2ac-652d47ea96e2') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('59ad0f5c-f121-1285-210f-46e81f1c1ba3','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Ancient Egyptian builders faced a daunting challenge in constructing the pyramids at ______ moving limestone and granite blocks, some weighing several tons, across long distances and lifting them into place without iron tools or pulleys.","options":[{"id":"A","label":"Giza;"},{"id":"B","label":"Giza, and"},{"id":"C","label":"Giza"},{"id":"D","label":"Giza:"}]}'::jsonb,23,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-023","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '59ad0f5c-f121-1285-210f-46e81f1c1ba3','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because a colon can follow an independent clause (“Ancient Egyptian builders faced a daunting challenge in constructing the pyramids at Giza”) to introduce an explanation of what the challenge was. Choice A is incorrect because a semicolon must be followed by an independent clause, and the phrase beginning “moving limestone” is not one. Choice B is incorrect because “and” wrongly joins the clause to a phrase that has no verb of its own. Choice C is incorrect because without punctuation the explanation runs into the clause, suggesting nonsensically that Giza was moving the blocks."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='59ad0f5c-f121-1285-210f-46e81f1c1ba3') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('775c5c3e-da8e-47a3-552b-ae3350689f83','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"A hummingbird’s heart can beat more than 1,000 times per minute during flight. Hummingbirds have some of the highest metabolic rates of any ______ they must feed frequently throughout the day, sometimes visiting hundreds of flowers.","options":[{"id":"A","label":"animals, consequently,"},{"id":"B","label":"animals; consequently,"},{"id":"C","label":"animals consequently,"},{"id":"D","label":"animals, consequently;"}]}'::jsonb,24,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-024","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '775c5c3e-da8e-47a3-552b-ae3350689f83','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because two independent clauses joined by the conjunctive adverb “consequently” require a semicolon before the adverb and a comma after it. Choice A is incorrect because commas alone create a comma splice. Choice C is incorrect because it joins the clauses with no punctuation before “consequently,” creating a run-on. Choice D is incorrect because it places the semicolon after “consequently,” attaching the adverb to the wrong clause and leaving a comma splice before it."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='775c5c3e-da8e-47a3-552b-ae3350689f83') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c312e394-08fa-f8ff-9473-22edec736c3b','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"In June 1963, Soviet cosmonaut Valentina Tereshkova became the first woman to travel to space. Her ______ orbited Earth 48 times over nearly three days before returning safely to the ground.","options":[{"id":"A","label":"spacecraft, Vostok 6,"},{"id":"B","label":"spacecraft Vostok 6,"},{"id":"C","label":"spacecraft, Vostok 6"},{"id":"D","label":"spacecraft; Vostok 6,"}]}'::jsonb,25,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-025","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'c312e394-08fa-f8ff-9473-22edec736c3b','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because Tereshkova flew in only one spacecraft on this mission, so its name, “Vostok 6,” is nonessential information about “Her spacecraft” and must be set off by a pair of commas. Choice B is incorrect because it places a comma between the subject and the verb without an opening comma. Choice C is incorrect because it opens the appositive with a comma but does not close it. Choice D is incorrect because a semicolon cannot separate a noun from its appositive."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='c312e394-08fa-f8ff-9473-22edec736c3b') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8ce22dc7-a092-abea-a69a-4efb228fb708','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Some of the oldest evidence of humans in the Americas may come from an ancient lakebed in the southwestern United States. The fossilized footprints that researchers discovered at White Sands National Park in New ______ that humans were present in North America more than 21,000 years ago.","options":[{"id":"A","label":"Mexico, suggest"},{"id":"B","label":"Mexico; suggest"},{"id":"C","label":"Mexico suggest"},{"id":"D","label":"Mexico—suggest"}]}'::jsonb,26,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-026","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '8ce22dc7-a092-abea-a69a-4efb228fb708','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because no punctuation should separate the long subject (“The fossilized footprints that researchers discovered at White Sands National Park in New Mexico”) from its verb, “suggest.” Choice A is incorrect because a single comma between a subject and its verb is not standard. Choice B is incorrect because a semicolon cannot separate a subject from its verb. Choice D is incorrect because a dash cannot separate a subject from its verb here."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='8ce22dc7-a092-abea-a69a-4efb228fb708') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('70492c35-0423-210f-8ffc-dc80fe401a4c','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The Hope Diamond, now housed at the Smithsonian Institution, appears deep blue in ordinary light. Under ultraviolet ______ the gem glows a vivid orange-red for several seconds after the ultraviolet source is switched off.","options":[{"id":"A","label":"light; however,"},{"id":"B","label":"light, however,"},{"id":"C","label":"light however,"},{"id":"D","label":"light, however;"}]}'::jsonb,27,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-027","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '70492c35-0423-210f-8ffc-dc80fe401a4c','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the second sentence is a single independent clause in which “however” follows the introductory phrase “Under ultraviolet light”; commas correctly set the word off. Choice A is incorrect because a semicolon must separate independent clauses, and “Under ultraviolet light” is only a phrase. Choice C is incorrect because “however” must be set off by commas on both sides. Choice D is incorrect because the semicolon splits the introductory phrase from the clause it belongs to."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='70492c35-0423-210f-8ffc-dc80fe401a4c') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3f8de644-d239-331b-2676-3a8b579e5180','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The bar-tailed godwit, a shorebird, makes one of the longest nonstop migrations of any land ______ 2022, a tagged juvenile flew from Alaska to Tasmania without stopping, covering more than 13,000 kilometers in about eleven days.","options":[{"id":"A","label":"bird, in"},{"id":"B","label":"bird: in"},{"id":"C","label":"bird in"},{"id":"D","label":"bird, which in"}]}'::jsonb,28,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-028","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '3f8de644-d239-331b-2676-3a8b579e5180','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because a colon can join two independent clauses when the second illustrates or explains the first; the record-setting flight illustrates the godwit’s long migrations. Choice A is incorrect because a comma alone between the two independent clauses creates a comma splice. Choice C is incorrect because without punctuation the clauses run together. Choice D is incorrect because “which” turns the second clause into a relative clause that has no logical place for its pronoun, producing an ungrammatical sentence."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='3f8de644-d239-331b-2676-3a8b579e5180') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b5461eb4-83ec-bccd-4027-1a640956ae44','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"From the thirteenth to the fifteenth century, much of northern Europe’s trade passed through a small number of port cities. The Hanseatic ______ commercial alliance of merchant guilds and market towns, dominated trade on the Baltic Sea during this period.","options":[{"id":"A","label":"League, a"},{"id":"B","label":"League—a"},{"id":"C","label":"League; a"},{"id":"D","label":"League a"}]}'::jsonb,29,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-029","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'b5461eb4-83ec-bccd-4027-1a640956ae44','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the appositive “a commercial alliance of merchant guilds and market towns” ends with a comma before the verb “dominated,” so it must also begin with a comma. Choice B is incorrect because an appositive that closes with a comma cannot open with a dash. Choice C is incorrect because a semicolon cannot separate a noun from its appositive. Choice D is incorrect because the appositive must be set off from the noun it renames."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='b5461eb4-83ec-bccd-4027-1a640956ae44') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('56b455ed-da92-b0a1-dd72-9fdb2825edef','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Mount Everest, at about 8,849 meters, is the highest mountain above sea ______ is not the tallest mountain measured from base to peak; that distinction belongs to Mauna Kea in Hawaii, much of which lies beneath the ocean.","options":[{"id":"A","label":"level, it"},{"id":"B","label":"level it"},{"id":"C","label":"level, yet, it"},{"id":"D","label":"level, yet it"}]}'::jsonb,30,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-030","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '56b455ed-da92-b0a1-dd72-9fdb2825edef','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because two independent clauses can be joined by a comma followed by a coordinating conjunction, here “yet,” which also signals the contrast. Choice A is incorrect because a comma alone between independent clauses creates a comma splice. Choice B is incorrect because no punctuation creates a run-on. Choice C is incorrect because a comma should not follow the coordinating conjunction “yet.”"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='56b455ed-da92-b0a1-dd72-9fdb2825edef') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d4c463c9-7fa2-4ba6-d191-6b9e6873ebea','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The Japanese artist Katsushika Hokusai produced thousands of works over a career lasting about seventy years. Hokusai’s ______ depicts three boats beneath an enormous wave, with Mount Fuji visible in the distance.","options":[{"id":"A","label":"woodblock print, The Great Wave off Kanagawa,"},{"id":"B","label":"woodblock print, The Great Wave off Kanagawa"},{"id":"C","label":"woodblock print The Great Wave off Kanagawa"},{"id":"D","label":"woodblock print The Great Wave off Kanagawa,"}]}'::jsonb,31,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-031","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'd4c463c9-7fa2-4ba6-d191-6b9e6873ebea','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because Hokusai made many woodblock prints, so the title is essential to identify which print is meant and should not be set off with commas. Choice A is incorrect because commas around the title would wrongly suggest that Hokusai made only one woodblock print. Choice B is incorrect because it opens with a comma that is never closed. Choice D is incorrect because it places a comma between the subject and the verb “depicts.”"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='d4c463c9-7fa2-4ba6-d191-6b9e6873ebea') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f96cabea-99d3-4a8c-0025-35b7e34b2f62','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Mammals that lay eggs rather than giving birth to live young are called monotremes. The platypus and the four species of ______ the only living monotremes, and all of them live in Australia or New Guinea.","options":[{"id":"A","label":"echidna, are"},{"id":"B","label":"echidna: are"},{"id":"C","label":"echidna; are"},{"id":"D","label":"echidna are"}]}'::jsonb,32,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-032","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'f96cabea-99d3-4a8c-0025-35b7e34b2f62','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because no punctuation should separate the compound subject (“The platypus and the four species of echidna”) from its verb, “are.” Choice A is incorrect because a comma between the subject and the verb is not standard. Choice B is incorrect because a colon must follow an independent clause. Choice C is incorrect because a semicolon cannot separate a subject from its verb."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='f96cabea-99d3-4a8c-0025-35b7e34b2f62') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f036c259-a0d0-bec9-8177-468925ec11d1','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Some of the world’s oldest known musical instruments are flutes carved from materials such ______ bird bone and mammoth ivory; examples found in caves in southern Germany are more than 35,000 years old.","options":[{"id":"A","label":"as:"},{"id":"B","label":"as,"},{"id":"C","label":"as;"},{"id":"D","label":"as"}]}'::jsonb,33,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-033","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'f036c259-a0d0-bec9-8177-468925ec11d1','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because no punctuation should separate “such as” from the examples it introduces. Choice A is incorrect because a colon must follow an independent clause and should not come after “such as.” Choice B is incorrect because a comma should not separate “such as” from its examples. Choice C is incorrect because a semicolon must join independent clauses, and “as” does not end one."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='f036c259-a0d0-bec9-8177-468925ec11d1') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7c0ee1e9-9115-7417-d6b7-74f2e56d1a3c','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"In her 1962 book Silent Spring, the biologist Rachel Carson described ______ widespread use of the pesticide DDT was harming birds, fish, and other wildlife. The book helped inspire the modern environmental movement.","options":[{"id":"A","label":"how, the"},{"id":"B","label":"how the"},{"id":"C","label":", how the"},{"id":"D","label":"how: the"}]}'::jsonb,34,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-034","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '7c0ee1e9-9115-7417-d6b7-74f2e56d1a3c','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the clause beginning with “how” is the object of the verb “described,” and no punctuation should separate a verb from its object or split the clause after “how.” Choice A is incorrect because a comma should not separate “how” from the rest of its clause. Choice C is incorrect because a comma should not separate a verb from its object. Choice D is incorrect because a colon should not separate “how” from the rest of its clause."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='7c0ee1e9-9115-7417-d6b7-74f2e56d1a3c') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('53f71134-8676-ead2-f2e9-46d322b10fde','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Some plants respond to touch with surprising speed. The leaves of the sensitive plant, Mimosa pudica, fold inward within seconds when brushed by an insect or a human ______ the leaves of the Venus flytrap snap shut in less than a second when an insect touches the trigger hairs inside them.","options":[{"id":"A","label":"hand, similarly,"},{"id":"B","label":"hand similarly,"},{"id":"C","label":"hand, similarly"},{"id":"D","label":"hand; similarly,"}]}'::jsonb,35,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-035","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '53f71134-8676-ead2-f2e9-46d322b10fde','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the two independent clauses are joined by the conjunctive adverb “similarly,” which requires a semicolon before it and a comma after it. Choice A is incorrect because a comma before “similarly” creates a comma splice. Choice B is incorrect because it joins the clauses without punctuation, creating a run-on. Choice C is incorrect because it creates a comma splice: a comma alone cannot join two independent clauses."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='53f71134-8676-ead2-f2e9-46d322b10fde') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7800b938-a866-49ba-2bcd-c8f0d397e034','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Medieval scribes sometimes reused old parchment, which was expensive to produce, by scraping off the original ______ recycled manuscript of this kind is called a palimpsest, and traces of the earlier text can often be recovered with special imaging.","options":[{"id":"A","label":"writing; a"},{"id":"B","label":"writing, a"},{"id":"C","label":"writing a"},{"id":"D","label":"writing, and, a"}]}'::jsonb,36,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-036","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '7800b938-a866-49ba-2bcd-c8f0d397e034','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because a semicolon correctly joins the two independent clauses. Choice B is incorrect because a comma alone between the clauses creates a comma splice. Choice C is incorrect because no punctuation creates a run-on sentence. Choice D is incorrect because no comma should follow the coordinating conjunction “and.”"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='7800b938-a866-49ba-2bcd-c8f0d397e034') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d578c901-959a-1e85-3e75-e6769734e3f3','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The active ingredient in aspirin is related to a compound found in willow bark, which people used for centuries to relieve ______ chemists did not produce a stable synthetic form of the drug until 1897.","options":[{"id":"A","label":"pain but,"},{"id":"B","label":"pain, but,"},{"id":"C","label":"pain, but"},{"id":"D","label":"pain; but,"}]}'::jsonb,37,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-037","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'd578c901-959a-1e85-3e75-e6769734e3f3','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because two independent clauses can be joined by a comma followed by the coordinating conjunction “but.” Choice A is incorrect because the comma must precede “but,” not follow it. Choice B is incorrect because no comma should follow “but.” Choice D is incorrect because no comma should follow “but.”"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='d578c901-959a-1e85-3e75-e6769734e3f3') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('00d0ecdc-688c-ca07-9ab8-34840ed8a5af','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Astronomers measure the abundance of chemical elements by analyzing the light given off by stars and clouds of gas. Hydrogen, helium, and ______ the three most abundant elements in the Milky Way by mass.","options":[{"id":"A","label":"oxygen are"},{"id":"B","label":"oxygen, are"},{"id":"C","label":"oxygen; are"},{"id":"D","label":"oxygen: are"}]}'::jsonb,38,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-038","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '00d0ecdc-688c-ca07-9ab8-34840ed8a5af','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because no punctuation should separate the subject (“Hydrogen, helium, and oxygen”) from its verb, “are.” Choice B is incorrect because a comma should not follow the final item of a list that serves as the subject. Choice C is incorrect because a semicolon cannot separate a subject from its verb. Choice D is incorrect because a colon must follow an independent clause."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='00d0ecdc-688c-ca07-9ab8-34840ed8a5af') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b70a36da-507c-7de2-6c71-1a8e99cb05f7','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Long before the magnetic compass reached the Pacific, Polynesian navigators sailed thousands of kilometers across open ocean using only natural ______ the positions of rising and setting stars, the patterns of ocean swells, and the flight paths of seabirds.","options":[{"id":"A","label":"clues; such as"},{"id":"B","label":"clues, these were"},{"id":"C","label":"clues—"},{"id":"D","label":"clues, such as:"}]}'::jsonb,39,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-039","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'b70a36da-507c-7de2-6c71-1a8e99cb05f7','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because a dash can follow an independent clause to introduce a list that explains it, here the clues the navigators used. Choice A is incorrect because a semicolon must be followed by an independent clause. Choice B is incorrect because it creates a comma splice by joining two independent clauses with only a comma. Choice D is incorrect because a colon should not come between “such as” and its examples."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='b70a36da-507c-7de2-6c71-1a8e99cb05f7') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('bba24cb8-9ba8-4a58-40a3-db53f9f9e59f','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The Wright brothers’ first powered flight, on December 17, 1903, lasted only 12 seconds and covered about 37 ______ made three more flights that same day, the longest of which lasted 59 seconds.","options":[{"id":"A","label":"meters, they"},{"id":"B","label":"meters they"},{"id":"C","label":"meters, and, they"},{"id":"D","label":"meters; they"}]}'::jsonb,40,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-040","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'bba24cb8-9ba8-4a58-40a3-db53f9f9e59f','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because a semicolon correctly joins the two independent clauses. Choice A is incorrect because a comma alone between the clauses creates a comma splice. Choice B is incorrect because no punctuation creates a run-on sentence. Choice C is incorrect because no comma should follow the coordinating conjunction “and.”"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='bba24cb8-9ba8-4a58-40a3-db53f9f9e59f') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c133bcc0-3ebe-f044-07d6-0aef6864e06d','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Although the Rosetta Stone is often associated with the era of the great ______ was inscribed in 196 BCE, more than two thousand years after the pyramids at Giza were built.","options":[{"id":"A","label":"pyramids, it"},{"id":"B","label":"pyramids. It"},{"id":"C","label":"pyramids; it"},{"id":"D","label":"pyramids: it"}]}'::jsonb,41,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-041","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'c133bcc0-3ebe-f044-07d6-0aef6864e06d','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because a comma correctly separates the introductory dependent clause (“Although the Rosetta Stone is often associated with the era of the great pyramids”) from the main clause. Choice B is incorrect because a period would leave the dependent clause as a fragment. Choice C is incorrect because a semicolon must join independent clauses, and the “Although” clause is dependent. Choice D is incorrect because a colon must follow an independent clause, and the “Although” clause is dependent."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='c133bcc0-3ebe-f044-07d6-0aef6864e06d') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b6ee3122-b919-b6fe-4417-b37e88668f5f','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Most of the energy that powers Earth’s weather comes from sunlight absorbed by the oceans, land, and atmosphere. The energy that drives plate ______ comes largely from heat inside the planet, some of it left over from Earth’s formation and some produced by the decay of radioactive elements.","options":[{"id":"A","label":"tectonics; however,"},{"id":"B","label":"tectonics, however,"},{"id":"C","label":"tectonics however,"},{"id":"D","label":"tectonics, however"}]}'::jsonb,42,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-042","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'b6ee3122-b919-b6fe-4417-b37e88668f5f','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because “however” interrupts a single independent clause, falling between the subject (“The energy that drives plate tectonics”) and the verb (“comes”), so it must be set off by a pair of commas. Choice A is incorrect because a semicolon must separate two independent clauses, and “The energy that drives plate tectonics” is not one. Choice C is incorrect because “however” needs a comma before it as well as after it. Choice D is incorrect because it leaves “however” without a closing comma, so the interruption is not fully set off from the verb."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='b6ee3122-b919-b6fe-4417-b37e88668f5f') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('19925d28-1086-b18d-7450-a5eaee5b2d4a','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The exhibition brings together works by three artists who transformed twentieth-century printmaking: Käthe Kollwitz, a German artist known for her powerful images of grief and ______ Elizabeth Catlett, an American-born sculptor and printmaker who spent much of her career in Mexico; and M. C. Escher, a Dutch artist famous for his mathematically inspired designs.","options":[{"id":"A","label":"poverty,"},{"id":"B","label":"poverty:"},{"id":"C","label":"poverty;"},{"id":"D","label":"poverty—"}]}'::jsonb,43,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-043","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '19925d28-1086-b18d-7450-a5eaee5b2d4a','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because each item in this list contains internal commas (a name followed by a descriptive phrase), so the items must be separated by semicolons, matching the semicolon after “Mexico.” Choice A is incorrect because a comma would make it impossible to tell where the first artist’s description ends and the next item begins. Choice B is incorrect because a colon does not separate items in a list. Choice D is incorrect because a dash does not separate items in a list and does not match the semicolon used later."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='19925d28-1086-b18d-7450-a5eaee5b2d4a') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('706a0f05-040b-60f2-686a-3a89aaa8cd7c','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The octopus has an unusual nervous system: of its roughly 500 million neurons, about two-thirds are located not in its brain but in its ______ allows each arm to respond to touch and taste with a surprising degree of independence.","options":[{"id":"A","label":"arms; an arrangement that"},{"id":"B","label":"arms, this arrangement"},{"id":"C","label":"arms an arrangement that"},{"id":"D","label":"arms, an arrangement that"}]}'::jsonb,44,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-044","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '706a0f05-040b-60f2-686a-3a89aaa8cd7c','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because “an arrangement that allows each arm to respond ...” is a phrase that renames and comments on the preceding clause, and a comma correctly sets it off. Choice A is incorrect because a semicolon must be followed by an independent clause, and “an arrangement that allows ...” lacks a main verb of its own. Choice B is incorrect because “this arrangement allows ...” is an independent clause, so joining it to the preceding clause with only a comma creates a comma splice. Choice C is incorrect because without a comma the phrase runs into the clause, blurring the sentence’s structure."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='706a0f05-040b-60f2-686a-3a89aaa8cd7c') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f6988d11-14cc-6570-b595-6499eaed2449','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Concern about the effects of certain pesticides on pollinators has grown in recent decades. The question that the research team, led by ecologists at two universities, hoped to ______ whether bees exposed to a common pesticide could still find their way back to their hives.","options":[{"id":"A","label":"answer, was"},{"id":"B","label":"answer: was"},{"id":"C","label":"answer was"},{"id":"D","label":"answer—was"}]}'::jsonb,45,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-045","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'f6988d11-14cc-6570-b595-6499eaed2449','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the subject (“The question that the research team ... hoped to answer”) must not be separated from its verb, “was”; the interrupting phrase “led by ecologists at two universities” is already set off by its own pair of commas. Choice A is incorrect because the comma would separate the subject from its verb. Choice B is incorrect because a colon must follow an independent clause, and the long subject is not one. Choice D is incorrect because a dash would also separate the subject from its verb."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='f6988d11-14cc-6570-b595-6499eaed2449') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('dda00d61-f98a-4fd7-526b-20aafd3247f0','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Early photographic processes required exposure times of several minutes, during which subjects had to remain perfectly ______ the 1850s, improved chemistry had shortened exposures to a few seconds, making portrait studios far more practical.","options":[{"id":"A","label":"still, by"},{"id":"B","label":"still. By"},{"id":"C","label":"still by"},{"id":"D","label":"still, and, by"}]}'::jsonb,46,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-046","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'dda00d61-f98a-4fd7-526b-20aafd3247f0','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the passage contains two independent clauses, and a period correctly separates them; “By the 1850s” then begins the second sentence as an introductory phrase. Choice A is incorrect because a comma alone between the clauses creates a comma splice. Choice C is incorrect because without punctuation “by the 1850s” seems to attach to the first clause, and the two clauses run together. Choice D is incorrect because no comma should follow the coordinating conjunction “and.”"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='dda00d61-f98a-4fd7-526b-20aafd3247f0') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f34a96a8-15ae-5d18-ea6e-d781a7cf8a92','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Paintings ______ the Dutch artist Johannes Vermeer number only about 35, a remarkably small output for a career that lasted roughly two decades. That scarcity has made each work enormously valuable.","options":[{"id":"A","label":"attributed to"},{"id":"B","label":", attributed to"},{"id":"C","label":", attributed to,"},{"id":"D","label":"attributed to,"}]}'::jsonb,47,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-047","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'f34a96a8-15ae-5d18-ea6e-d781a7cf8a92','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the phrase “attributed to the Dutch artist Johannes Vermeer” is essential: it identifies which paintings number only about 35, so it should not be set off with punctuation. Choice B is incorrect because it separates the subject “Paintings” from the essential phrase that defines it, and the comma is never closed. Choice C is incorrect because it places a comma between “attributed to” and its object. Choice D is incorrect because a comma should not separate a preposition from its object."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='f34a96a8-15ae-5d18-ea6e-d781a7cf8a92') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0ab97638-a585-4b1e-9cb4-f76f8a1daaa8','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The Code of Hammurabi—a set of nearly 300 laws issued by the Babylonian king Hammurabi around 1750 BCE and inscribed on a basalt stele that is now housed in the Louvre ______ one of the earliest and most complete written legal codes known to historians.","options":[{"id":"A","label":"Museum—is"},{"id":"B","label":"Museum, is"},{"id":"C","label":"Museum is"},{"id":"D","label":"Museum; is"}]}'::jsonb,48,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-048","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '0ab97638-a585-4b1e-9cb4-f76f8a1daaa8','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the long nonessential phrase that describes the Code of Hammurabi begins with a dash after “Hammurabi,” so it must end with a dash before the verb “is.” Choice B is incorrect because a nonessential element that opens with a dash cannot close with a comma. Choice C is incorrect because the interruption is never closed, so the verb is not separated from the descriptive phrase. Choice D is incorrect because a semicolon cannot separate a subject from its verb."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='0ab97638-a585-4b1e-9cb4-f76f8a1daaa8') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f5d311ac-4b9e-e1a2-95db-65bf6f15e507','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Glass appears to be a solid, and in everyday terms it is ______ its atoms lack the orderly, repeating arrangement found in crystalline solids such as quartz, which is why scientists classify it as an amorphous solid.","options":[{"id":"A","label":"one, at the molecular level, however,"},{"id":"B","label":"one; at the molecular level, however,"},{"id":"C","label":"one; at the molecular level however,"},{"id":"D","label":"one at the molecular level, however,"}]}'::jsonb,49,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-049","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'f5d311ac-4b9e-e1a2-95db-65bf6f15e507','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because a semicolon correctly separates the two independent clauses, and the interrupting word “however” is set off by commas within the second clause. Choice A is incorrect because the commas create a comma splice between the two independent clauses. Choice C is incorrect because “however” interrupts the clause and must be set off by commas on both sides. Choice D is incorrect because it attaches “at the molecular level” to the first clause, which contradicts the point that glass differs from crystalline solids at the molecular level, and it joins the clauses with only commas, creating a comma splice."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='f5d311ac-4b9e-e1a2-95db-65bf6f15e507') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('13a9f647-af4e-b34d-ce0d-53f4fdf5e5c3','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Languages that have no demonstrable relationship to any other living or recorded language, such as Basque in southwestern Europe and Burushaski in northern ______ called language isolates.","options":[{"id":"A","label":"Pakistan are"},{"id":"B","label":"Pakistan; are"},{"id":"C","label":"Pakistan, are"},{"id":"D","label":"Pakistan—are"}]}'::jsonb,50,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-050","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '13a9f647-af4e-b34d-ce0d-53f4fdf5e5c3','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the nonessential phrase “such as Basque in southwestern Europe and Burushaski in northern Pakistan” begins with a comma and must end with a comma before the verb “are.” Choice A is incorrect because the nonessential phrase is not closed. Choice B is incorrect because a semicolon cannot separate a subject from its verb. Choice D is incorrect because a phrase that opens with a comma cannot close with a dash."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='13a9f647-af4e-b34d-ce0d-53f4fdf5e5c3') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3b889ecd-9b0f-682a-5db1-3ae9eec9f256','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The Atacama Large Millimeter/submillimeter Array, a group of 66 radio antennas that engineers can move across a high plateau in northern Chile to change the array’s ______ researchers to study the cold gas and dust from which stars and planets form.","options":[{"id":"A","label":"resolution allows"},{"id":"B","label":"resolution; allows"},{"id":"C","label":"resolution—allows"},{"id":"D","label":"resolution, allows"}]}'::jsonb,51,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-051","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '3b889ecd-9b0f-682a-5db1-3ae9eec9f256','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the long appositive describing the array begins with a comma after “Array” and must end with a comma before the verb “allows.” Choice A is incorrect because the appositive is not closed, so it runs into the verb. Choice B is incorrect because a semicolon cannot separate a subject from its verb. Choice C is incorrect because an appositive that opens with a comma cannot close with a dash."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='3b889ecd-9b0f-682a-5db1-3ae9eec9f256') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('068b1320-0bc2-df24-f9c6-a3629d654088','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Many of the workers in the textile mills of Lowell, Massachusetts, in the 1840s were young women recruited from farms across rural New ______ some of these workers wrote and published a literary magazine, the Lowell Offering, featuring their own essays, poems, and stories.","options":[{"id":"A","label":"England, remarkably,"},{"id":"B","label":"England remarkably,"},{"id":"C","label":"England. Remarkably,"},{"id":"D","label":"England, remarkably"}]}'::jsonb,52,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-052","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '068b1320-0bc2-df24-f9c6-a3629d654088','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the passage contains two independent clauses, and a period correctly separates them; “Remarkably” then introduces the second sentence and is followed by a comma. Choice A is incorrect because the comma before “remarkably” creates a comma splice. Choice B is incorrect because without punctuation before “remarkably” the clauses run together. Choice D is incorrect because it creates a comma splice and leaves “remarkably” unclear about which clause it modifies."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='068b1320-0bc2-df24-f9c6-a3629d654088') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('81fc8428-8c79-fd70-aff9-949fae70ec0e','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Ada Lovelace was born in London in December 1815, and her parents separated only weeks later. Lovelace’s ______ left England when she was an infant and never saw her again.","options":[{"id":"A","label":"father the poet Lord Byron"},{"id":"B","label":"father, the poet Lord Byron,"},{"id":"C","label":"father, the poet, Lord Byron,"},{"id":"D","label":"father the poet, Lord Byron,"}]}'::jsonb,53,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-053","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '81fc8428-8c79-fd70-aff9-949fae70ec0e','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because Lovelace had only one father, so “the poet Lord Byron” is nonessential information that must be set off by a pair of commas; within that phrase, “Lord Byron” is essential to identify which poet is meant, so no comma separates “the poet” from the name. Choice A is incorrect because it treats the nonessential appositive as essential. Choice C is incorrect because the comma between “the poet” and “Lord Byron” wrongly separates the title from the name it identifies. Choice D is incorrect because it lacks a comma after “father” and wrongly places one after “the poet.”"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='81fc8428-8c79-fd70-aff9-949fae70ec0e') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('57ca778b-683a-9006-bf21-36a02f33da95','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"In the third century BCE, the Greek scholar Eratosthenes estimated Earth’s circumference using a clever ______ noon on the summer solstice, the Sun shone straight down a well in the city of Syene but cast shadows in Alexandria, and from the angle of those shadows and the distance between the cities, he calculated the planet’s size.","options":[{"id":"A","label":"observation, at"},{"id":"B","label":"observation at"},{"id":"C","label":"observation, which at"},{"id":"D","label":"observation: at"}]}'::jsonb,54,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-054","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '57ca778b-683a-9006-bf21-36a02f33da95','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because a colon can follow an independent clause (“Eratosthenes estimated Earth’s circumference using a clever observation”) to introduce an explanation of that observation, which here is itself a series of independent clauses. Choice A is incorrect because a comma alone between independent clauses creates a comma splice. Choice B is incorrect because without punctuation “at noon” seems to modify “observation,” and the clauses run together. Choice C is incorrect because “which” begins a relative clause that cannot grammatically include the independent clauses that follow."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='57ca778b-683a-9006-bf21-36a02f33da95') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('66bfd694-fde8-dcda-f2d1-2e0ce80a880e','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Among the most celebrated achievements of the Abbasid-era House of Wisdom in ______ the translation of Greek, Persian, and Indian scientific and philosophical works into Arabic, a project that preserved many texts that might otherwise have been lost.","options":[{"id":"A","label":"Baghdad was"},{"id":"B","label":"Baghdad was:"},{"id":"C","label":"Baghdad was,"},{"id":"D","label":"Baghdad—was"}]}'::jsonb,55,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"boundaries","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-bd-055","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '66bfd694-fde8-dcda-f2d1-2e0ce80a880e','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because in this inverted sentence the verb “was” is followed directly by its subject, “the translation,” and no punctuation should separate a verb from its subject. Choice B is incorrect because a colon must follow an independent clause, and the words before the colon do not form one. Choice C is incorrect because a comma should not separate the verb from its subject. Choice D is incorrect because a dash would separate the introductory phrase from the verb for no reason and does not pair with any other dash."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='66bfd694-fde8-dcda-f2d1-2e0ce80a880e') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('67aa82d8-2c43-a7f7-1231-2fe8f32ad054','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Farmers plowing a field near the village uncovered a clay jar filled with silver coins from the twelfth century. The collection of ancient coins ______ now on display at the regional museum, where visitors can examine the coins under magnifying lenses.","options":[{"id":"A","label":"is"},{"id":"B","label":"are"},{"id":"C","label":"were"},{"id":"D","label":"have been"}]}'::jsonb,56,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '67aa82d8-2c43-a7f7-1231-2fe8f32ad054','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the subject of the sentence is the singular noun “collection,” so the singular verb “is” agrees with it; “of ancient coins” is a prepositional phrase that does not change the subject. Choice B is incorrect because the plural verb “are” does not agree with the singular subject. Choice C is incorrect because “were” is plural and also shifts to the past tense, which conflicts with “now.” Choice D is incorrect because “have been” is plural."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='67aa82d8-2c43-a7f7-1231-2fe8f32ad054') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2563bccb-b3dc-4b10-3828-96e3c712a4ad','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The giant panda spends as many as 14 hours a day eating bamboo, which makes up almost all of its diet. Because bamboo provides little nutrition, the panda must eat large quantities of it to meet ______ energy needs.","options":[{"id":"A","label":"their"},{"id":"B","label":"it’s"},{"id":"C","label":"its"},{"id":"D","label":"theirs"}]}'::jsonb,57,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-002","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '2563bccb-b3dc-4b10-3828-96e3c712a4ad','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the possessive pronoun must refer to the singular noun “the panda,” and “its” is the singular possessive form. Choice A is incorrect because “their” is plural and does not agree with “the panda.” Choice B is incorrect because “it’s” is a contraction of “it is,” not a possessive. Choice D is incorrect because “theirs” is a plural pronoun that stands alone and cannot come before a noun."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='2563bccb-b3dc-4b10-3828-96e3c712a4ad') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('85a7b757-c4cb-fbe1-1936-81a71500edaf','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"In July 1969, the Apollo 11 mission ______ the first humans on the Moon. Astronauts Neil Armstrong and Buzz Aldrin spent about two and a half hours walking on the lunar surface while Michael Collins orbited overhead.","options":[{"id":"A","label":"lands"},{"id":"B","label":"landed"},{"id":"C","label":"will land"},{"id":"D","label":"has landed"}]}'::jsonb,58,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '85a7b757-c4cb-fbe1-1936-81a71500edaf','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the sentence describes a completed event at a specific past time, “In July 1969,” so the simple past “landed” is correct; it also matches the past-tense verbs in the next sentence. Choice A is incorrect because the present tense “lands” does not fit a past event. Choice C is incorrect because the future tense is illogical for an event in 1969. Choice D is incorrect because the present perfect “has landed” is not used with a specific past time."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='85a7b757-c4cb-fbe1-1936-81a71500edaf') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('16594012-b49f-a225-cf0a-ee86fee12cf5','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Giraffes are the tallest living land animals, with adult males reaching heights of more than five meters. The ______ long necks allow them to browse on leaves high in acacia trees, beyond the reach of most other plant-eating animals.","options":[{"id":"A","label":"animals"},{"id":"B","label":"animal’s"},{"id":"C","label":"animals’"},{"id":"D","label":"animals’s"}]}'::jsonb,59,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '16594012-b49f-a225-cf0a-ee86fee12cf5','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the necks belong to more than one animal, as the plural pronoun “them” shows, so the plural possessive “animals’” is needed. Choice A is incorrect because “animals” is a plural noun without possession. Choice B is incorrect because “animal’s” is singular possessive and does not agree with “them.” Choice D is incorrect because “animals’s” is not a standard possessive form; a plural noun ending in s takes only an apostrophe."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='16594012-b49f-a225-cf0a-ee86fee12cf5') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4af6969f-9e67-5012-d371-0abe156348b9','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Sodium is a soft metal that reacts violently with water, and chlorine is a poisonous gas. Sodium and chlorine ______ hazardous on their own, but when they combine chemically, they form sodium chloride, better known as ordinary table salt.","options":[{"id":"A","label":"is"},{"id":"B","label":"are"},{"id":"C","label":"was"},{"id":"D","label":"has been"}]}'::jsonb,60,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-005","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '4af6969f-9e67-5012-d371-0abe156348b9','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the compound subject “Sodium and chlorine” is plural, and the plural present-tense verb “are” agrees with it and matches the present tense of the passage. Choice A is incorrect because “is” is singular. Choice C is incorrect because “was” is singular and in the past tense. Choice D is incorrect because “has been” is singular."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='4af6969f-9e67-5012-d371-0abe156348b9') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('86968d5e-4330-edab-f2f7-11f3fe73ee07','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Lascaux Cave in southwestern France contains about 600 paintings of animals made roughly 17,000 years ago. Exploring the woods near the town of Montignac in September 1940, ______","options":[{"id":"A","label":"the entrance to the cave was discovered by four teenagers."},{"id":"B","label":"the cave’s entrance was found by four teenagers."},{"id":"C","label":"the discovery of the cave’s entrance was made by four teenagers."},{"id":"D","label":"four teenagers discovered the entrance to the cave."}]}'::jsonb,61,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '86968d5e-4330-edab-f2f7-11f3fe73ee07','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the introductory phrase “Exploring the woods near the town of Montignac in September 1940” must be followed by the people who did the exploring, and “four teenagers” is the subject of the main clause. Choice A is incorrect because it places “the entrance” right after the phrase, illogically suggesting that the entrance was exploring the woods. Choice B is incorrect because it suggests that the cave’s entrance was exploring. Choice C is incorrect because it suggests that “the discovery” was exploring the woods."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='86968d5e-4330-edab-f2f7-11f3fe73ee07') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3ddcac5d-86f9-0557-0466-047462eba4dc','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Comets are small bodies of ice and dust that orbit the Sun. The Rosetta spacecraft, launched by the European Space Agency in 2004, ______ in orbit around Comet 67P/Churyumov–Gerasimenko in 2014, after a journey of more than ten years.","options":[{"id":"A","label":"arriving"},{"id":"B","label":"to arrive"},{"id":"C","label":"arrived"},{"id":"D","label":"having arrived"}]}'::jsonb,62,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '3ddcac5d-86f9-0557-0466-047462eba4dc','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the sentence needs a main verb for its subject, “The Rosetta spacecraft,” and the finite past-tense verb “arrived” supplies one. Choice A is incorrect because the participle “arriving” cannot serve as a main verb, leaving a fragment. Choice B is incorrect because the infinitive “to arrive” cannot serve as a main verb. Choice D is incorrect because “having arrived” is also a nonfinite form that leaves the sentence without a main verb."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='3ddcac5d-86f9-0557-0466-047462eba4dc') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8997977a-a829-372f-63fa-aa996b80f4e2','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"In most orchestras, the principal oboist plays a single note, usually an A, before a performance begins. The other musicians then tune ______ instruments to that note so that the whole ensemble plays in tune.","options":[{"id":"A","label":"its"},{"id":"B","label":"there"},{"id":"C","label":"they’re"},{"id":"D","label":"their"}]}'::jsonb,63,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '8997977a-a829-372f-63fa-aa996b80f4e2','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the possessive pronoun refers to the plural noun “musicians,” and “their” is the plural possessive form. Choice A is incorrect because “its” is singular. Choice B is incorrect because “there” refers to a place and is not possessive. Choice C is incorrect because “they’re” is a contraction of “they are,” not a possessive."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='8997977a-a829-372f-63fa-aa996b80f4e2') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6c3bfedf-1115-8dda-5cbc-c45b883e1950','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The Great Pyramid of Giza is the only one of the Seven Wonders of the Ancient World that is still largely standing. Each of the seven wonders ______ described by ancient Greek writers, whose lists of remarkable monuments date back more than two thousand years.","options":[{"id":"A","label":"were"},{"id":"B","label":"was"},{"id":"C","label":"are"},{"id":"D","label":"have been"}]}'::jsonb,64,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-009","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '6c3bfedf-1115-8dda-5cbc-c45b883e1950','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the subject “Each” is singular, so it requires the singular verb “was”; the past tense fits writers who lived long ago. Choice A is incorrect because “were” is plural; the plural noun “wonders” is part of a prepositional phrase, not the subject. Choice C is incorrect because “are” is plural. Choice D is incorrect because “have been” is plural."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='6c3bfedf-1115-8dda-5cbc-c45b883e1950') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('44870329-c5f9-c6ea-9a40-2312df0726d7','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The Library of Alexandria in Egypt became one of the most famous centers of learning in the ancient world. When the library was founded in the third century BCE, its scholars ______ to collect copies of every book they could find.","options":[{"id":"A","label":"sought"},{"id":"B","label":"seek"},{"id":"C","label":"will seek"},{"id":"D","label":"are seeking"}]}'::jsonb,65,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '44870329-c5f9-c6ea-9a40-2312df0726d7','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the sentence describes events in the third century BCE, and the past-tense verb “sought” matches the past-tense verbs “was founded” and “could find.” Choice B is incorrect because the present tense “seek” does not fit a past event. Choice C is incorrect because the future tense is illogical for events in the distant past. Choice D is incorrect because the present progressive “are seeking” does not fit a past event."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='44870329-c5f9-c6ea-9a40-2312df0726d7') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('58379b7b-8f28-7df9-a303-c5ffe80775b2','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Unlike most birds, a hummingbird can hover in midair, and it can even fly backward. The bird accomplishes this by rotating ______ wings in a figure-eight pattern, producing lift on both the forward stroke and the backward stroke.","options":[{"id":"A","label":"its"},{"id":"B","label":"it’s"},{"id":"C","label":"their"},{"id":"D","label":"its’"}]}'::jsonb,66,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '58379b7b-8f28-7df9-a303-c5ffe80775b2','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the possessive pronoun refers to the singular noun “The bird,” and “its” is the correct singular possessive form. Choice B is incorrect because “it’s” means “it is.” Choice C is incorrect because “their” is plural and does not agree with “The bird.” Choice D is incorrect because “its’” is not a word in Standard English."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='58379b7b-8f28-7df9-a303-c5ffe80775b2') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1cad8071-bb0e-6310-a68e-c7d4e3bc0beb','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Muscles make movement possible, from blinking to running. In the human body, there ______ more than 600 skeletal muscles, which together account for roughly 40 percent of an adult’s body weight.","options":[{"id":"A","label":"is"},{"id":"B","label":"has been"},{"id":"C","label":"was"},{"id":"D","label":"are"}]}'::jsonb,67,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '1cad8071-bb0e-6310-a68e-c7d4e3bc0beb','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because in a sentence beginning with “there,” the verb agrees with the noun that follows it; the subject here is the plural “more than 600 skeletal muscles,” so the plural “are” is correct, and the present tense matches “account.” Choice A is incorrect because “is” is singular. Choice B is incorrect because “has been” is singular. Choice C is incorrect because “was” is singular and in the past tense."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='1cad8071-bb0e-6310-a68e-c7d4e3bc0beb') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e0fd4272-399d-9967-00e9-30292c090f3e','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Marie Curie is best known for her pioneering research on radioactivity, work that earned her Nobel Prizes in both physics and chemistry. Born in Warsaw in 1867, ______","options":[{"id":"A","label":"Paris was where Curie later moved to study physics and mathematics."},{"id":"B","label":"Curie later moved to Paris to study physics and mathematics at the Sorbonne."},{"id":"C","label":"the Sorbonne in Paris was where Curie later studied physics and mathematics."},{"id":"D","label":"physics and mathematics were the subjects Curie later studied in Paris."}]}'::jsonb,68,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-013","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'e0fd4272-399d-9967-00e9-30292c090f3e','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the person who was born in Warsaw in 1867 is Curie, and placing “Curie” immediately after the introductory phrase makes clear who is being described. Choice A is incorrect because it suggests that Paris was born in Warsaw. Choice C is incorrect because it suggests that the Sorbonne was born in Warsaw. Choice D is incorrect because it suggests that physics and mathematics were born in Warsaw."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='e0fd4272-399d-9967-00e9-30292c090f3e') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ae863693-67dd-9ada-4bf4-bdd5342127cd','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Astronauts have lived aboard the International Space Station continuously since November 2000. Today, the station ______ Earth about every 90 minutes at an altitude of roughly 400 kilometers, so its crew sees about 16 sunrises a day.","options":[{"id":"A","label":"orbited"},{"id":"B","label":"had orbited"},{"id":"C","label":"will have orbited"},{"id":"D","label":"orbits"}]}'::jsonb,69,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-014","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'ae863693-67dd-9ada-4bf4-bdd5342127cd','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because “Today” signals a current, repeated action, which calls for the present tense “orbits”; it also matches the present-tense verb “sees.” Choice A is incorrect because the past tense “orbited” conflicts with “Today.” Choice B is incorrect because the past perfect refers to an action completed before another past action. Choice C is incorrect because the future perfect refers to an action that will be complete at a future time."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='ae863693-67dd-9ada-4bf4-bdd5342127cd') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('84174713-302b-be03-4541-e5b34b00b4d4','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"No two zebras have exactly the same pattern of stripes. Researchers can therefore identify individual animals in a herd by photographing each ______ stripes and comparing the images with a database of earlier photographs.","options":[{"id":"A","label":"zebras’"},{"id":"B","label":"zebras"},{"id":"C","label":"zebra’s"},{"id":"D","label":"zebras’s"}]}'::jsonb,70,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-015","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '84174713-302b-be03-4541-e5b34b00b4d4','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because “each” refers to one zebra at a time, so the singular possessive “zebra’s” correctly shows that the stripes belong to a single animal. Choice A is incorrect because “zebras’” is plural possessive, which does not fit “each.” Choice B is incorrect because “zebras” is a plural noun without possession. Choice D is incorrect because “zebras’s” is not a standard possessive form."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='84174713-302b-be03-4541-e5b34b00b4d4') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('aaa049dc-c658-aa71-7685-ac22386c5f13','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Excavating an archaeological site is slow, careful work. The tool that archaeologists use most often to remove soil from around delicate finds ______ not a shovel but a small pointed trowel.","options":[{"id":"A","label":"are"},{"id":"B","label":"were"},{"id":"C","label":"have been"},{"id":"D","label":"is"}]}'::jsonb,71,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-016","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'aaa049dc-c658-aa71-7685-ac22386c5f13','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the subject is the singular noun “The tool,” so the singular verb “is” agrees with it; the plural nouns “archaeologists” and “finds” are within a clause and a phrase that modify the subject. The present tense also matches “use.” Choice A is incorrect because “are” is plural. Choice B is incorrect because “were” is plural. Choice C is incorrect because “have been” is plural."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='aaa049dc-c658-aa71-7685-ac22386c5f13') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a1a7d12a-ad66-60c8-4a78-ef9248c9beb3','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The city of Venice is built on more than 100 small islands in a shallow lagoon, and high tides regularly flood its streets. To protect ______ historic buildings, the city has installed a system of movable barriers at the lagoon’s inlets.","options":[{"id":"A","label":"their"},{"id":"B","label":"its"},{"id":"C","label":"it’s"},{"id":"D","label":"there"}]}'::jsonb,72,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-017","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'a1a7d12a-ad66-60c8-4a78-ef9248c9beb3','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the pronoun refers to the singular noun “the city,” and “its” is the singular possessive form. Choice A is incorrect because “their” is plural and does not agree with “the city.” Choice C is incorrect because “it’s” is a contraction of “it is.” Choice D is incorrect because “there” refers to a place and is not possessive."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='a1a7d12a-ad66-60c8-4a78-ef9248c9beb3') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('970c73e0-d640-da76-54c0-3b6ffddd74dd','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Archaeological evidence shows that people have lived on the islands of Haida Gwaii, off the coast of present-day British Columbia, for a very long time. By the time the first European ships reached the area in the 1770s, the Haida people ______ there for thousands of years.","options":[{"id":"A","label":"live"},{"id":"B","label":"will live"},{"id":"C","label":"had lived"},{"id":"D","label":"are living"}]}'::jsonb,73,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-018","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '970c73e0-d640-da76-54c0-3b6ffddd74dd','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because “By the time ... reached” sets a point in the past, and the past perfect “had lived” describes an action that continued up to that point. Choice A is incorrect because the present tense “live” does not fit an action completed before a past event. Choice B is incorrect because the future tense is illogical here. Choice D is incorrect because the present progressive describes an action happening now, not one that had continued until the 1770s."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='970c73e0-d640-da76-54c0-3b6ffddd74dd') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('979b5323-68d9-35e3-f59e-0692836a1ef5','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Many of Claude Monet’s most famous works show the garden he created at his home in Giverny, France. The French artist ______ about 250 paintings of water lilies, many of them depicting the pond in that garden.","options":[{"id":"A","label":"painted"},{"id":"B","label":"painting"},{"id":"C","label":"to paint"},{"id":"D","label":"having painted"}]}'::jsonb,74,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-019","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '979b5323-68d9-35e3-f59e-0692836a1ef5','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the sentence needs a main verb for the subject “The French artist,” and the finite past-tense verb “painted” provides one. Choice B is incorrect because the participle “painting” cannot serve as the main verb, leaving a fragment. Choice C is incorrect because the infinitive “to paint” cannot serve as the main verb. Choice D is incorrect because “having painted” is a nonfinite form that also leaves the sentence without a main verb."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='979b5323-68d9-35e3-f59e-0692836a1ef5') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2ea96d4d-f7dd-21f9-d353-ef8c419c50b0','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Australia’s Great Barrier Reef supports an extraordinary range of marine life. The reef, along with the many species of fish, turtles, and seabirds that depend on it, ______ protected as part of a marine park that covers more than 340,000 square kilometers.","options":[{"id":"A","label":"are"},{"id":"B","label":"is"},{"id":"C","label":"were"},{"id":"D","label":"have been"}]}'::jsonb,75,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-020","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '2ea96d4d-f7dd-21f9-d353-ef8c419c50b0','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the subject is the singular noun “The reef”; a phrase beginning with “along with” does not make a subject plural, so the singular verb “is” is correct. Choice A is incorrect because “are” is plural and agrees with the nouns in the interrupting phrase rather than with the subject. Choice C is incorrect because “were” is plural and shifts to the past tense. Choice D is incorrect because “have been” is plural."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='2ea96d4d-f7dd-21f9-d353-ef8c419c50b0') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8854c0ba-bc14-4012-496d-0d622a47f1db','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Ratites are a group of large birds that includes the ostrich of Africa and the emu of Australia. Neither the ostrich nor the emu ______ able to fly, but both birds can run at speeds of more than 45 kilometers per hour.","options":[{"id":"A","label":"are"},{"id":"B","label":"were"},{"id":"C","label":"is"},{"id":"D","label":"have been"}]}'::jsonb,76,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-021","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '8854c0ba-bc14-4012-496d-0d622a47f1db','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because when two singular subjects are joined by “neither ... nor,” the verb agrees with the nearer subject, “the emu,” which is singular, so “is” is correct; the present tense matches “can run.” Choice A is incorrect because “are” is plural. Choice B is incorrect because “were” is plural and in the past tense. Choice D is incorrect because “have been” is plural."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='8854c0ba-bc14-4012-496d-0d622a47f1db') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ff0dd916-5c44-5460-9268-18feaa911343','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Honeybee colonies keep the temperature inside the hive within a narrow range so that developing young bees can survive. When the hive becomes too hot, worker bees stand near the entrance and fan ______ wings to draw cooler air inside.","options":[{"id":"A","label":"their"},{"id":"B","label":"its"},{"id":"C","label":"his or her"},{"id":"D","label":"it’s"}]}'::jsonb,77,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-022","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'ff0dd916-5c44-5460-9268-18feaa911343','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the pronoun refers to the plural noun “worker bees,” and “their” is the plural possessive form. Choice B is incorrect because “its” is singular; although “the hive” appears nearby, the hive does not have wings. Choice C is incorrect because “his or her” is singular. Choice D is incorrect because “it’s” is a contraction of “it is.”"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='ff0dd916-5c44-5460-9268-18feaa911343') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e5cd6ee6-3d49-2a4a-f42e-cce5c9dc61ff','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The first planet orbiting a Sun-like star outside our solar system was confirmed in 1995. Since then, astronomers ______ more than 5,000 exoplanets, using telescopes on the ground and in space.","options":[{"id":"A","label":"confirm"},{"id":"B","label":"had confirmed"},{"id":"C","label":"will confirm"},{"id":"D","label":"have confirmed"}]}'::jsonb,78,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-023","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'e5cd6ee6-3d49-2a4a-f42e-cce5c9dc61ff','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because “Since then” describes a period that began in the past and continues to the present, which calls for the present perfect “have confirmed.” Choice A is incorrect because the simple present “confirm” does not express an action continuing from a past point to now. Choice B is incorrect because the past perfect would require a later past reference point. Choice C is incorrect because the future tense is illogical with “Since then.”"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='e5cd6ee6-3d49-2a4a-f42e-cce5c9dc61ff') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ad5fc99b-0a06-d9dc-51bd-1a72ae15f084','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Pottery made from clay dug at one site has a slightly different chemical makeup from pottery made with clay from another. Studying the chemical composition of ancient pottery ______ archaeologists to trace the trade routes along which the vessels traveled.","options":[{"id":"A","label":"allow"},{"id":"B","label":"allows"},{"id":"C","label":"have allowed"},{"id":"D","label":"are allowing"}]}'::jsonb,79,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-024","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'ad5fc99b-0a06-d9dc-51bd-1a72ae15f084','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the subject is the gerund phrase “Studying the chemical composition of ancient pottery,” which is singular, so the singular verb “allows” agrees with it. Choice A is incorrect because “allow” is a plural verb, which does not agree with the singular gerund phrase that serves as the subject. Choice C is incorrect because “have allowed” is plural. Choice D is incorrect because “are allowing” is plural."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='ad5fc99b-0a06-d9dc-51bd-1a72ae15f084') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5cba5082-a76c-e3af-4791-142f84d3a509','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The fossil remains of early human relatives are rarely found intact, which makes nearly complete skeletons especially valuable to researchers. Discovered in 1974 in the Afar region of Ethiopia, ______","options":[{"id":"A","label":"researchers named the partial skeleton Lucy after a popular song."},{"id":"B","label":"scientists identified the species of the partial skeleton called Lucy as Australopithecus afarensis."},{"id":"C","label":"the partial skeleton known as Lucy belongs to the species Australopithecus afarensis."},{"id":"D","label":"Australopithecus afarensis is the species to which the partial skeleton known as Lucy belongs."}]}'::jsonb,80,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-025","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '5cba5082-a76c-e3af-4791-142f84d3a509','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the thing that was discovered in 1974 is the skeleton, and “the partial skeleton known as Lucy” comes immediately after the introductory phrase. Choice A is incorrect because it suggests that the researchers were discovered in Ethiopia. Choice B is incorrect because it suggests that the scientists were discovered. Choice D is incorrect because it suggests that the species as a whole, rather than the skeleton, was discovered in 1974."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='5cba5082-a76c-e3af-4791-142f84d3a509') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f66fb68c-8307-67f2-a561-a1c727126b0a','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"In 1804, Meriwether Lewis and William Clark set out to explore the lands west of the Mississippi River. The two ______ journals describe hundreds of plants and animals that were new to American scientists at the time.","options":[{"id":"A","label":"explorer’s"},{"id":"B","label":"explorers"},{"id":"C","label":"explorers’s"},{"id":"D","label":"explorers’"}]}'::jsonb,81,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-026","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'f66fb68c-8307-67f2-a561-a1c727126b0a','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the journals belong to two explorers, so the plural possessive “explorers’” is needed. Choice A is incorrect because “explorer’s” is singular possessive, which conflicts with “two.” Choice B is incorrect because “explorers” is plural but not possessive. Choice C is incorrect because “explorers’s” is not a standard possessive form."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='f66fb68c-8307-67f2-a561-a1c727126b0a') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0df95e73-a6a6-66cd-9700-7cdb98f42e4c','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Astronomers spent decades tracking the orbits of stars near the center of our galaxy. At the center of the Milky Way ______ a supermassive black hole called Sagittarius A*, which has a mass about four million times that of the Sun.","options":[{"id":"A","label":"lies"},{"id":"B","label":"lie"},{"id":"C","label":"are lying"},{"id":"D","label":"have lain"}]}'::jsonb,82,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-027","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '0df95e73-a6a6-66cd-9700-7cdb98f42e4c','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because in this inverted sentence the subject, “a supermassive black hole,” comes after the verb and is singular, so the singular “lies” is correct. Choice B is incorrect because “lie” is plural. Choice C is incorrect because “are lying” is plural. Choice D is incorrect because “have lain” is plural."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='0df95e73-a6a6-66cd-9700-7cdb98f42e4c') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9264e8c4-a4b0-7c49-c055-08169813b820','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The tomb of the young pharaoh Tutankhamun is famous for the treasures found inside it. When the archaeologist Howard Carter entered the tomb in 1922, he found evidence that robbers ______ it in ancient times but had left most of its contents behind.","options":[{"id":"A","label":"enter"},{"id":"B","label":"will enter"},{"id":"C","label":"had entered"},{"id":"D","label":"are entering"}]}'::jsonb,83,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-028","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '9264e8c4-a4b0-7c49-c055-08169813b820','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the robbers entered the tomb before Carter did in 1922, and the past perfect “had entered” shows an action completed before another past action; it also parallels “had left.” Choice A is incorrect because the present tense does not fit a past event. Choice B is incorrect because the future tense is illogical. Choice D is incorrect because the present progressive does not fit an action in ancient times."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='9264e8c4-a4b0-7c49-c055-08169813b820') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3e616b8b-cabd-00c0-5621-c1db47eab299','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The Bauhaus, which was founded in Weimar, Germany, in 1919 and later moved to Dessau and then Berlin, required ______ students to complete a preliminary course in materials, color, and form before specializing.","options":[{"id":"A","label":"their"},{"id":"B","label":"it’s"},{"id":"C","label":"there"},{"id":"D","label":"its"}]}'::jsonb,84,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-029","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '3e616b8b-cabd-00c0-5621-c1db47eab299','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the pronoun refers to the singular noun “The Bauhaus,” a school, and “its” is the singular possessive form. Choice A is incorrect because “their” is plural and may seem to agree with the cities named nearby, but the school is the antecedent. Choice B is incorrect because “it’s” means “it is.” Choice C is incorrect because “there” refers to a place and is not possessive."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='3e616b8b-cabd-00c0-5621-c1db47eab299') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ba363031-4f5c-a1f9-7d03-6ab9c9686606','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Ice cores drilled from the Antarctic ice sheet, some of which contain air bubbles trapped more than 800,000 years ago, ______ scientists with a record of how the composition of Earth’s atmosphere has changed over time.","options":[{"id":"A","label":"providing"},{"id":"B","label":"provide"},{"id":"C","label":"to provide"},{"id":"D","label":"having provided"}]}'::jsonb,85,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-030","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'ba363031-4f5c-a1f9-7d03-6ab9c9686606','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the sentence needs a main verb for its plural subject, “Ice cores,” and “provide” is a finite plural verb. Choice A is incorrect because the participle “providing” cannot serve as a main verb, leaving a fragment. Choice C is incorrect because the infinitive “to provide” cannot serve as a main verb. Choice D is incorrect because “having provided” is also nonfinite and leaves the sentence without a main verb."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='ba363031-4f5c-a1f9-7d03-6ab9c9686606') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b3752adc-00ba-a3d3-8c7f-353cc3f24b3d','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Linguists disagree about exactly how to distinguish a language from a dialect. Even so, the number of languages spoken worldwide ______ commonly estimated at about 7,000, and many of those languages have only a few thousand speakers.","options":[{"id":"A","label":"are"},{"id":"B","label":"were"},{"id":"C","label":"is"},{"id":"D","label":"have been"}]}'::jsonb,86,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-031","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'b3752adc-00ba-a3d3-8c7f-353cc3f24b3d','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the subject is “the number,” which is singular, so the singular verb “is” is correct; “of languages spoken worldwide” does not change the subject, and the present tense matches “have.” Choice A is incorrect because “are” is plural. Choice B is incorrect because “were” is plural and in the past tense. Choice D is incorrect because “have been” is plural."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='b3752adc-00ba-a3d3-8c7f-353cc3f24b3d') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b11204ac-0dae-320d-425a-27ea9cb8820c','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Kimchi, a fermented vegetable dish, is served with almost every meal in Korea. To make a traditional version, cooks salt napa cabbage, rinse it, and ______ it with a paste of chili, garlic, and ginger before leaving it to ferment.","options":[{"id":"A","label":"coat"},{"id":"B","label":"coating"},{"id":"C","label":"to coat"},{"id":"D","label":"coated"}]}'::jsonb,87,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-032","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'b11204ac-0dae-320d-425a-27ea9cb8820c','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because items in a series should share the same grammatical form; “coat” is a present-tense verb like “salt” and “rinse.” Choice B is incorrect because the participle “coating” breaks the parallel structure. Choice C is incorrect because the infinitive “to coat” breaks the parallel structure. Choice D is incorrect because the past-tense “coated” does not match the present-tense verbs in the series."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='b11204ac-0dae-320d-425a-27ea9cb8820c') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8e0d3372-3a20-d540-f6fa-ca2a3031b306','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"In the early nineteenth century, few women were able to join Britain’s formal scientific societies or study at its universities. A largely self-taught fossil collector, ______","options":[{"id":"A","label":"the first complete plesiosaur skeleton was found by Mary Anning in 1823 on the coast near Lyme Regis, England."},{"id":"B","label":"Mary Anning found the first complete plesiosaur skeleton in 1823 on the coast near Lyme Regis, England."},{"id":"C","label":"the coast near Lyme Regis, England, was where Mary Anning found the first complete plesiosaur skeleton in 1823."},{"id":"D","label":"Mary Anning’s discovery of the first complete plesiosaur skeleton came in 1823 on the coast near Lyme Regis, England."}]}'::jsonb,88,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-033","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '8e0d3372-3a20-d540-f6fa-ca2a3031b306','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the fossil collector described by the introductory phrase is Mary Anning, and her name immediately follows the phrase. Choice A is incorrect because it suggests that the skeleton was a self-taught fossil collector. Choice C is incorrect because it suggests that the coast was the fossil collector. Choice D is incorrect because the subject is “discovery,” not Anning; the possessive “Mary Anning’s” is not the noun the phrase can modify."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='8e0d3372-3a20-d540-f6fa-ca2a3031b306') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a2388caf-d602-39f4-5ee5-74522d0ca2c5','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Chinua Achebe’s 1958 novel Things Fall Apart is set in a fictional Igbo village during the late nineteenth century. In the novel, the protagonist, Okonkwo, ______ to become a respected leader of Umuofia, in part because he fears being seen as weak like his father.","options":[{"id":"A","label":"strove"},{"id":"B","label":"had striven"},{"id":"C","label":"will strive"},{"id":"D","label":"strives"}]}'::jsonb,89,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-034","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'a2388caf-d602-39f4-5ee5-74522d0ca2c5','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the sentence discusses the novel in the present tense, as “he fears” shows, and the present-tense “strives” keeps the verbs consistent, following the convention for describing the events of a literary work. Choice A is incorrect because the past-tense “strove” conflicts with the present-tense “fears.” Choice B is incorrect because the past perfect also conflicts with “fears.” Choice C is incorrect because the future tense is illogical for an action already under way."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='a2388caf-d602-39f4-5ee5-74522d0ca2c5') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d0215727-9270-aa39-f6f8-18fcfc19fbb0','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Coral bleaching occurs when stressed corals expel the algae that live in their tissues. A team of marine biologists studying reefs off the coast of Belize ______ that some coral colonies recover from bleaching much faster than others growing nearby.","options":[{"id":"A","label":"has found"},{"id":"B","label":"have found"},{"id":"C","label":"are finding"},{"id":"D","label":"find"}]}'::jsonb,90,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-035","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'd0215727-9270-aa39-f6f8-18fcfc19fbb0','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the subject is the singular noun “A team,” so the singular verb “has found” agrees with it. Choice B is incorrect because “have found” is plural and seems to agree with “biologists” or “reefs,” which are not the subject. Choice C is incorrect because “are finding” is plural. Choice D is incorrect because “find” is plural."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='d0215727-9270-aa39-f6f8-18fcfc19fbb0') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9c2635ce-1a3d-b1d1-8e90-c18f6939c10a','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Most frogs begin life as tadpoles that hatch from eggs laid in water. Unlike most frogs, which lay ______ eggs in ponds or streams, the coquí frog of Puerto Rico lays its eggs on land, and the young hatch as tiny, fully formed frogs.","options":[{"id":"A","label":"its"},{"id":"B","label":"it’s"},{"id":"C","label":"their"},{"id":"D","label":"they’re"}]}'::jsonb,91,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-036","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '9c2635ce-1a3d-b1d1-8e90-c18f6939c10a','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the pronoun refers to the plural noun “most frogs,” and “their” is the plural possessive form. Choice A is incorrect because “its” is singular; it agrees with “the coquí frog,” but that noun is not the antecedent here. Choice B is incorrect because “it’s” means “it is.” Choice D is incorrect because “they’re” means “they are.”"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='9c2635ce-1a3d-b1d1-8e90-c18f6939c10a') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5389fa25-df51-5efa-ca03-663c223ae44b','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Signed in 1959, the Antarctic Treaty set aside the continent for peaceful scientific research. The treaty also froze the seven claimant ______ territorial claims, meaning that no new claims could be made while the treaty remained in force.","options":[{"id":"A","label":"nation’s"},{"id":"B","label":"nations’"},{"id":"C","label":"nations"},{"id":"D","label":"nations’s"}]}'::jsonb,92,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-037","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '5389fa25-df51-5efa-ca03-663c223ae44b','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the claims belong to seven nations, so the plural possessive “nations’” is required. Choice A is incorrect because “nation’s” is singular possessive, which conflicts with “seven.” Choice C is incorrect because “nations” is plural but not possessive. Choice D is incorrect because “nations’s” is not a standard possessive form."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='5389fa25-df51-5efa-ca03-663c223ae44b') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6b8f41b3-f8ae-2d49-7054-e20360b7c6c6','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Jacob Lawrence’s Migration Series, a sequence of 60 panels depicting the movement of African Americans from the rural South to cities in the North, ______ divided between two museums: the Phillips Collection in Washington, D.C., and the Museum of Modern Art in New York.","options":[{"id":"A","label":"is"},{"id":"B","label":"are"},{"id":"C","label":"were"},{"id":"D","label":"have been"}]}'::jsonb,93,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-038","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '6b8f41b3-f8ae-2d49-7054-e20360b7c6c6','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the subject is “Migration Series,” the title of a single work, which is singular, so “is” agrees with it. Choice B is incorrect because “are” is plural and seems to agree with “panels” or “African Americans,” which are in the appositive, not the subject. Choice C is incorrect because “were” is plural and past tense. Choice D is incorrect because “have been” is plural."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='6b8f41b3-f8ae-2d49-7054-e20360b7c6c6') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('eabd6bfe-75b2-5628-a2f2-8bfb48a5a56c','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Reindeer living in the far north face long, dark winters with little food. The Svalbard reindeer, a subspecies that lives only on a remote group of Norwegian islands, ______ shorter legs and a smaller head than most other reindeer, features that help it conserve heat.","options":[{"id":"A","label":"having"},{"id":"B","label":"to have"},{"id":"C","label":"which has"},{"id":"D","label":"has"}]}'::jsonb,94,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-039","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'eabd6bfe-75b2-5628-a2f2-8bfb48a5a56c','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the sentence needs a main verb for the subject “The Svalbard reindeer,” and the finite verb “has” provides one. Choice A is incorrect because the participle “having” cannot serve as a main verb. Choice B is incorrect because the infinitive “to have” cannot serve as a main verb. Choice C is incorrect because “which has” turns the rest of the sentence into a relative clause, leaving the subject without a main verb."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='eabd6bfe-75b2-5628-a2f2-8bfb48a5a56c') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('17a7f844-aee7-ed9c-a220-277ec9c3fa0d','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Neptune, the most distant major planet from the Sun, has been visited by only one spacecraft. The Voyager 2 probe ______ past Neptune in 1989, sending back the first close-up images of the planet’s blue clouds and its largest moon, Triton.","options":[{"id":"A","label":"has flown"},{"id":"B","label":"flies"},{"id":"C","label":"flew"},{"id":"D","label":"will fly"}]}'::jsonb,95,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-040","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '17a7f844-aee7-ed9c-a220-277ec9c3fa0d','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the flyby happened at a specific past time, “in 1989,” so the simple past “flew” is correct. Choice A is incorrect because the present perfect “has flown” is not used with a specific past time such as “in 1989.” Choice B is incorrect because the present tense does not fit a past event. Choice D is incorrect because the future tense is illogical for an event in 1989."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='17a7f844-aee7-ed9c-a220-277ec9c3fa0d') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4033a3d6-9a19-b13f-4f5a-f9754d9eac3b','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"In 1610, the Italian astronomer Galileo Galilei published a short book describing what he had seen through his telescope. Using a telescope he had built himself, ______","options":[{"id":"A","label":"four moons were observed orbiting Jupiter by Galileo."},{"id":"B","label":"Jupiter’s four largest moons were discovered by Galileo."},{"id":"C","label":"Galileo’s observations revealed four moons orbiting Jupiter."},{"id":"D","label":"Galileo observed four moons orbiting Jupiter."}]}'::jsonb,96,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-041","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '4033a3d6-9a19-b13f-4f5a-f9754d9eac3b','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the person who used the telescope is Galileo, and his name immediately follows the introductory phrase. Choice A is incorrect because it suggests that the moons used a telescope. Choice B is incorrect because it also suggests that the moons used a telescope. Choice C is incorrect because the subject is “observations,” not Galileo; the possessive “Galileo’s” cannot be what the phrase modifies."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='4033a3d6-9a19-b13f-4f5a-f9754d9eac3b') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ee30fdff-9a40-806b-127d-c1073c26a901','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Excavations at Tell Mardikh, in present-day Syria, revealed the ancient city of Ebla in the 1960s and 1970s. The discovery of thousands of clay tablets and fragments in the city’s royal archive, many of them written in a previously unknown Semitic language, ______ historians a detailed view of Ebla’s trade and administration more than 4,000 years ago.","options":[{"id":"A","label":"has given"},{"id":"B","label":"have given"},{"id":"C","label":"giving"},{"id":"D","label":"were giving"}]}'::jsonb,97,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-042","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'ee30fdff-9a40-806b-127d-c1073c26a901','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the subject of the sentence is the singular noun “discovery,” so the singular verb “has given” agrees with it; the plural nouns “tablets,” “fragments,” and “them” appear in modifying phrases. Choice B is incorrect because “have given” is plural. Choice C is incorrect because the participle “giving” cannot serve as the main verb, leaving a fragment. Choice D is incorrect because “were giving” is plural."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='ee30fdff-9a40-806b-127d-c1073c26a901') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('64ff3c3c-179c-ddd2-5fdb-cea891e49250','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Every year, the larvae of the European eel drift on ocean currents from the Atlantic to rivers across Europe, where they grow for many years before returning to sea. Researchers studying the European eel, a species that migrates thousands of kilometers to spawn in the Sargasso Sea, have long struggled to observe ______ spawning directly, since no one has seen the species reproducing in the wild.","options":[{"id":"A","label":"their"},{"id":"B","label":"it’s"},{"id":"C","label":"its"},{"id":"D","label":"they’re"}]}'::jsonb,98,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-043","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '64ff3c3c-179c-ddd2-5fdb-cea891e49250','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the pronoun refers to “the European eel,” a singular noun naming the species, so the singular possessive “its” is correct. Choice A is incorrect because “their” is plural, and the only plural noun it could refer to is “Researchers,” which would illogically suggest that the researchers spawn. Choice B is incorrect because “it’s” means “it is.” Choice D is incorrect because “they’re” means “they are.”"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='64ff3c3c-179c-ddd2-5fdb-cea891e49250') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('93077ce8-883a-6712-724c-cc8b373848ae','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Dmitri Mendeleev was not the only chemist of his era to look for patterns among the elements, but his table proved the most influential. By the time Mendeleev published his periodic table in 1869, chemists ______ about 63 elements, which he arranged by atomic weight while leaving gaps for elements he predicted would later be found.","options":[{"id":"A","label":"have identified"},{"id":"B","label":"had identified"},{"id":"C","label":"identify"},{"id":"D","label":"identified"}]}'::jsonb,99,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-044","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '93077ce8-883a-6712-724c-cc8b373848ae','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because “By the time Mendeleev published ... in 1869” establishes a past reference point, and the past perfect “had identified” describes identifications completed before that point. Choice A is incorrect because the present perfect connects the past to the present, not to an earlier past moment. Choice C is incorrect because the present tense does not fit events in 1869. Choice D is incorrect because the simple past “identified” does not show that the identifications were already complete at the 1869 reference point that “By the time” establishes; that relationship requires the past perfect."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='93077ce8-883a-6712-724c-cc8b373848ae') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1bc7a805-871d-4d22-444d-0ef6b7f6ecdc','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Miguel de Cervantes’s novel about an aging gentleman who imagines himself a knight has been translated into more than 140 languages. First published in two parts, in 1605 and 1615, ______","options":[{"id":"A","label":"Cervantes wrote Don Quixote, a novel that many critics consider the first modern novel."},{"id":"B","label":"many critics have described Cervantes’s Don Quixote as the first modern novel."},{"id":"C","label":"critics’ descriptions of Cervantes’s Don Quixote often call it the first modern novel."},{"id":"D","label":"Don Quixote is often described by critics as the first modern novel."}]}'::jsonb,100,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-045","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '1bc7a805-871d-4d22-444d-0ef6b7f6ecdc','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because what was “first published in two parts, in 1605 and 1615” is the novel, and “Don Quixote” is the subject that immediately follows the introductory phrase. Choice A is incorrect because it suggests that Cervantes himself was published in two parts. Choice B is incorrect because it suggests that the critics were published in 1605 and 1615; “Don Quixote” appears only as an object. Choice C is incorrect because the subject is “descriptions,” not the novel."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='1bc7a805-871d-4d22-444d-0ef6b7f6ecdc') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('faedeab4-9ae9-9249-2515-45e6bdd824e4','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The Alhambra, a palace and fortress complex in Granada, Spain, was largely built by rulers of the Nasrid dynasty in the thirteenth and fourteenth centuries. The intricate geometric tilework of the Alhambra’s palaces and the carved stucco inscriptions that cover many of its walls ______ visitors a vivid sense of the artistry of Nasrid-era Granada.","options":[{"id":"A","label":"give"},{"id":"B","label":"gives"},{"id":"C","label":"has given"},{"id":"D","label":"is giving"}]}'::jsonb,101,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-046","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'faedeab4-9ae9-9249-2515-45e6bdd824e4','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the subject is compound—“The intricate geometric tilework ... and the carved stucco inscriptions”—so it requires the plural verb “give.” Choice B is incorrect because “gives” is singular; it may seem to agree with “tilework” or “Granada,” but the two parts of the subject joined by “and” make it plural. Choice C is incorrect because “has given” is singular. Choice D is incorrect because “is giving” is singular."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='faedeab4-9ae9-9249-2515-45e6bdd824e4') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a2ee513d-5193-861f-7af4-1520eb0c51f1','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The Nazca Lines, enormous designs etched into the desert of southern Peru between about 500 BCE and 500 CE, some of which depict animals such as a hummingbird, a monkey, and a spider, ______ best viewed from the air or from the surrounding foothills.","options":[{"id":"A","label":"are"},{"id":"B","label":"being"},{"id":"C","label":"which are"},{"id":"D","label":"that are"}]}'::jsonb,102,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-047","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'a2ee513d-5193-861f-7af4-1520eb0c51f1','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the sentence needs a main verb for its plural subject, “The Nazca Lines,” and the finite verb “are” provides one after the long appositive and relative clause. Choice B is incorrect because “being” is a participle and cannot serve as the main verb. Choice C is incorrect because “which are” begins another relative clause, leaving the subject without a main verb. Choice D is incorrect because “that are” also creates a relative clause and leaves the sentence a fragment."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='a2ee513d-5193-861f-7af4-1520eb0c51f1') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('bb7d4502-8939-6117-d5f3-107211054a4e','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Founded in Geneva in 1863, the International Committee of the Red Cross, whose delegates have visited prisoners of war in conflicts around the world for more than a century, bases ______ work on the Geneva Conventions, a set of treaties that define protections for people in wartime.","options":[{"id":"A","label":"their"},{"id":"B","label":"it’s"},{"id":"C","label":"they’re"},{"id":"D","label":"its"}]}'::jsonb,103,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-048","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'bb7d4502-8939-6117-d5f3-107211054a4e','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the pronoun refers to the singular noun “the International Committee of the Red Cross,” the subject of “bases,” so the singular possessive “its” is correct. Choice A is incorrect because “their” is plural; it may seem to refer to “delegates,” but the delegates are in a relative clause, and the committee is the one that “bases” its work. Choice B is incorrect because “it’s” means “it is.” Choice C is incorrect because “they’re” means “they are.”"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='bb7d4502-8939-6117-d5f3-107211054a4e') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0b292f95-91a5-7241-2c6d-9658998e4ede','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Over the past century, many of the world’s coastal ______ have grown rapidly as people moved to seaside cities in search of work, increasing pressure on the wetlands and estuaries that surround them.","options":[{"id":"A","label":"city’s populations"},{"id":"B","label":"cities populations"},{"id":"C","label":"cities’ populations"},{"id":"D","label":"cities’ population’s"}]}'::jsonb,104,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-049","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '0b292f95-91a5-7241-2c6d-9658998e4ede','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the sentence refers to the populations belonging to many cities, so the plural possessive “cities’” is needed, and “populations” must be a plain plural noun serving as the subject of “have grown.” Choice A is incorrect because “city’s” is singular possessive, which conflicts with “many of the world’s coastal.” Choice B is incorrect because “cities” lacks the apostrophe needed to show possession. Choice D is incorrect because “population’s” is a possessive form, but the populations do not possess anything in this sentence."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='0b292f95-91a5-7241-2c6d-9658998e4ede') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0bf599e3-7ad3-d68b-fceb-209a289c51c5','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Linear B, a script used to write an early form of Greek, was deciphered in 1952 by the architect and amateur scholar Michael Ventris. Since then, scholars ______ thousands of clay tablets inscribed with the script, most of them records of goods such as grain, livestock, and textiles.","options":[{"id":"A","label":"translate"},{"id":"B","label":"had translated"},{"id":"C","label":"translated"},{"id":"D","label":"have translated"}]}'::jsonb,105,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-050","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '0bf599e3-7ad3-d68b-fceb-209a289c51c5','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because “Since then” refers to a period that began in 1952 and continues to the present, which requires the present perfect “have translated.” Choice A is incorrect because the simple present does not express an action extending from a past point to now. Choice B is incorrect because the past perfect would require a later past reference point. Choice C is incorrect because the simple past “translated” presents the work as finished at some past time, whereas “Since then” describes a period that runs from 1952 up to the present."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='0bf599e3-7ad3-d68b-fceb-209a289c51c5') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6da66043-4104-7808-7237-0d52af602481','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Sudan, Egypt’s southern neighbor, is home to more than 200 ancient pyramids, more than are found in Egypt itself. Like those built by the ancient Egyptians, ______","options":[{"id":"A","label":"the rulers of the Kingdom of Kush built pyramids that served as royal tombs."},{"id":"B","label":"the pyramids of the Kingdom of Kush served as royal tombs."},{"id":"C","label":"the Kushite kings were buried in pyramids."},{"id":"D","label":"present-day Sudan contains pyramids that served as royal tombs."}]}'::jsonb,106,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-051","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '6da66043-4104-7808-7237-0d52af602481','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because “those built by the ancient Egyptians” refers to pyramids, so the subject that follows the introductory phrase must also be pyramids; “the pyramids of the Kingdom of Kush” creates a logical comparison of pyramids with pyramids. Choice A is incorrect because it compares Egyptian pyramids with the rulers of Kush. Choice C is incorrect because it compares pyramids with Kushite kings. Choice D is incorrect because it compares pyramids with a country, present-day Sudan."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='6da66043-4104-7808-7237-0d52af602481') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('905b500f-6ae0-7b44-52c6-b4e5d2a41ef1','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"In 1972, a diver swimming off the coast of Calabria in southern Italy spotted an arm protruding from the sand of the seabed. Each of the two ancient Greek bronze statues that were then recovered from the site near the town of Riace ______ nearly two meters tall.","options":[{"id":"A","label":"stand"},{"id":"B","label":"are standing"},{"id":"C","label":"stands"},{"id":"D","label":"have stood"}]}'::jsonb,107,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-052","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '905b500f-6ae0-7b44-52c6-b4e5d2a41ef1','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the subject is “Each,” which is singular, so the singular verb “stands” agrees with it; the plural noun “statues” is in a prepositional phrase and relative clause that modify “Each.” Choice A is incorrect because “stand” is plural. Choice B is incorrect because “are standing” is plural. Choice D is incorrect because “have stood” is plural."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='905b500f-6ae0-7b44-52c6-b4e5d2a41ef1') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('022a7ea1-3bf2-7ff6-22cf-4b8d37bc3243','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"In July 2015, NASA’s New Horizons spacecraft flew past Pluto, capturing the first close-up images of the dwarf planet. The spacecraft ______ since then to explore the Kuiper Belt, and on January 1, 2019, it flew past Arrokoth, the most distant object ever visited by a spacecraft.","options":[{"id":"A","label":"continues"},{"id":"B","label":"has continued"},{"id":"C","label":"had continued"},{"id":"D","label":"continued"}]}'::jsonb,108,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-053","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '022a7ea1-3bf2-7ff6-22cf-4b8d37bc3243','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because “since then” describes an action that began in the past (after 2015) and continues to the present, which calls for the present perfect “has continued.” Choice A is incorrect because the simple present does not combine with “since then” to show continuation from a past point. Choice C is incorrect because the past perfect requires a later past reference point, which the sentence does not provide. Choice D is incorrect because the simple past presents the action as finished, which conflicts with “since then.”"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='022a7ea1-3bf2-7ff6-22cf-4b8d37bc3243') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a3493624-df6c-e673-b6c3-5aa67e8f1d4b','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Mammoth tusks grow in layers, and each layer preserves chemical traces of the place where the animal was living when that layer formed. Having analyzed these traces along the full length of a tusk from a woolly mammoth that lived in Alaska about 17,000 years ago, ______","options":[{"id":"A","label":"the mammoth was found to have walked a distance equal to circling Earth almost twice during its life."},{"id":"B","label":"it was concluded that the mammoth had walked a distance equal to circling Earth almost twice during its life."},{"id":"C","label":"the researchers’ conclusion was that the mammoth had walked a distance equal to circling Earth almost twice during its life."},{"id":"D","label":"researchers concluded that the mammoth had walked a distance equal to circling Earth almost twice during its life."}]}'::jsonb,109,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-054","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'a3493624-df6c-e673-b6c3-5aa67e8f1d4b','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the people who analyzed the traces were the researchers, and “researchers” is the subject immediately following the introductory phrase. Choice A is incorrect because it suggests that the mammoth analyzed the traces in its own tusk. Choice B is incorrect because the subject “it” is not anyone who could have analyzed the traces, so the modifier dangles. Choice C is incorrect because the subject is “conclusion,” not the researchers; the possessive “researchers’” cannot be what the phrase modifies."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='a3493624-df6c-e673-b6c3-5aa67e8f1d4b') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('240ef950-e421-5ffc-65a8-391316d53a16','24c46e8c-bf57-91c3-4ec9-181a057feb7a','question_single_choice','{"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Antarctica’s ice sheet is, on average, about two kilometers thick. Hidden beneath it ______ more than 400 lakes of liquid water, the largest of which, Lake Vostok, is comparable in size to Lake Ontario.","options":[{"id":"A","label":"lies"},{"id":"B","label":"is lying"},{"id":"C","label":"lie"},{"id":"D","label":"has lain"}]}'::jsonb,110,'{"section_type":"reading_writing","sat_domain":"grammar","sat_official_domain":"standard_english_conventions","sat_skill":"form_structure_and_sense","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"sec-fss-055","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '240ef950-e421-5ffc-65a8-391316d53a16','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because in this inverted sentence the subject, “more than 400 lakes,” follows the verb and is plural, so the plural verb “lie” is required. Choice A is incorrect because “lies” is singular; it may seem to agree with “it” or with “Lake Vostok,” but neither is the subject of this verb. Choice B is incorrect because “is lying” is singular. Choice D is incorrect because “has lain” is singular."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='240ef950-e421-5ffc-65a8-391316d53a16') on conflict do nothing;
